/*
# Seed: Firdam recipe library (204 halal recipes, 60 cuisines)

Generated by supabase/seed/build-recipes.mts from the JSON files in supabase/seed/recipes —
edit those files and re-run the script rather than editing this file.

Safe to run more than once and on existing projects: rows are matched by
name, so existing recipes are kept and only missing pieces are added.
Allergens are linked to existing rows with the same meaning (e.g. an
existing "Milk" allergen is reused for Dairy).
*/

DO $seed$
DECLARE
  missing_cols text;
  -- Some projects require these columns; "to taste" then gets 0 (the app shows it as "to taste").
  qty_required boolean := EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public'
    AND table_name = 'recipe_ingredients' AND column_name = 'quantity' AND is_nullable = 'NO');
  nutrition_required boolean := EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public'
    AND table_name = 'recipes' AND column_name IN ('calories', 'protein', 'carbs', 'fat') AND is_nullable = 'NO');
BEGIN

  SELECT string_agg(c.table_name || '.' || c.column_name, ', ' ORDER BY c.table_name, c.column_name) INTO missing_cols
  FROM information_schema.columns c
  WHERE c.table_schema = 'public' AND c.is_nullable = 'NO' AND c.column_default IS NULL AND c.is_identity = 'NO'
    AND c.is_generated = 'NEVER'
    AND ((c.table_name = 'cuisines' AND c.column_name <> ALL(ARRAY['id', 'name', 'slug']))
      OR (c.table_name = 'meal_types' AND c.column_name <> ALL(ARRAY['id', 'name', 'slug']))
      OR (c.table_name = 'difficulties' AND c.column_name <> ALL(ARRAY['id', 'name', 'slug']))
      OR (c.table_name = 'tags' AND c.column_name <> ALL(ARRAY['id', 'name', 'slug']))
      OR (c.table_name = 'allergens' AND c.column_name <> ALL(ARRAY['id', 'name', 'slug']))
      OR (c.table_name = 'ingredients' AND c.column_name <> ALL(ARRAY['id', 'name', 'slug', 'halal']))
      OR (c.table_name = 'recipes' AND c.column_name <> ALL(ARRAY['id', 'name', 'slug', 'short_description', 'cuisine_id', 'meal_type_id', 'difficulty_id', 'prep_time_minutes', 'cook_time_minutes', 'servings', 'calories', 'protein', 'carbs', 'fat', 'halal', 'is_active', 'is_featured']))
      OR (c.table_name = 'recipe_ingredients' AND c.column_name <> ALL(ARRAY['id', 'recipe_id', 'ingredient_id', 'quantity', 'unit', 'display_order']))
      OR (c.table_name = 'recipe_steps' AND c.column_name <> ALL(ARRAY['id', 'recipe_id', 'step_number', 'instruction']))
      OR (c.table_name = 'recipe_tips' AND c.column_name <> ALL(ARRAY['id', 'recipe_id', 'tip', 'display_order']))
      OR (c.table_name = 'recipe_allergens' AND c.column_name <> ALL(ARRAY['id', 'recipe_id', 'allergen_id']))
      OR (c.table_name = 'recipe_tags' AND c.column_name <> ALL(ARRAY['id', 'recipe_id', 'tag_id'])));
  IF missing_cols IS NOT NULL THEN
    RAISE EXCEPTION 'These required columns need values the recipe seed does not provide: %', missing_cols;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'cuisines' AND column_name = 'slug') THEN
