  INSERT INTO public.recipes (name, slug, short_description, cuisine_id, meal_type_id, difficulty_id,
      prep_time_minutes, cook_time_minutes, servings, calories, protein, carbs, fat, halal, is_active, is_featured)
  SELECT v.name, v.slug, v.description,
    (SELECT id FROM public.cuisines c WHERE lower(c.name) = lower(v.cuisine) LIMIT 1),
    (SELECT id FROM public.meal_types m WHERE lower(m.name) = lower(v.meal_type) LIMIT 1),
    (SELECT id FROM public.difficulties d WHERE lower(d.name) = lower(v.difficulty) LIMIT 1),
    v.prep, v.cook, v.servings,
    CASE WHEN nutrition_required THEN coalesce(v.calories::numeric, 0) ELSE v.calories::numeric END,
    CASE WHEN nutrition_required THEN coalesce(v.protein::numeric, 0) ELSE v.protein::numeric END,
    CASE WHEN nutrition_required THEN coalesce(v.carbs::numeric, 0) ELSE v.carbs::numeric END,
    CASE WHEN nutrition_required THEN coalesce(v.fat::numeric, 0) ELSE v.fat::numeric END,
    true, true, false
  FROM (VALUES
    ('Shakshuka', 'shakshuka', 'Eggs gently poached in a spiced tomato and pepper sauce — perfect with warm bread.', 'Middle Eastern', 'Breakfast', 'Easy', 10, 20, 4, 280, 15, 14, 18),
    ('Ful Medames', 'ful-medames', 'Egypt’s beloved breakfast of warm fava beans with garlic, lemon, cumin and olive oil.', 'Egyptian', 'Breakfast', 'Easy', 5, 10, 4, 260, 13, 30, 9),
    ('Menemen', 'menemen', 'Soft Turkish scrambled eggs with tomatoes and green peppers.', 'Turkish', 'Breakfast', 'Easy', 10, 12, 2, 250, 13, 10, 17),
    ('Za''atar Manakish', 'za-atar-manakish', 'Soft Lebanese flatbreads topped with za’atar and olive oil, baked until golden.', 'Lebanese', 'Breakfast', 'Medium', 80, 10, 6, 320, 7, 42, 14),
    ('Date & Tahini Overnight Oats', 'date-tahini-overnight-oats', 'Creamy no-cook oats sweetened with dates — ideal for suhoor.', 'Middle Eastern', 'Breakfast', 'Easy', 5, 0, 2, 390, 12, 58, 13),
    ('Lentil Soup (Shorbat Adas)', 'lentil-soup-shorbat-adas', 'A silky red lentil soup with cumin and lemon — a Ramadan table favourite.', 'Middle Eastern', 'Lunch', 'Easy', 10, 30, 4, 290, 16, 42, 7),
    ('Chicken Shawarma Wraps', 'chicken-shawarma-wraps', 'Spiced, juicy chicken wrapped with garlic sauce and pickles.', 'Middle Eastern', 'Lunch', 'Medium', 20, 20, 4, 520, 38, 45, 20),
    ('Fattoush Salad', 'fattoush-salad', 'Crunchy Lebanese salad with toasted pita and a tangy sumac dressing.', 'Lebanese', 'Lunch', 'Easy', 15, 5, 4, 210, 4, 22, 12),
    ('Falafel with Tahini Sauce', 'falafel-with-tahini-sauce', 'Crisp herby falafel made from soaked chickpeas, with a lemony tahini sauce.', 'Palestinian', 'Lunch', 'Medium', 25, 15, 4, 430, 15, 40, 23),
    ('Chicken Biryani', 'chicken-biryani', 'Fragrant layered rice and spiced chicken — a celebration dish for Eid and family gatherings.', 'Pakistani', 'Dinner', 'Hard', 30, 60, 6, 610, 36, 70, 19),
    ('Moroccan Chicken Tagine with Olives and Lemon', 'moroccan-chicken-tagine-with-olives-and-lemon', 'Slow-cooked chicken with preserved lemon, green olives, ginger and saffron.', 'Moroccan', 'Dinner', 'Medium', 15, 60, 4, 480, 40, 12, 29),
    ('Lamb Kofta with Yogurt Sauce', 'lamb-kofta-with-yogurt-sauce', 'Grilled spiced lamb skewers with a cool garlic and mint yogurt.', 'Turkish', 'Dinner', 'Medium', 20, 12, 4, 520, 30, 10, 40),
    ('Chicken Karahi', 'chicken-karahi', 'A rich, tomato-based Pakistani curry cooked fast in a wok-like karahi.', 'Pakistani', 'Dinner', 'Medium', 10, 35, 4, 450, 38, 9, 29),
    ('Daal Tadka', 'daal-tadka', 'Comforting yellow lentils finished with a sizzling spiced ghee tempering.', 'Indian', 'Dinner', 'Easy', 10, 30, 4, 310, 15, 40, 10),
    ('Nasi Lemak', 'nasi-lemak', 'Malaysia’s national dish: fragrant coconut rice with sambal, egg, cucumber and peanuts.', 'Malaysian', 'Lunch', 'Medium', 20, 35, 4, 560, 18, 70, 23),
    ('Beef Rendang', 'beef-rendang', 'Slow-cooked dry beef curry in coconut and spices — rich, tender and deeply flavoured.', 'Indonesian', 'Dinner', 'Hard', 25, 180, 6, 590, 40, 9, 44),
    ('Jollof Rice with Chicken', 'jollof-rice-with-chicken', 'Smoky, tomatoey West African rice served with seasoned chicken.', 'West African', 'Dinner', 'Medium', 20, 50, 6, 560, 32, 70, 16),
    ('Somali Chicken Suqaar', 'somali-chicken-suqaar', 'Quick-fried chicken pieces with vegetables and Somali xawaash spice.', 'Somali', 'Dinner', 'Easy', 15, 20, 4, 380, 34, 12, 21),
    ('Mujaddara', 'mujaddara', 'Humble lentils and rice crowned with sweet, crispy onions.', 'Lebanese', 'Lunch', 'Easy', 10, 45, 4, 420, 15, 62, 12),
    ('Maqluba', 'maqluba', 'The ‘upside-down’ pot of spiced rice, chicken and fried vegetables, flipped at the table.', 'Palestinian', 'Dinner', 'Hard', 30, 75, 6, 640, 34, 68, 26),
    ('Harira', 'harira', 'Morocco’s hearty tomato, lentil and chickpea soup traditionally served to break the fast.', 'Moroccan', 'Dinner', 'Medium', 20, 60, 6, 330, 20, 38, 10),
    ('Classic Hummus', 'classic-hummus', 'Ultra-smooth chickpea dip with tahini, lemon and garlic.', 'Middle Eastern', 'Snack', 'Easy', 10, 0, 6, 190, 7, 15, 12),
