    ('Basbousa', 'basbousa', 'Golden semolina cake soaked in fragrant syrup — an Eid favourite.', 'Egyptian', 'Snack', 'Medium', 15, 35, 12, 310, 5, 46, 12),
    ('Kheer (Rice Pudding)', 'kheer-rice-pudding', 'Creamy slow-cooked rice pudding with cardamom, pistachios and almonds.', 'Pakistani', 'Snack', 'Easy', 5, 50, 6, 260, 7, 38, 9),
    ('Lemon Herb Baked Salmon', 'lemon-herb-baked-salmon', 'A quick weeknight salmon with garlic, lemon and fresh herbs.', 'Mediterranean', 'Dinner', 'Easy', 10, 15, 4, 390, 34, 3, 26),
    ('Chicken Kabsa', 'chicken-kabsa', 'Saudi Arabia’s fragrant spiced rice with chicken, raisins and almonds.', 'Saudi', 'Dinner', 'Medium', 15, 60, 6, 590, 36, 66, 19),
    ('Msemen with Honey', 'msemen-with-honey', 'Flaky, buttery layered squares of pan-fried Moroccan flatbread, drizzled with warm honey.', 'Moroccan', 'Breakfast', 'Medium', 40, 25, 4, 520, 10, 70, 22),
    ('Baghrir (Thousand-Hole Pancakes)', 'baghrir-thousand-hole-pancakes', 'Spongy, one-sided semolina pancakes covered in tiny bubbles that soak up a warm honey and butter sauce.', 'Moroccan', 'Breakfast', 'Easy', 15, 25, 4, 380, 9, 62, 11),
    ('Bissara (Fava Bean Soup)', 'bissara-fava-bean-soup', 'A thick, silky dried fava bean soup flavoured with garlic and cumin, finished with olive oil and paprika.', 'Moroccan', 'Lunch', 'Easy', 10, 60, 4, 340, 20, 42, 11),
    ('Lamb Tagine with Prunes and Almonds', 'lamb-tagine-with-prunes-and-almonds', 'Tender lamb slow-cooked with onions, cinnamon and saffron, topped with sweet prunes, toasted almonds and sesame seeds.', 'Moroccan', 'Dinner', 'Medium', 20, 120, 4, 640, 40, 42, 33),
    ('Chicken Pastilla', 'chicken-pastilla', 'Crisp golden filo pie filled with saffron-spiced shredded chicken, egg and almonds, dusted with cinnamon and icing sugar.', 'Moroccan', 'Dinner', 'Hard', 60, 70, 6, 610, 33, 42, 34),
    ('Couscous with Seven Vegetables', 'couscous-with-seven-vegetables', 'Fluffy steamed couscous crowned with tender beef or lamb and seven vegetables in a golden, gently spiced broth.', 'Moroccan', 'Dinner', 'Medium', 30, 90, 6, 560, 28, 78, 16),
    ('Zaalouk (Aubergine Salad)', 'zaalouk-aubergine-salad', 'A warm, smoky Moroccan dip of cooked aubergine and tomato with garlic, cumin and paprika.', 'Moroccan', 'Lunch', 'Easy', 15, 40, 4, 180, 3, 16, 12),
    ('Kefta Mkaouara (Meatball Tagine with Eggs)', 'kefta-mkaouara-meatball-tagine-with-eggs', 'Spiced beef meatballs simmered in a garlicky tomato sauce with eggs gently poached on top.', 'Moroccan', 'Dinner', 'Easy', 25, 35, 4, 480, 32, 14, 33),
    ('Chorba Frik (Lamb & Freekeh Soup)', 'chorba-frik-lamb-freekeh-soup', 'Algeria''s Ramadan favourite: a rich tomato soup of lamb, chickpeas and cracked green wheat with fresh coriander and mint.', 'Algerian', 'Lunch', 'Medium', 20, 75, 6, 360, 25, 34, 14),
    ('Mhadjeb (Stuffed Semolina Flatbread)', 'mhadjeb-stuffed-semolina-flatbread', 'Thin, crisp semolina pockets stuffed with a slow-cooked tomato, onion and pepper filling.', 'Algerian', 'Breakfast', 'Medium', 40, 30, 4, 420, 9, 58, 17),
    ('Chtitha Djej (Spiced Chicken Stew)', 'chtitha-djej-spiced-chicken-stew', 'A fiery Algerian chicken stew with chickpeas in a garlicky red pepper and tomato sauce.', 'Algerian', 'Dinner', 'Easy', 15, 50, 4, 450, 36, 24, 24),
    ('Makrout (Date Semolina Cookies)', 'makrout-date-semolina-cookies', 'Diamond-shaped semolina cookies filled with spiced date paste, fried until golden and dipped in honey. Makes about 24 pieces.', 'Algerian', 'Snack', 'Medium', 45, 25, 24, 170, 2, 26, 7),
    ('Lablabi (Chickpea Soup)', 'lablabi-chickpea-soup', 'A warming Tunisian street-food chickpea soup, ladled over torn bread with garlic, cumin, harissa, a soft egg and olive oil.', 'Tunisian', 'Breakfast', 'Easy', 15, 30, 4, 420, 17, 52, 16),
    ('Brik à l''Oeuf (Egg Brik)', 'brik-a-l-oeuf-egg-brik', 'Crisp, golden pastry triangles hiding a tuna and parsley filling and a runny egg yolk.', 'Tunisian', 'Lunch', 'Medium', 20, 15, 4, 340, 17, 24, 20),
    ('Tunisian Fish Couscous', 'tunisian-fish-couscous', 'Fluffy couscous topped with fish and vegetables in a fragrant, spicy tomato and harissa broth.', 'Tunisian', 'Dinner', 'Medium', 25, 60, 4, 590, 38, 70, 17),
    ('Sharba Libiya (Lamb & Orzo Soup)', 'sharba-libiya-lamb-orzo-soup', 'Libya''s beloved Ramadan soup: tender lamb, orzo pasta and a tangy tomato broth with mint and lemon.', 'Libyan', 'Lunch', 'Easy', 15, 60, 6, 340, 22, 32, 14),
    ('Koshari', 'koshari', 'Egypt''s national street food: rice, lentils and macaroni layered with spicy tomato sauce, chickpeas and crispy fried onions.', 'Egyptian', 'Lunch', 'Medium', 25, 50, 4, 640, 20, 108, 15),
    ('Molokhia with Chicken', 'molokhia-with-chicken', 'A silky green jute leaf stew with garlic and coriander, served over rice with tender poached chicken.', 'Egyptian', 'Dinner', 'Medium', 20, 60, 4, 520, 38, 42, 22),
    ('Hawawshi (Spiced Beef Bread)', 'hawawshi-spiced-beef-bread', 'Pita stuffed with juicy spiced minced beef, onion and pepper, baked until crisp outside and succulent inside.', 'Egyptian', 'Lunch', 'Easy', 20, 25, 4, 560, 28, 52, 26),
    ('Om Ali (Bread Pudding)', 'om-ali-bread-pudding', 'Egypt''s famous warm pudding of flaky pastry, nuts and raisins baked in sweet creamy milk until bubbling and golden.', 'Egyptian', 'Snack', 'Easy', 15, 25, 6, 520, 12, 52, 30),
    ('Eggah (Herb Omelette)', 'eggah-herb-omelette', 'A thick, fluffy baked omelette packed with parsley, coriander and spring onions, served in wedges.', 'Egyptian', 'Breakfast', 'Easy', 10, 20, 4, 250, 15, 6, 18),
    ('Mullah Bamia (Okra Stew)', 'mullah-bamia-okra-stew', 'A rich Sudanese stew of lamb and okra in a tomato and garlic sauce with a dry-okra and onion flavour, served with rice or kisra.', 'Sudanese', 'Dinner', 'Medium', 20, 70, 4, 460, 30, 24, 26),
    ('Labneh with Za''atar and Olive Oil', 'labneh-with-za-atar-and-olive-oil', 'Thick, tangy strained yogurt swirled onto a plate and finished with fragrant za''atar and golden olive oil, perfect scooped up with warm bread.', 'Lebanese', 'Breakfast', 'Easy', 15, 0, 4, 230, 11, 8, 17),
    ('Fatteh Hummus', 'fatteh-hummus', 'Crisp toasted pita layered with warm chickpeas and garlicky yogurt tahini sauce, finished with sizzling spiced butter and toasted pine nuts.', 'Syrian', 'Breakfast', 'Easy', 15, 15, 4, 520, 21, 52, 26),
    ('Manaqish Jibneh (Cheese Flatbread)', 'manaqish-jibneh-cheese-flatbread', 'Soft, chewy flatbreads baked with a layer of melting white cheese, just like the bakeries of Beirut.', 'Lebanese', 'Breakfast', 'Medium', 100, 12, 4, 480, 20, 56, 19),
    ('Mfarakeh (Potato & Egg Scramble)', 'mfarakeh-potato-egg-scramble', 'Golden pan-fried potatoes folded into softly scrambled eggs with sweet onion and a hint of allspice, a comforting Lebanese breakfast.', 'Lebanese', 'Breakfast', 'Easy', 10, 25, 4, 320, 13, 28, 18),
    ('Tabbouleh', 'tabbouleh', 'A bright, parsley-heavy Lebanese salad with juicy tomato, mint and a little fine bulgur, dressed with lemon and olive oil.', 'Lebanese', 'Lunch', 'Easy', 30, 0, 4, 190, 4, 20, 11),
    ('Warak Enab (Stuffed Vine Leaves)', 'warak-enab-stuffed-vine-leaves', 'Tender vine leaves rolled around spiced lamb and rice, simmered in lemony broth until soft and tangy.', 'Lebanese', 'Lunch', 'Hard', 60, 75, 6, 310, 13, 30, 15),
    ('Adas bi Hamod (Lentil & Chard Soup)', 'adas-bi-hamod-lentil-chard-soup', 'A hearty Lebanese soup of brown lentils, silverbeet and potato brightened with plenty of lemon and garlic.', 'Lebanese', 'Lunch', 'Easy', 15, 40, 4, 290, 15, 40, 8),
    ('Arayes (Grilled Meat-Stuffed Pita)', 'arayes-grilled-meat-stuffed-pita', 'Pita pockets packed with spiced lamb and beef mince, grilled until crisp outside and juicy inside.', 'Lebanese', 'Lunch', 'Easy', 20, 15, 4, 520, 29, 40, 26),
    ('Sfeeha (Open Meat Pies)', 'sfeeha-open-meat-pies', 'Little open-faced pies topped with tangy spiced minced lamb, tomato and pomegranate molasses.', 'Syrian', 'Lunch', 'Medium', 90, 15, 4, 480, 22, 46, 22),
    ('Kibbeh bil Sanieh (Baked Kibbeh)', 'kibbeh-bil-sanieh-baked-kibbeh', 'Layers of spiced lamb and bulgur shell around a sweet, nutty minced lamb filling, scored in diamonds and baked until golden.', 'Lebanese', 'Dinner', 'Hard', 60, 40, 6, 450, 28, 26, 26),
