    ('Moi Moi (Steamed Bean Pudding)', 'moi-moi-steamed-bean-pudding', 'A soft, savoury steamed pudding of blended black-eyed beans, peppers and onion, studded with boiled egg and fish. Makes 6 portions.', 'Nigerian', 'Lunch', 'Medium', 40, 50, 6, 310, 15, 26, 16),
    ('Waakye (Rice & Beans)', 'waakye-rice-beans', 'Ghana''s beloved rice and black-eyed beans, tinted deep reddish-brown with millet leaf sheaths and served with boiled egg, gari, fried plantain and shito.', 'Ghanaian', 'Lunch', 'Medium', 20, 75, 4, 540, 19, 80, 15),
    ('Sukuma Wiki with Ugali', 'sukuma-wiki-with-ugali', 'Quick-sauteed collard greens with tomato and onion, served with firm, white maize-meal ugali. Kenya''s everyday family meal.', 'Kenyan', 'Lunch', 'Easy', 15, 25, 4, 380, 9, 68, 8),
    ('Bariis Iskukaris (Spiced Rice with Lamb)', 'bariis-iskukaris-spiced-rice-with-lamb', 'Somalia''s fragrant festive rice, cooked with lamb in a blend of cumin, cardamom, cloves and cinnamon and studded with raisins.', 'Somali', 'Dinner', 'Medium', 20, 90, 4, 680, 34, 78, 24),
    ('Doro Wat (Chicken Stew)', 'doro-wat-chicken-stew', 'Ethiopia''s national dish: chicken slowly simmered in a rich berbere and onion sauce with spiced butter and hard-boiled eggs.', 'Ethiopian', 'Dinner', 'Medium', 25, 90, 4, 520, 42, 20, 30),
    ('Zigni (Spiced Beef Stew)', 'zigni-spiced-beef-stew', 'A fiery Eritrean beef stew in a thick berbere and tomato sauce, slow-cooked until the meat is meltingly tender.', 'Eritrean', 'Dinner', 'Medium', 20, 110, 4, 480, 38, 14, 29),
    ('Egusi Soup', 'egusi-soup', 'A thick, nutty Nigerian soup of ground melon seeds, palm oil, leafy greens and tender beef, traditionally eaten with pounded yam or eba.', 'Nigerian', 'Dinner', 'Medium', 20, 50, 4, 560, 34, 10, 42),
    ('Suya (Spiced Beef Skewers)', 'suya-spiced-beef-skewers', 'Thinly sliced beef coated in smoky, peanut-based yaji spice and grilled until charred, the famous Nigerian street food.', 'Nigerian', 'Dinner', 'Easy', 30, 15, 4, 420, 38, 9, 26),
    ('Thieboudienne (Fish & Rice)', 'thieboudienne-fish-rice', 'Senegal''s national dish: whole-spice stuffed fish simmered with vegetables in tomato broth, then rice cooked in the same flavourful liquid.', 'Senegalese', 'Dinner', 'Hard', 40, 75, 4, 640, 38, 78, 20),
    ('Chicken Yassa', 'chicken-yassa', 'Chicken marinated in lemon, mustard and a mountain of onions, grilled then braised in the sweet-sharp onion sauce and served over rice.', 'Senegalese', 'Dinner', 'Easy', 20, 55, 4, 530, 38, 16, 33),
    ('Mafe (Peanut Stew)', 'mafe-peanut-stew', 'A velvety West African stew of beef and root vegetables in a rich peanut and tomato sauce, served over steamed rice.', 'Senegalese', 'Dinner', 'Medium', 20, 80, 4, 610, 35, 30, 39),
    ('Swahili Pilau', 'swahili-pilau', 'The aromatic spiced rice of the Kenyan coast, cooked with beef in pilau masala, caramelised onions and potatoes.', 'Kenyan', 'Dinner', 'Medium', 20, 85, 4, 660, 32, 80, 22),
    ('Samaki wa Kupaka (Coconut Fish Curry)', 'samaki-wa-kupaka-coconut-fish-curry', 'Grilled fish smothered in a tangy, creamy coconut and tamarind sauce, a signature dish of the Swahili coast.', 'Tanzanian', 'Dinner', 'Medium', 20, 30, 4, 480, 36, 12, 32),
    ('Sambusa', 'sambusa', 'Crisp triangular pastries filled with spiced minced beef, onion and herbs, a must-have at Ramadan iftar tables. Makes about 18.', 'Somali', 'Snack', 'Medium', 45, 25, 6, 290, 13, 26, 15),
    ('Kelewele (Spiced Plantain)', 'kelewele-spiced-plantain', 'Cubes of ripe plantain tossed in ginger, chilli and spices then fried until sticky and caramelised, Ghana''s favourite street snack.', 'Ghanaian', 'Snack', 'Easy', 15, 15, 4, 340, 2, 52, 15),
    ('Mandazi', 'mandazi', 'Lightly sweet, cardamom-scented East African doughnuts, fried until puffed and golden, perfect with chai. Makes about 16 pieces, serving 8.', 'Tanzanian', 'Snack', 'Easy', 20, 20, 8, 270, 5, 35, 12),
    ('Puff-Puff', 'puff-puff', 'Soft, chewy, golden balls of sweetened yeast dough deep-fried until puffed, Nigeria''s favourite party snack. Makes about 24 balls.', 'Nigerian', 'Snack', 'Easy', 75, 20, 6, 280, 5, 43, 10),
    ('Fluffy Pancakes with Berries', 'fluffy-pancakes-with-berries', 'Thick, golden American-style pancakes stacked high and topped with juicy fresh berries and maple syrup.', 'American', 'Breakfast', 'Easy', 10, 15, 4, 380, 11, 55, 13),
    ('Spinach & Feta Omelette', 'spinach-feta-omelette', 'A light, protein-packed omelette folded around wilted spinach and salty feta, ready in under 20 minutes.', 'Mediterranean', 'Breakfast', 'Easy', 10, 8, 2, 340, 22, 5, 26),
    ('Greek Yogurt Parfait with Granola', 'greek-yogurt-parfait-with-granola', 'Creamy Greek yogurt layered with crunchy granola, fresh berries and a drizzle of honey for a no-cook breakfast.', 'Mediterranean', 'Breakfast', 'Easy', 10, 0, 4, 320, 16, 42, 10),
    ('Beef & Egg Breakfast Burrito', 'beef-egg-breakfast-burrito', 'Large warm tortillas stuffed with spiced minced beef, fluffy scrambled eggs, melted cheese and fresh salsa.', 'Mexican', 'Breakfast', 'Easy', 15, 15, 4, 520, 31, 40, 26),
    ('Spaghetti Bolognese', 'spaghetti-bolognese', 'A rich, slow-simmered halal beef ragu with tomatoes and herbs, served over spaghetti and finished with parmesan.', 'Italian', 'Dinner', 'Easy', 15, 60, 4, 610, 35, 70, 21),
    ('Chicken Alfredo Pasta', 'chicken-alfredo-pasta', 'Tender pan-seared chicken and fettuccine tossed in a silky garlic, cream and parmesan sauce.', 'Italian', 'Dinner', 'Easy', 10, 25, 4, 720, 42, 62, 35),
    ('Homemade Margherita Pizza', 'homemade-margherita-pizza', 'Classic pizza with a crisp, chewy homemade base, simple tomato sauce, creamy mozzarella and fresh basil.', 'Italian', 'Dinner', 'Medium', 100, 12, 4, 560, 24, 78, 17),
    ('Beef Lasagne', 'beef-lasagne', 'Layers of pasta, rich beef ragu and creamy white sauce, baked until bubbling with a golden cheesy top.', 'Italian', 'Dinner', 'Medium', 30, 90, 6, 640, 36, 46, 34),
    ('Chicken Souvlaki with Tzatziki', 'chicken-souvlaki-with-tzatziki', 'Lemony, herby grilled chicken skewers served in warm pita with cool cucumber tzatziki and fresh salad.', 'Greek', 'Dinner', 'Easy', 20, 15, 4, 480, 42, 36, 18),
    ('Chicken & Prawn Paella', 'chicken-prawn-paella', 'Saffron-scented Spanish rice with chicken, prawns and peas, flavoured with smoked paprika for a deep, smoky taste.', 'Spanish', 'Dinner', 'Medium', 20, 40, 4, 560, 40, 66, 14),
    ('Minestrone Soup', 'minestrone-soup', 'A hearty Italian vegetable soup with beans and small pasta in a fragrant tomato broth.', 'Italian', 'Lunch', 'Easy', 15, 35, 4, 290, 12, 46, 7),
    ('Ratatouille', 'ratatouille', 'A Provençal stew of aubergine, courgette, peppers and tomatoes slowly cooked in olive oil with garlic and herbs.', 'French', 'Lunch', 'Easy', 20, 50, 4, 210, 5, 24, 11),
    ('Tuna Niçoise Salad', 'tuna-nicoise-salad', 'A colourful French salad of tuna, boiled eggs, green beans, potatoes, tomatoes and olives with a mustard dressing.', 'French', 'Lunch', 'Easy', 20, 15, 4, 420, 30, 24, 22),
    ('Beef Tacos', 'beef-tacos', 'Soft taco shells filled with smoky spiced minced beef, crisp lettuce, tomato, cheese and a squeeze of lime.', 'Mexican', 'Lunch', 'Easy', 15, 15, 4, 480, 28, 38, 23),
    ('Shepherd''s Pie with Lamb', 'shepherd-s-pie-with-lamb', 'A comforting British classic of rich minced lamb and vegetables under a golden, buttery mashed potato crust.', 'British', 'Dinner', 'Easy', 25, 60, 4, 590, 33, 44, 31),
    ('Oven-Baked Fish and Chips', 'oven-baked-fish-and-chips', 'Crispy breadcrumb-coated cod fillets with golden oven chips and minty crushed peas, a lighter take on the British favourite.', 'British', 'Dinner', 'Easy', 20, 40, 4, 520, 38, 56, 15),
    ('Homemade Beef Burgers', 'homemade-beef-burgers', 'Thick, juicy halal beef patties with melted cheese, crisp salad and sauce in toasted burger buns.', 'American', 'Dinner', 'Easy', 20, 12, 4, 640, 38, 42, 34),
    ('Chicken Fajitas', 'chicken-fajitas', 'Sizzling spiced chicken strips with soft peppers and onions, wrapped in warm tortillas with guacamole and soured cream.', 'Mexican', 'Dinner', 'Easy', 15, 15, 4, 450, 38, 40, 14),
    ('Jerk Chicken with Rice and Peas', 'jerk-chicken-with-rice-and-peas', 'Fiery, fragrant Jamaican jerk chicken roasted until sticky and charred, served with coconut rice and kidney beans.', 'Caribbean', 'Dinner', 'Medium', 20, 60, 4, 680, 44, 68, 24),
    ('Pão de Queijo (Cheese Bread)', 'pao-de-queijo-cheese-bread', 'Chewy, gluten-free Brazilian cheese puffs with a crisp shell and a soft, cheesy middle; this makes about 20 small rolls.', 'Brazilian', 'Snack', 'Easy', 15, 25, 20, 85, 3, 9, 4),
    ('Banana Bread', 'banana-bread', 'A moist, golden banana loaf with a tender crumb and a hint of cinnamon; one loaf makes 10 slices.', 'American', 'Snack', 'Easy', 15, 55, 10, 290, 4, 42, 12)
  ) AS v(name, slug, description, cuisine, meal_type, difficulty, prep, cook, servings, calories, protein, carbs, fat)
  WHERE NOT EXISTS (SELECT 1 FROM public.recipes r WHERE lower(r.name) = lower(v.name) OR r.slug = v.slug);

  UPDATE public.recipes r SET image_prompt = v.prompt FROM (VALUES
    ('Shakshuka', 'Shakshuka (Middle Eastern). Eggs gently poached in a spiced tomato and pepper sauce — perfect with warm bread.'),
