    ('Kheer (Rice Pudding)', 'Kheer (Rice Pudding) (Pakistani). Creamy slow-cooked rice pudding with cardamom, pistachios and almonds.'),
    ('Lemon Herb Baked Salmon', 'Lemon Herb Baked Salmon (Mediterranean). A quick weeknight salmon with garlic, lemon and fresh herbs.'),
    ('Chicken Kabsa', 'Chicken Kabsa (Saudi). Saudi Arabia’s fragrant spiced rice with chicken, raisins and almonds.'),
    ('Msemen with Honey', 'Msemen with Honey (Moroccan). A stack of golden, square layered flatbreads on a ceramic plate with honey being drizzled over the top. A small pot of honey and a glass of mint tea sit alongside.'),
    ('Baghrir (Thousand-Hole Pancakes)', 'Baghrir (Thousand-Hole Pancakes) (Moroccan). A plate of pale golden pancakes with their honeycomb surface of tiny holes facing up, glistening with honey butter. Folded or stacked in a loose pile on a white plate.'),
    ('Bissara (Fava Bean Soup)', 'Bissara (Fava Bean Soup) (Moroccan). A deep earthenware bowl of smooth, pale green-beige soup with a golden pool of olive oil and a dusting of red paprika and cumin. Served with a lemon wedge and warm bread beside it.'),
    ('Lamb Tagine with Prunes and Almonds', 'Lamb Tagine with Prunes and Almonds (Moroccan). A terracotta tagine dish of glossy dark-brown lamb with dark prunes, scattered golden almonds, sesame seeds and green coriander. A wooden spoon and flatbread sit beside it.'),
    ('Chicken Pastilla', 'Chicken Pastilla (Moroccan). A round golden-brown filo pie dusted with a lattice of white icing sugar and cinnamon on a large platter. One slice is cut out showing layers of shredded chicken and egg.'),
    ('Couscous with Seven Vegetables', 'Couscous with Seven Vegetables (Moroccan). A large round platter of fluffy couscous topped with a colourful arrangement of orange carrots, pumpkin, green courgette, cabbage, chickpeas and meat. A bowl of golden broth sits beside it.'),
    ('Zaalouk (Aubergine Salad)', 'Zaalouk (Aubergine Salad) (Moroccan). A shallow bowl of dark, rich aubergine and tomato spread glistening with olive oil, sprinkled with paprika and fresh herbs. Served with triangles of flatbread.'),
    ('Kefta Mkaouara (Meatball Tagine with Eggs)', 'Kefta Mkaouara (Meatball Tagine with Eggs) (Moroccan). A wide terracotta dish of meatballs in bright red tomato sauce with four runny-yolked eggs on top, scattered with green herbs. Torn bread alongside.'),
    ('Chorba Frik (Lamb & Freekeh Soup)', 'Chorba Frik (Lamb & Freekeh Soup) (Algerian). A deep bowl of thick red-orange soup with tender lamb cubes, chickpeas and cracked green wheat, topped with chopped fresh coriander and mint. A lemon wedge on the rim.'),
    ('Mhadjeb (Stuffed Semolina Flatbread)', 'Mhadjeb (Stuffed Semolina Flatbread) (Algerian). A pile of crisp golden rectangular flatbreads on a wooden board, one cut open to show a bright red tomato and onion filling. A glass of mint tea beside.'),
    ('Chtitha Djej (Spiced Chicken Stew)', 'Chtitha Djej (Spiced Chicken Stew) (Algerian). A shallow dish of chicken pieces in a glossy red-orange sauce with chickpeas and green olives, topped with fresh coriander leaves. Crusty bread on the side.'),
    ('Makrout (Date Semolina Cookies)', 'Makrout (Date Semolina Cookies) (Algerian). Rows of golden diamond-shaped cookies glistening with honey, one broken open to reveal dark date filling. Arranged on a patterned plate.'),
    ('Lablabi (Chickpea Soup)', 'Lablabi (Chickpea Soup) (Tunisian). A rustic bowl of golden chickpea soup over chunks of bread, topped with a halved soft-boiled egg, flaked tuna, capers, olives and a swirl of red harissa oil.'),
    ('Brik à l''Oeuf (Egg Brik)', 'Brik à l''Oeuf (Egg Brik) (Tunisian). Two crisp golden triangular pastries on a plate, one cut open with a bright runny egg yolk and tuna filling. Garnished with parsley and a lemon wedge.'),
    ('Tunisian Fish Couscous', 'Tunisian Fish Couscous (Tunisian). A large platter of fluffy couscous topped with chunks of white fish, orange carrots, potatoes and courgettes in a red spicy broth. A lemon wedge on the side.'),
    ('Sharba Libiya (Lamb & Orzo Soup)', 'Sharba Libiya (Lamb & Orzo Soup) (Libyan). A deep bowl of red-brown soup with lamb cubes, orzo and chickpeas, sprinkled with dried mint and parsley. A lemon wedge on the rim and bread alongside.'),
    ('Koshari', 'Koshari (Egyptian). A deep bowl layered with rice, brown lentils, macaroni and chickpeas, covered in red tomato sauce and a generous heap of crispy fried onions.'),
    ('Molokhia with Chicken', 'Molokhia with Chicken (Egyptian). A bowl of vivid dark green molokhia stew next to a plate of white rice and golden browned chicken pieces, with a lemon wedge on the side.'),
    ('Hawawshi (Spiced Beef Bread)', 'Hawawshi (Spiced Beef Bread) (Egyptian). Several crisp golden pita pockets cut into diagonal wedges showing juicy spiced beef filling, on a board with sliced tomato and parsley.'),
    ('Om Ali (Bread Pudding)', 'Om Ali (Bread Pudding) (Egyptian). A bubbling golden-brown bread pudding in a round baking dish with flaky pastry peaks, chopped green pistachios, raisins and a dusting of cinnamon.'),
    ('Eggah (Herb Omelette)', 'Eggah (Herb Omelette) (Egyptian). A thick, golden-green herb omelette in a round pan, cut into wedges to show the flecks of parsley and coriander. Served with pita and sliced tomato.'),
    ('Mullah Bamia (Okra Stew)', 'Mullah Bamia (Okra Stew) (Sudanese). A bowl of thick red-brown stew with lamb pieces and green okra pods, served alongside a mound of fluffy white rice on a round plate.'),
    ('Labneh with Za''atar and Olive Oil', 'Labneh with Za''atar and Olive Oil (Lebanese). A wide white plate of creamy labneh swirled with olive oil and dusted green-brown with za''atar, ringed with cherry tomatoes, cucumber slices, olives and mint, with warm pita alongside.'),
    ('Fatteh Hummus', 'Fatteh Hummus (Syrian). A shallow rustic bowl layered with golden pita, whole chickpeas and white yogurt sauce, topped with glistening red-orange spiced butter, toasted pine nuts and green parsley.'),
    ('Manaqish Jibneh (Cheese Flatbread)', 'Manaqish Jibneh (Cheese Flatbread) (Lebanese). Four golden round flatbreads with bubbling, lightly browned white cheese and crisp edges, served on a wooden board with fresh mint, tomatoes and cucumber.'),
    ('Mfarakeh (Potato & Egg Scramble)', 'Mfarakeh (Potato & Egg Scramble) (Lebanese). A cast-iron pan of fluffy yellow egg threaded with golden potato cubes and soft onion, scattered with red sumac and fresh green parsley.'),
    ('Tabbouleh', 'Tabbouleh (Lebanese). A shallow white bowl piled with vivid green finely chopped parsley flecked with red tomato cubes, with crisp lettuce leaves and lemon wedges at the side.'),
    ('Warak Enab (Stuffed Vine Leaves)', 'Warak Enab (Stuffed Vine Leaves) (Lebanese). A round platter of neatly packed dark green vine leaf rolls arranged in a spiral with lemon wedges and fresh mint, glistening with olive oil.'),
    ('Adas bi Hamod (Lentil & Chard Soup)', 'Adas bi Hamod (Lentil & Chard Soup) (Lebanese). A deep earthenware bowl of rustic brown lentil soup flecked with deep green chard, topped with a drizzle of olive oil and a lemon wedge on the rim.'),
    ('Arayes (Grilled Meat-Stuffed Pita)', 'Arayes (Grilled Meat-Stuffed Pita) (Lebanese). Golden-charred pita halves cut into wedges showing a juicy spiced meat filling, on a wooden board with a bowl of yogurt and fresh parsley.'),
    ('Sfeeha (Open Meat Pies)', 'Sfeeha (Open Meat Pies) (Syrian). A tray of small round golden pies topped with rust-coloured spiced lamb, pine nuts and glossy tomato, with lemon wedges and parsley.'),
    ('Kibbeh bil Sanieh (Baked Kibbeh)', 'Kibbeh bil Sanieh (Baked Kibbeh) (Lebanese). A square baking dish of golden-brown kibbeh scored into neat diamonds, with a few pieces lifted to show the spiced lamb and pine nut filling, served with a bowl of yogurt.'),
    ('Shish Tawook', 'Shish Tawook (Lebanese). Skewers of golden-orange charred chicken cubes alternating with red onion on a platter, with a bowl of white garlic sauce and lemon wedges.'),
