    ('Shakriyeh (Lamb in Yogurt Sauce)', 'Shakriyeh (Lamb in Yogurt Sauce) (Syrian). A deep bowl of creamy white yogurt sauce with chunks of tender lamb, set on fluffy white rice and topped with golden pine nuts and dried mint.'),
    ('Musakhan (Sumac Onion Chicken)', 'Musakhan (Sumac Onion Chicken) (Palestinian). Golden roast chicken pieces on a bed of glistening purple-red sumac onions over flatbread, with pine nuts and a bowl of yogurt.'),
