    ('Iraqi Dolma', 'Iraqi Dolma (Iraqi). A big platter of assorted glossy stuffed peppers, tomatoes, aubergines, vine leaf rolls and onion rolls in rich reddish-brown colours, garnished with parsley.'),
    ('Masgouf-Style Baked Fish', 'Masgouf-Style Baked Fish (Iraqi). A whole butterflied fish with crisp golden-brown skin on a tray of roasted red tomatoes and onions, garnished with parsley and lemon.'),
