    ('Maamoul (Date-Filled Cookies)', 'Maamoul (Date-Filled Cookies) (Lebanese). Rows of pale, intricately patterned domed cookies dusted with icing sugar on a white tray, one broken open to reveal dark date filling.'),
    ('Balaleet (Sweet Vermicelli with Eggs)', 'Balaleet (Sweet Vermicelli with Eggs) (Emirati). A golden-orange mound of glossy vermicelli on a white plate, topped with a pale yellow omelette and a sprinkle of crushed saffron threads.'),
    ('Chebab (Saffron Pancakes)', 'Chebab (Saffron Pancakes) (Emirati). A stack of golden, softly speckled saffron pancakes on a plate, drizzled with dark date syrup with a small dish of cream cheese beside.'),
    ('Kuku Sabzi (Herb Frittata)', 'Kuku Sabzi (Herb Frittata) (Iranian). A thick round green frittata cut into wedges in a black skillet, flecked with walnuts and red barberries, with a bowl of white yogurt alongside.'),
    ('Harees (Wheat & Chicken Porridge)', 'Harees (Wheat & Chicken Porridge) (Emirati). A shallow bowl of creamy beige harees with a pool of golden ghee in the centre, dusted with cinnamon, on a rustic table.'),
