    ('Fesenjan (Pomegranate Walnut Chicken)', 'Fesenjan (Pomegranate Walnut Chicken) (Iranian). Glossy dark brown walnut sauce coating pieces of chicken, served next to white rice and sprinkled with ruby pomegranate seeds.'),
    ('Jeweled Rice (Javaher Polow)', 'Jeweled Rice (Javaher Polow) (Iranian). A tall mound of yellow-white rice jewelled with orange peel, red barberries, green pistachios and almonds on a silver platter.'),
    ('Joojeh Kabab (Saffron Chicken Kebab)', 'Joojeh Kabab (Saffron Chicken Kebab) (Iranian). Golden saffron-yellow chicken skewers with charred edges on a plate alongside blistered grilled tomatoes and flatbread.'),
    ('Kabuli Pulao', 'Kabuli Pulao (Afghan). A brown glossy mound of rice topped with thin orange carrot strips, plump raisins and green pistachios, with lamb pieces on the side.'),
    ('Mantu (Beef Dumplings)', 'Mantu (Beef Dumplings) (Afghan). Plump steamed dumplings on a bed of white garlic yogurt, topped with red-brown tomato sauce and dried mint.'),
    ('Mutabbaq (Stuffed Pan-Fried Pastry)', 'Mutabbaq (Stuffed Pan-Fried Pastry) (Saudi). Golden crispy square pastries cut open to reveal a spiced beef and egg filling, served on a plate with lemon wedges.'),
    ('Luqaimat (Date Syrup Dumplings)', 'Luqaimat (Date Syrup Dumplings) (Emirati). A pile of glossy golden-brown round dumplings drizzled with dark date syrup and scattered with sesame seeds on a white plate.'),
    ('Sholeh Zard (Saffron Rice Pudding)', 'Sholeh Zard (Saffron Rice Pudding) (Iranian). A golden-yellow pudding in a shallow dish decorated with lines of brown cinnamon, green pistachio slivers and almond flakes.'),
    ('Shor Nakhod (Chickpea & Potato Salad)', 'Shor Nakhod (Chickpea & Potato Salad) (Afghan). A bowl of golden chickpeas and potato cubes tossed with red onion, green herbs and chilli flakes, with a lemon wedge.'),
    ('Aloo Paratha', 'Aloo Paratha (Pakistani). Two golden-brown parathas with crisp brown spots stacked on a plate, one folded in half, with a bowl of white yogurt and a pat of ghee melting on top.'),
    ('Masala Omelette', 'Masala Omelette (Indian). A golden folded omelette flecked with red onion, tomato and green coriander on a white plate, served with buttered toast triangles.'),
    ('Mas Huni (Tuna & Coconut) with Roshi', 'Mas Huni (Tuna & Coconut) with Roshi (Maldivian). A mound of pale pink tuna and coconut mix flecked with green chilli and onion, beside a stack of thin golden roshi flatbreads and a lime wedge on a wooden board.'),
    ('Chapli Kebab', 'Chapli Kebab (Pakistani). Rustic round dark-brown chapli kebabs stacked on a plate with naan, lemon wedges, sliced onion rings and green chutney.'),
    ('Chana Masala', 'Chana Masala (Indian). A bowl of glossy golden-brown chickpeas in thick spiced gravy topped with fresh coriander, sliced red onion and a green chilli, beside basmati rice.'),
    ('Rajma Chawal', 'Rajma Chawal (Indian). A white plate with fluffy basmati rice next to a ladle of dark red kidney bean curry, garnished with chopped coriander.'),
    ('Aloo Gobi', 'Aloo Gobi (Indian). Golden-yellow cauliflower florets and potato cubes in a black karahi, scattered with fresh coriander and green chilli slivers.'),
    ('Bhindi Masala (Okra Stir-Fry)', 'Bhindi Masala (Okra Stir-Fry) (Indian). A shallow dish of bright green okra pieces glazed with golden-brown onions and spices, garnished with fresh coriander.'),
    ('Khichuri', 'Khichuri (Bangladeshi). A deep bowl of soft golden khichuri topped with a swirl of ghee, green chilli and chopped coriander, with a fried egg on the side.'),
    ('Nihari', 'Nihari (Pakistani). A deep bowl of glossy mahogany beef nihari with a bone, topped with ginger matchsticks, green chilli, coriander and crisp fried onions, with naan alongside.'),
    ('Haleem', 'Haleem (Pakistani). A wide bowl of thick golden-brown haleem crowned with fried onions, ginger matchsticks, green chilli, mint and a lemon wedge.'),
    ('Seekh Kebab', 'Seekh Kebab (Pakistani). Long charred seekh kebabs on metal skewers resting on a platter with naan, sliced red onion, lemon wedges and green chutney.'),
    ('Yakhni Pulao (Chicken Pulao)', 'Yakhni Pulao (Chicken Pulao) (Pakistani). A platter of fluffy long-grain rice with browned chicken pieces, whole spices and caramelised onions on top, served with a bowl of raita.'),
    ('Butter Chicken', 'Butter Chicken (Indian). A bowl of creamy orange-red butter chicken with charred chicken pieces, a swirl of cream and coriander leaves, with naan on the side.'),
    ('Chicken Tikka Masala', 'Chicken Tikka Masala (Indian). A rich orange tikka masala with charred chicken chunks in a shallow bowl, drizzled with cream and topped with coriander, beside basmati rice.'),
    ('Palak Paneer', 'Palak Paneer (Indian). A bowl of bright green creamy spinach curry with golden paneer cubes and a swirl of cream, served with a charred roti.'),
    ('Beef Bhuna', 'Beef Bhuna (Bangladeshi). Dark glossy chunks of beef bhuna with thick masala in a copper bowl, topped with slit green chillies and served with rice.'),
    ('Macher Jhol (Bengali Fish Curry)', 'Macher Jhol (Bengali Fish Curry) (Bangladeshi). A shallow bowl of golden-yellow fish curry with thick white fish steaks, potato wedges and green chillies, served beside steamed white rice.'),
    ('Sri Lankan Chicken Curry', 'Sri Lankan Chicken Curry (Sri Lankan). A bowl of orange-gold coconut chicken curry with bone-in pieces, curry leaves and green chillies, beside a mound of white rice.'),
    ('Vegetable Samosas', 'Vegetable Samosas (Pakistani). A pile of golden-brown crisp triangular samosas on a platter with a bowl of green mint chutney and a bowl of tamarind sauce.'),
    ('Vegetable Pakoras', 'Vegetable Pakoras (Pakistani). A heap of golden crispy irregular pakoras on a lined basket with a small bowl of green chutney and lemon wedges.'),
    ('Gulab Jamun', 'Gulab Jamun (Pakistani). Glossy dark-golden gulab jamun in a bowl of amber syrup, sprinkled with chopped green pistachios and saffron threads.'),
    ('Sheer Khurma', 'Sheer Khurma (Pakistani). A cream-coloured bowl of creamy vermicelli pudding topped with sliced pistachios, almonds, dates and saffron strands.'),
    ('Mango Lassi', 'Mango Lassi (Indian). Tall glasses of thick golden-yellow mango lassi sprinkled with chopped pistachios, with a slice of fresh mango on the rim.'),
    ('Çılbır (Poached Eggs with Garlic Yogurt)', 'Çılbır (Poached Eggs with Garlic Yogurt) (Turkish). Poached eggs resting on a pool of white garlic yogurt in a shallow white dish, streaked with glossy red paprika butter and a sprinkle of dried mint. Torn bread sits alongside.'),
    ('Sucuklu Yumurta (Beef Sucuk & Eggs)', 'Sucuklu Yumurta (Beef Sucuk & Eggs) (Turkish). A black cast-iron pan of golden fried eggs with bright yolks nestled among overlapping red-brown sucuk rounds, flecked with parsley. Torn crusty bread beside it.'),
    ('Lahmacun', 'Lahmacun (Turkish). Thin round flatbreads topped with a red-orange spiced lamb layer and charred edges, stacked on a wooden board with fresh parsley and lemon wedges.'),
    ('İmam Bayıldı (Stuffed Aubergine)', 'İmam Bayıldı (Stuffed Aubergine) (Turkish). Four glossy dark-purple aubergines split open and brimming with red tomato and onion filling in a white oval dish, scattered with fresh parsley.'),
    ('Burek (Meat Pie)', 'Burek (Meat Pie) (Bosnian). A golden-brown coiled spiral pie cut into wedges showing flaky layers and meat filling, with a bowl of white yogurt on the side.'),
    ('Dushbara (Dumpling Soup)', 'Dushbara (Dumpling Soup) (Azerbaijani). A deep white bowl of clear golden broth with small triangular dumplings, sprinkled with dried mint and a few drops of garlic vinegar.'),
    ('Lanzhou-Style Beef Noodle Soup', 'Lanzhou-Style Beef Noodle Soup (Chinese (Hui)). A large bowl of clear amber broth with noodles, sliced beef and radish, topped with green spring onion, coriander and a swirl of red chilli oil.'),
    ('Circassian Chicken (Çerkez Tavuğu)', 'Circassian Chicken (Çerkez Tavuğu) (Turkish). Shredded chicken covered in a pale cream walnut sauce on a white oval plate, with a red paprika oil drizzle and crushed walnut garnish.'),
    ('Iskender Kebab', 'Iskender Kebab (Turkish). Layers of sliced beef over golden pide cubes, red tomato sauce, white yogurt and a pool of butter, with a charred green chilli on the side.'),
    ('Karnıyarık (Aubergine Stuffed with Beef)', 'Karnıyarık (Aubergine Stuffed with Beef) (Turkish). Four split aubergines filled with browned beef mince, each topped with a tomato slice and a green pepper, in a baking dish with red sauce.'),
    ('Kıymalı Pide (Minced Beef Pide)', 'Kıymalı Pide (Minced Beef Pide) (Turkish). Four long golden boat-shaped breads with a visible spiced beef filling, edges glossy with butter, on a wooden board with parsley.'),
    ('Turkish Mantı', 'Turkish Mantı (Turkish). A bowl of small dumplings topped with white garlic yogurt and a red paprika butter drizzle with dried mint on top.'),
    ('Ćevapi with Lepinja', 'Ćevapi with Lepinja (Bosnian). A plate of golden-brown grilled ćevapi lined up beside a puffy flatbread, with raw red onion and a white dollop of sour cream.'),
    ('Tavë Kosi (Baked Lamb & Yogurt)', 'Tavë Kosi (Baked Lamb & Yogurt) (Albanian). A rectangular baking dish with a puffed golden-brown custard top over lamb and rice, with a slice taken out showing the layers.'),
    ('Uzbek Plov', 'Uzbek Plov (Uzbek). A mound of golden, glossy rice and carrots on a large platter, topped with chunks of lamb and a whole roasted garlic bulb.'),
    ('Lagman (Hand-Pulled Noodles)', 'Lagman (Hand-Pulled Noodles) (Uyghur). A shallow bowl of long pale noodles piled high with red-brown lamb and colourful peppers and carrots, garnished with green coriander.'),
    ('Beshbarmak', 'Beshbarmak (Kazakh). A large platter of wide flat noodles topped with chunks of boiled lamb, soft onion rings and potatoes, sprinkled with dill.'),
    ('Mercimek Köftesi (Lentil Patties)', 'Mercimek Köftesi (Lentil Patties) (Turkish). Oval orange lentil patties arranged in fresh green lettuce leaves on a platter, with lemon wedges and parsley.'),
    ('Baklava', 'Baklava (Turkish). A tray of golden diamond-shaped baklava with glistening syrup, each piece topped with bright green crushed pistachio.'),
    ('Sütlaç (Baked Rice Pudding)', 'Sütlaç (Baked Rice Pudding) (Turkish). Individual terracotta bowls of creamy white rice pudding with dark caramelised spots on the surface.'),
    ('Samsa (Baked Lamb Pastries)', 'Samsa (Baked Lamb Pastries) (Uzbek). Golden triangular pastries dotted with sesame seeds, one broken open to reveal a juicy lamb filling, on a baking paper-lined tray.'),
    ('Chak-Chak (Honey Dough Bites)', 'Chak-Chak (Honey Dough Bites) (Tatar). A glossy golden mound of honey-coated fried dough strands on a round white plate.'),
    ('Roti Canai with Dhal', 'Roti Canai with Dhal (Malaysian). A golden flaky roti canai torn open on a round plate beside a small bowl of yellow dhal topped with fried curry leaves.'),
    ('Nasi Goreng', 'Nasi Goreng (Indonesian). A mound of dark glossy fried rice on a white plate topped with a crispy fried egg, with cucumber and tomato slices and golden fried shallots.'),
    ('Bubur Ayam (Chicken Rice Porridge)', 'Bubur Ayam (Chicken Rice Porridge) (Indonesian). A deep white bowl of creamy porridge topped with shredded chicken, a halved egg, green spring onion and golden fried shallots.'),
    ('Mee Goreng Mamak', 'Mee Goreng Mamak (Malaysian). A glossy red-brown tangle of fried noodles on a plate with golden tofu cubes, greens, egg and a lime wedge on the side.'),
    ('Curry Laksa', 'Curry Laksa (Malaysian). A big bowl of orange curry broth with vermicelli, pink prawns, tofu puffs, a halved egg and a heap of green herbs.'),
    ('Soto Ayam', 'Soto Ayam (Indonesian). A bowl of bright yellow broth with shredded chicken, glass noodles, a halved egg, potato and fried shallot garnish, a lime wedge on the rim.'),
    ('Gado-Gado', 'Gado-Gado (Indonesian). A colourful platter of green beans, cabbage, potato, tofu and halved eggs covered in thick peanut sauce with pink prawn crackers on top.'),
    ('Pad Thai with Prawns', 'Pad Thai with Prawns (Thai). A nest of orange-brown noodles with pink prawns on a plate, scattered with crushed peanuts, bean sprouts, chives and a lime wedge.'),
    ('Salmon Onigiri', 'Salmon Onigiri (Japanese). Four neat white rice triangles with black nori bands and sesame seeds, arranged on a small wooden board.'),
    ('Egg Fried Rice', 'Egg Fried Rice (Chinese). A bowl of golden fried rice flecked with yellow egg, green peas, orange carrot and spring onion.'),
    ('Chicken Satay with Peanut Sauce', 'Chicken Satay with Peanut Sauce (Malaysian). A row of charred golden chicken skewers on a platter beside a bowl of glossy peanut sauce with cucumber and red onion chunks.'),
    ('Ayam Masak Merah', 'Ayam Masak Merah (Malaysian). Glossy red-glazed chicken pieces in a shallow dish with green peas and whole spices, served beside white rice.'),
    ('Opor Ayam', 'Opor Ayam (Indonesian). Pieces of chicken in a pale creamy yellow coconut sauce in a clay bowl, topped with fried shallots and herbs.'),
    ('Murtabak', 'Murtabak (Singaporean). A golden crisp square murtabak cut into pieces showing the minced beef and egg filling, with a small bowl of cucumber pickle.'),
    ('Beef Massaman Curry', 'Beef Massaman Curry (Thai). Tender beef chunks and potatoes in a creamy orange-brown curry in a ceramic bowl, topped with roasted peanuts, rice alongside.'),
    ('Thai Green Chicken Curry', 'Thai Green Chicken Curry (Thai). A bowl of pale green curry with chicken, round aubergines and green basil leaves, with a mound of white rice beside it.'),
    ('Chicken Piaparan', 'Chicken Piaparan (Filipino (Maranao)). Chicken pieces in a thick brownish coconut sauce in a shallow bowl, topped with fresh green spring onion and red chilli slices.'),
    ('Chicken Teriyaki', 'Chicken Teriyaki (Japanese). Sliced glossy dark-glazed chicken fanned over a bowl of white rice with bright green broccoli and sesame seeds.'),
    ('Beef Bulgogi', 'Beef Bulgogi (Korean). Caramelised dark beef slices with onion and sesame seeds in a dish, with a bowl of rice and fresh green lettuce leaves beside.'),
    ('Cumin Lamb Stir-Fry', 'Cumin Lamb Stir-Fry (Chinese (Hui)). Browned lamb slices flecked with cumin and red chilli, with green chilli, onion and coriander on a dark plate.'),
    ('Pisang Goreng (Banana Fritters)', 'Pisang Goreng (Banana Fritters) (Malaysian). A pile of golden crunchy banana fritters on a rustic plate lined with paper, with a few banana slices showing soft yellow inside.'),
    ('Klepon (Palm Sugar Rice Balls)', 'Klepon (Palm Sugar Rice Balls) (Indonesian). Small bright green round balls rolled in white shredded coconut, piled on a banana leaf lined plate.'),
    ('Canjeero (Laxoox Pancakes)', 'Canjeero (Laxoox Pancakes) (Somali). A stack of pale golden pancakes with a honeycomb of tiny holes on a white plate, one folded over to show the spongy texture, melted butter glistening and a dusting of sugar. A small glass of tea sits beside the plate.'),
    ('Akara (Bean Fritters)', 'Akara (Bean Fritters) (Nigerian). A heap of round, deep golden-brown bean fritters with craggy crisp surfaces on a paper-lined plate, one broken open to reveal a pale fluffy interior. A small bowl of pepper sauce sits alongside.'),
    ('Swahili Chapati', 'Swahili Chapati (Kenyan). A stack of round golden chapatis with brown blistered spots, the top one torn open to show soft flaky layers, on a wooden board with a cup of spiced chai beside it.'),
    ('Misir Wat (Spiced Red Lentils)', 'Misir Wat (Spiced Red Lentils) (Ethiopian). A shallow bowl of thick, glossy brick-red lentil stew with a swirl of spiced butter on top, served beside folded spongy injera on a round platter.'),
    ('Shiro (Chickpea Stew)', 'Shiro (Chickpea Stew) (Eritrean). A bowl of smooth golden-orange chickpea stew with a shiny oil sheen and a pinch of chopped green chilli on top, placed on injera on a large round plate.'),
    ('Moi Moi (Steamed Bean Pudding)', 'Moi Moi (Steamed Bean Pudding) (Nigerian). Slices of firm, pale orange steamed bean pudding on a plate, one cut to reveal a wedge of boiled egg in the centre, served with a spoon of pap or bread alongside.'),
    ('Waakye (Rice & Beans)', 'Waakye (Rice & Beans) (Ghanaian). A mound of deep reddish-brown rice and beans on a banana-leaf-lined plate, with halved boiled eggs, golden fried plantain slices, a scoop of gari and a spoonful of dark red shito sauce.'),
    ('Sukuma Wiki with Ugali', 'Sukuma Wiki with Ugali (Kenyan). A smooth white dome of ugali next to a generous pile of glossy dark green sukuma wiki flecked with tomato, served on a simple enamel plate.'),
    ('Bariis Iskukaris (Spiced Rice with Lamb)', 'Bariis Iskukaris (Spiced Rice with Lamb) (Somali). A wide platter of fluffy golden-brown spiced rice dotted with raisins and grated carrot, topped with tender pieces of lamb, with a wedge of lime and a halved banana on the side.'),
    ('Doro Wat (Chicken Stew)', 'Doro Wat (Chicken Stew) (Ethiopian). A deep red-brown, glossy chicken stew with drumsticks and halved boiled eggs nestled in the sauce, served on a large round injera-lined platter with rolled injera on the side.'),
    ('Zigni (Spiced Beef Stew)', 'Zigni (Spiced Beef Stew) (Eritrean). A bowl of dark red, thick beef stew with tender chunks of meat and halved eggs, glistening with spiced butter, set on injera with extra rolled injera beside it.'),
    ('Egusi Soup', 'Egusi Soup (Nigerian). A deep bowl of golden-orange egusi soup with soft curds, dark green leaves and chunks of beef, glistening with palm oil, next to a smooth mound of pounded yam.'),
    ('Suya (Spiced Beef Skewers)', 'Suya (Spiced Beef Skewers) (Nigerian). Charred beef skewers dusted generously with rust-red yaji spice on a wooden board, served with raw red onion rings and sliced tomato on a piece of paper.'),
    ('Thieboudienne (Fish & Rice)', 'Thieboudienne (Fish & Rice) (Senegalese). A large round platter of orange-red rice topped with golden fried fish steaks, wedges of cabbage, carrot, cassava and aubergine, with a lime wedge and fresh parsley.'),
    ('Chicken Yassa', 'Chicken Yassa (Senegalese). Charred chicken legs resting on a bed of glossy golden caramelised onions with green olives, spooned over white rice on a deep serving dish.'),
    ('Mafe (Peanut Stew)', 'Mafe (Peanut Stew) (Senegalese). A bowl of thick, creamy orange-brown peanut stew with chunks of beef, sweet potato and carrot, served beside a mound of white rice and finished with a drizzle of the red oil.'),
    ('Swahili Pilau', 'Swahili Pilau (Kenyan). A shallow dish of brown, fluffy spiced rice with tender beef pieces and potato chunks, garnished with fried onions and served with a small bowl of fresh tomato and onion kachumbari.'),
    ('Samaki wa Kupaka (Coconut Fish Curry)', 'Samaki wa Kupaka (Coconut Fish Curry) (Tanzanian). Golden grilled fish fillets in a creamy, yellow-orange coconut sauce speckled with green coriander, served in a shallow dish next to white rice.'),
    ('Sambusa', 'Sambusa (Somali). A pile of crisp golden triangular sambusas on a plate lined with paper, one broken open to show the spiced beef filling, with lemon wedges and a small bowl of green chilli sauce.'),
    ('Kelewele (Spiced Plantain)', 'Kelewele (Spiced Plantain) (Ghanaian). Golden-brown caramelised plantain cubes dusted with spice, heaped in a small bowl or paper cone, with a handful of roasted peanuts beside them.'),
    ('Mandazi', 'Mandazi (Tanzanian). A pile of golden-brown triangular mandazi, lightly puffed and glistening, on a woven plate with a cup of milky chai beside them.'),
    ('Puff-Puff', 'Puff-Puff (Nigerian). A pile of round, golden-brown puff-puff with a slightly rough, glistening surface on a plain white plate, one torn open to show the soft airy centre.'),
    ('Fluffy Pancakes with Berries', 'Fluffy Pancakes with Berries (American). A tall stack of golden pancakes on a white plate, topped with halved strawberries and blueberries and glossy maple syrup running down the sides.'),
    ('Spinach & Feta Omelette', 'Spinach & Feta Omelette (Mediterranean). A golden folded omelette on a round plate, split open to show green spinach and white feta crumbles, finished with cracked black pepper and a sprig of oregano.'),
    ('Greek Yogurt Parfait with Granola', 'Greek Yogurt Parfait with Granola (Mediterranean). Four clear glasses showing distinct white, golden and red-purple layers of yogurt, granola and berries, topped with flaked almonds and a honey drizzle.'),
    ('Beef & Egg Breakfast Burrito', 'Beef & Egg Breakfast Burrito (Mexican). Two burritos cut in half on a wooden board showing a filling of browned beef, yellow scrambled egg and melted cheese, with a small bowl of red salsa and lime wedges beside them.'),
    ('Spaghetti Bolognese', 'Spaghetti Bolognese (Italian). A shallow white bowl of twirled spaghetti topped with deep red meat sauce, fresh basil leaves and a snowfall of grated parmesan.'),
    ('Chicken Alfredo Pasta', 'Chicken Alfredo Pasta (Italian). A wide white bowl of fettuccine coated in creamy pale sauce, topped with sliced golden chicken, chopped green parsley and black pepper.'),
    ('Homemade Margherita Pizza', 'Homemade Margherita Pizza (Italian). A round pizza on a wooden board with a blistered golden crust, melted white mozzarella pools, red tomato sauce and fresh green basil leaves.'),
    ('Beef Lasagne', 'Beef Lasagne (Italian). A square slice of lasagne on a white plate showing neat layers of pasta, red beef ragu and white sauce under a browned cheese top, with a basil leaf garnish.'),
    ('Chicken Souvlaki with Tzatziki', 'Chicken Souvlaki with Tzatziki (Greek). Charred chicken skewers on a rustic plate beside warm pita, a bowl of white tzatziki with dill, tomato and red onion slices and lemon wedges.'),
    ('Chicken & Prawn Paella', 'Chicken & Prawn Paella (Spanish). A wide paella pan of golden saffron rice topped with browned chicken, pink prawns, green peas, red pepper strips, parsley and lemon wedges.'),
    ('Minestrone Soup', 'Minestrone Soup (Italian). A rustic bowl of red-orange vegetable soup full of beans, pasta and green spinach, sprinkled with parmesan and a swirl of olive oil, with crusty bread beside it.'),
    ('Ratatouille', 'Ratatouille (French). A shallow terracotta dish of glossy, jewel-coloured stewed vegetables in tomato sauce, topped with torn basil and a drizzle of olive oil.'),
    ('Tuna Niçoise Salad', 'Tuna Niçoise Salad (French). A large white platter of salad with neat sections of flaked tuna, green beans, halved eggs with golden yolks, red tomatoes, black olives and potatoes.'),
    ('Beef Tacos', 'Beef Tacos (Mexican). Four open tacos on a slate board, filled with seasoned beef, shredded lettuce, diced tomato and melted cheese, with lime wedges and a bowl of soured cream.'),
    ('Shepherd''s Pie with Lamb', 'Shepherd''s Pie with Lamb (British). A baking dish of shepherd''s pie with a golden-brown fork-ridged mashed potato top, a portion scooped out to reveal rich lamb filling with peas and carrots.'),
    ('Oven-Baked Fish and Chips', 'Oven-Baked Fish and Chips (British). A golden crumb-coated fish fillet on a plate with thick oven chips and a scoop of bright green crushed peas, with a lemon wedge on the side.'),
    ('Homemade Beef Burgers', 'Homemade Beef Burgers (American). A tall burger on a wooden board with a toasted bun, melted yellow cheese over a juicy patty, lettuce, tomato and pickles, served with golden fries.'),
    ('Chicken Fajitas', 'Chicken Fajitas (Mexican). A hot black skillet of sizzling chicken, red, green and yellow pepper strips and onions, beside warm tortillas, green guacamole, soured cream and lime wedges.'),
    ('Jerk Chicken with Rice and Peas', 'Jerk Chicken with Rice and Peas (Caribbean). Dark, glossy charred jerk chicken pieces on a plate beside fluffy coconut rice speckled with red kidney beans, garnished with lime wedges and fresh thyme.'),
    ('Pão de Queijo (Cheese Bread)', 'Pão de Queijo (Cheese Bread) (Brazilian). A wicker basket lined with a napkin holding golden, puffed round cheese rolls, one broken open to show the soft, stretchy inside.'),
    ('Banana Bread', 'Banana Bread (American). A golden-brown banana loaf with a cracked top on a wooden board, a few thick slices cut to show the moist crumb and walnut pieces.')
  ) AS v(name, prompt)
  WHERE lower(r.name) = lower(v.name) AND r.image_prompt IS NULL;

  INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit, display_order)
  SELECT x.recipe_id, x.ingredient_id, x.qty, x.unit, x.ord FROM (
    SELECT (SELECT id FROM public.recipes WHERE lower(name) = lower(v.recipe) LIMIT 1) AS recipe_id,
           (SELECT id FROM public.ingredients i WHERE lower(i.name) = lower(v.ingredient) LIMIT 1) AS ingredient_id,
           CASE WHEN qty_required THEN coalesce(v.qty::numeric, 0) ELSE v.qty::numeric END AS qty, v.unit, v.ord
    FROM (VALUES
    ('Shakshuka', 'olive oil', 2, 'tbsp', 1),
    ('Shakshuka', 'onion', 1, 'pieces', 2),
    ('Shakshuka', 'red bell pepper', 1, 'pieces', 3),
    ('Shakshuka', 'garlic', 3, 'cloves', 4),
    ('Shakshuka', 'ground cumin', 1, 'tsp', 5),
    ('Shakshuka', 'paprika', 1, 'tsp', 6),
    ('Shakshuka', 'canned tomatoes', 800, 'g', 7),
    ('Shakshuka', 'eggs', 6, 'pieces', 8),
    ('Shakshuka', 'salt', 1, 'tsp', 9),
    ('Shakshuka', 'fresh parsley', 1, 'handful', 10),
    ('Ful Medames', 'canned fava beans', 800, 'g', 1),
    ('Ful Medames', 'garlic', 2, 'cloves', 2),
    ('Ful Medames', 'lemon', 1, 'pieces', 3),
    ('Ful Medames', 'ground cumin', 1, 'tsp', 4),
    ('Ful Medames', 'olive oil', 3, 'tbsp', 5),
    ('Ful Medames', 'tomato', 1, 'pieces', 6),
    ('Ful Medames', 'fresh parsley', 1, 'handful', 7),
    ('Ful Medames', 'salt', 1, 'tsp', 8),
    ('Ful Medames', 'pita bread', 4, 'pieces', 9),
    ('Menemen', 'butter', 1, 'tbsp', 1),
    ('Menemen', 'olive oil', 1, 'tbsp', 2),
    ('Menemen', 'green pepper', 2, 'pieces', 3),
    ('Menemen', 'tomato', 3, 'pieces', 4),
    ('Menemen', 'eggs', 4, 'pieces', 5),
    ('Menemen', 'chili flakes', 0.5, 'tsp', 6),
    ('Menemen', 'salt', 0.5, 'tsp', 7),
    ('Za''atar Manakish', 'flour', 500, 'g', 1),
    ('Za''atar Manakish', 'instant yeast', 7, 'g', 2),
    ('Za''atar Manakish', 'sugar', 1, 'tsp', 3),
    ('Za''atar Manakish', 'salt', 1, 'tsp', 4),
    ('Za''atar Manakish', 'warm water', 300, 'ml', 5),
    ('Za''atar Manakish', 'olive oil', 120, 'ml', 6),
    ('Za''atar Manakish', 'za''atar', 6, 'tbsp', 7),
    ('Date & Tahini Overnight Oats', 'rolled oats', 1, 'cup', 1),
    ('Date & Tahini Overnight Oats', 'milk', 1, 'cup', 2),
    ('Date & Tahini Overnight Oats', 'yogurt', 0.5, 'cup', 3),
    ('Date & Tahini Overnight Oats', 'medjool dates', 4, 'pieces', 4),
