  INSERT INTO public.recipe_steps (recipe_id, step_number, instruction)
  SELECT x.recipe_id, x.num, x.txt FROM (
    SELECT (SELECT id FROM public.recipes WHERE lower(name) = lower(v.recipe) LIMIT 1) AS recipe_id, v.num, v.txt
    FROM (VALUES
    ('Shakshuka', 1, 'Heat the olive oil in a wide pan over medium heat. Add the sliced onion and pepper and cook for 6–8 minutes until soft.'),
    ('Shakshuka', 2, 'Stir in the garlic, cumin and paprika and cook for 1 minute until fragrant.'),
    ('Shakshuka', 3, 'Add the tomatoes and salt, then simmer for 8–10 minutes until the sauce thickens.'),
    ('Shakshuka', 4, 'Make 6 small wells in the sauce and crack an egg into each. Cover and cook for 5–7 minutes until the whites are set.'),
    ('Shakshuka', 5, 'Scatter with chopped parsley and serve straight from the pan with bread.'),
    ('Ful Medames', 1, 'Tip the beans with their liquid into a pan and warm over medium heat for 5 minutes.'),
    ('Ful Medames', 2, 'Mash about half the beans with a fork or potato masher.'),
    ('Ful Medames', 3, 'Stir in the crushed garlic, cumin, lemon juice and salt.'),
    ('Ful Medames', 4, 'Spoon into bowls, drizzle generously with olive oil and top with diced tomato and parsley.'),
    ('Ful Medames', 5, 'Serve with warm pita bread.'),
    ('Menemen', 1, 'Melt the butter with the oil in a frying pan. Add the chopped peppers and cook for 4 minutes.'),
    ('Menemen', 2, 'Add the grated or finely chopped tomatoes and cook until most of the liquid has gone, about 6 minutes.'),
    ('Menemen', 3, 'Season with salt and chili flakes.'),
    ('Menemen', 4, 'Pour in the beaten eggs and stir gently until just set but still soft.'),
    ('Menemen', 5, 'Serve immediately with fresh bread.'),
    ('Za''atar Manakish', 1, 'Mix the flour, yeast, sugar and salt. Add the warm water and 2 tablespoons of the oil and knead for 8 minutes into a soft dough.'),
    ('Za''atar Manakish', 2, 'Cover and leave to rise for 1 hour until doubled.'),
    ('Za''atar Manakish', 3, 'Heat the oven to 240°C (465°F) with a tray inside.'),
    ('Za''atar Manakish', 4, 'Mix the za’atar with the remaining olive oil to a loose paste.'),
    ('Za''atar Manakish', 5, 'Divide the dough into 6, roll each into a thin round and press dimples into the surface with your fingertips.'),
    ('Za''atar Manakish', 6, 'Spread with the za’atar oil and bake for 6–8 minutes until the edges are golden.'),
    ('Date & Tahini Overnight Oats', 1, 'Chop the dates finely, removing the stones.'),
    ('Date & Tahini Overnight Oats', 2, 'Stir together the oats, milk, yogurt, dates and cinnamon in a jar or bowl.'),
    ('Date & Tahini Overnight Oats', 3, 'Cover and refrigerate overnight (at least 6 hours).'),
    ('Date & Tahini Overnight Oats', 4, 'In the morning, stir well and drizzle with tahini before eating.'),
    ('Lentil Soup (Shorbat Adas)', 1, 'Heat the oil in a large pot and cook the chopped onion and carrot for 6 minutes.'),
    ('Lentil Soup (Shorbat Adas)', 2, 'Add the garlic, cumin and turmeric and stir for 1 minute.'),
    ('Lentil Soup (Shorbat Adas)', 3, 'Add the rinsed lentils and stock. Bring to the boil, then simmer for 20–25 minutes until the lentils are very soft.'),
    ('Lentil Soup (Shorbat Adas)', 4, 'Blend until smooth, then season with salt.'),
    ('Lentil Soup (Shorbat Adas)', 5, 'Serve with lemon wedges and toasted pita.'),
    ('Chicken Shawarma Wraps', 1, 'Mix the yogurt, lemon juice, 2 crushed garlic cloves, spices, oil and a pinch of salt. Coat the chicken and marinate for at least 15 minutes (or overnight).'),
    ('Chicken Shawarma Wraps', 2, 'Cook the chicken in a hot pan or under the grill for 6–7 minutes a side until cooked through.'),
    ('Chicken Shawarma Wraps', 3, 'Rest for 5 minutes, then slice thinly.'),
    ('Chicken Shawarma Wraps', 4, 'Stir the remaining crushed garlic into a little yogurt with salt for a quick garlic sauce.'),
    ('Chicken Shawarma Wraps', 5, 'Fill warm pitas with chicken, sauce, pickles and sliced tomato, then roll up tightly.'),
    ('Fattoush Salad', 1, 'Tear the pita into pieces and toast in a hot oven or dry pan until crisp.'),
    ('Fattoush Salad', 2, 'Chop the lettuce, cucumber, tomatoes and radishes and place in a large bowl with the herbs.'),
    ('Fattoush Salad', 3, 'Whisk the olive oil, lemon juice, sumac, pomegranate molasses and a pinch of salt.'),
    ('Fattoush Salad', 4, 'Toss the salad with the dressing and pita just before serving.'),
    ('Falafel with Tahini Sauce', 1, 'Soak the dried chickpeas in plenty of cold water for 12–24 hours, then drain well (do not use canned).'),
    ('Falafel with Tahini Sauce', 2, 'Blitz the chickpeas, onion, garlic, herbs, cumin and salt in a food processor to a coarse paste. Stir in the baking soda.'),
    ('Falafel with Tahini Sauce', 3, 'Shape into small patties or balls.'),
    ('Falafel with Tahini Sauce', 4, 'Heat the oil to 175°C (350°F) and fry in batches for 3–4 minutes until deep golden. Drain on paper.'),
    ('Falafel with Tahini Sauce', 5, 'Whisk the tahini with lemon juice, a pinch of salt and enough cold water to make a pourable sauce.'),
    ('Falafel with Tahini Sauce', 6, 'Serve the falafel in pita or on a plate with salad and the tahini sauce.'),
    ('Chicken Biryani', 1, 'Soak the rice for 30 minutes. Warm the milk and soak the saffron in it.'),
    ('Chicken Biryani', 2, 'Fry the thinly sliced onions in the oil until deep golden. Remove half for garnish.'),
    ('Chicken Biryani', 3, 'Add the ginger garlic paste and chicken to the pan and cook for 5 minutes. Add tomatoes, yogurt, biryani masala, green chilies and salt and cook covered for 20 minutes until the chicken is tender and the sauce thick.'),
    ('Chicken Biryani', 4, 'Meanwhile, boil the rice in well-salted water for 5–6 minutes until 70% cooked, then drain.'),
    ('Chicken Biryani', 5, 'Layer half the rice over the chicken, scatter with mint, coriander and fried onions, then add the remaining rice. Drizzle with the saffron milk.'),
    ('Chicken Biryani', 6, 'Cover tightly and cook on the lowest heat for 20 minutes (dum) until the rice is fluffy.'),
    ('Chicken Biryani', 7, 'Gently mix the layers as you serve.'),
    ('Moroccan Chicken Tagine with Olives and Lemon', 1, 'Rub the chicken with the spices, crushed garlic, a pinch of salt and 1 tablespoon of oil.'),
    ('Moroccan Chicken Tagine with Olives and Lemon', 2, 'Heat the remaining oil in a tagine or heavy pot and brown the chicken on both sides. Remove.'),
    ('Moroccan Chicken Tagine with Olives and Lemon', 3, 'Soften the sliced onions for 8 minutes, then return the chicken with the stock and saffron.'),
    ('Moroccan Chicken Tagine with Olives and Lemon', 4, 'Cover and simmer gently for 40 minutes.'),
    ('Moroccan Chicken Tagine with Olives and Lemon', 5, 'Add the sliced preserved lemon rind and olives and cook uncovered for 10 more minutes to reduce the sauce.'),
    ('Moroccan Chicken Tagine with Olives and Lemon', 6, 'Scatter with coriander and serve with bread or couscous.'),
    ('Lamb Kofta with Yogurt Sauce', 1, 'Grate the onion and squeeze out the excess juice.'),
    ('Lamb Kofta with Yogurt Sauce', 2, 'Mix the lamb, onion, 2 crushed garlic cloves, chopped parsley, spices and salt. Knead for 2 minutes.'),
    ('Lamb Kofta with Yogurt Sauce', 3, 'Shape into 12 sausage shapes around skewers and chill for 10 minutes.'),
    ('Lamb Kofta with Yogurt Sauce', 4, 'Grill or pan-fry for 10–12 minutes, turning, until browned and cooked through.'),
    ('Lamb Kofta with Yogurt Sauce', 5, 'Stir the remaining garlic and chopped mint into the yogurt with a pinch of salt.'),
    ('Lamb Kofta with Yogurt Sauce', 6, 'Serve the kofta with the yogurt, salad and rice or flatbread.'),
    ('Chicken Karahi', 1, 'Heat the oil in a karahi or wide pan and fry the chicken on high heat for 5 minutes.'),
    ('Chicken Karahi', 2, 'Add the crushed garlic and half the grated ginger and cook for 2 minutes.'),
    ('Chicken Karahi', 3, 'Add the chopped tomatoes, salt, chili powder and ground coriander. Cover and cook for 15 minutes until the tomatoes collapse.'),
    ('Chicken Karahi', 4, 'Uncover and cook on high, stirring, until the oil separates from the sauce.'),
    ('Chicken Karahi', 5, 'Add the green chilies, remaining ginger (in thin strips) and garam masala. Cook for 2 minutes.'),
    ('Chicken Karahi', 6, 'Garnish with coriander and serve with naan or rice.'),
    ('Daal Tadka', 1, 'Rinse the lentils and simmer with 3 cups of water, the turmeric and salt for 25 minutes until soft.'),
    ('Daal Tadka', 2, 'Heat the ghee in a small pan and add the cumin seeds until they crackle.'),
    ('Daal Tadka', 3, 'Add the sliced garlic, chopped onion and chili and fry until golden.'),
    ('Daal Tadka', 4, 'Add the chopped tomato and garam masala and cook for 3 minutes.'),
    ('Daal Tadka', 5, 'Pour the sizzling tempering over the lentils, stir and garnish with coriander.'),
    ('Nasi Lemak', 1, 'Rinse the rice and cook it with the coconut milk, 1 cup of water, a pinch of salt and the knotted pandan leaves.'),
    ('Nasi Lemak', 2, 'Boil the eggs for 8 minutes, then cool and halve.'),
    ('Nasi Lemak', 3, 'For the sambal, fry the sliced onion in oil until soft, add the chili paste and cook for 5 minutes. Stir in the tamarind, sugar and a splash of water and simmer until thick.'),
    ('Nasi Lemak', 4, 'Fry the anchovies until crisp (or skip for a lighter version).'),
    ('Nasi Lemak', 5, 'Serve the rice with sambal, egg, cucumber slices, peanuts and anchovies.'),
    ('Beef Rendang', 1, 'Soak the dried chilies, then blend with the shallots, garlic, ginger, galangal and turmeric into a paste.'),
    ('Beef Rendang', 2, 'Toast the desiccated coconut in a dry pan until golden, then pound or blend until oily.'),
    ('Beef Rendang', 3, 'Fry the spice paste in the oil for 8 minutes until fragrant.'),
    ('Beef Rendang', 4, 'Add the beef cubes, bruised lemongrass and lime leaves and stir to coat.'),
    ('Beef Rendang', 5, 'Pour in the coconut milk, bring to a simmer and cook uncovered on low for 2½–3 hours, stirring often, until the sauce has almost completely reduced.'),
    ('Beef Rendang', 6, 'Stir in the toasted coconut, palm sugar and salt and cook until dark and dry.'),
    ('Jollof Rice with Chicken', 1, 'Season the chicken with curry powder, thyme and salt, then roast at 200°C (400°F) for 35 minutes.'),
    ('Jollof Rice with Chicken', 2, 'Blend the tomatoes, peppers, scotch bonnet and one onion until smooth.'),
    ('Jollof Rice with Chicken', 3, 'Fry the other sliced onion in the oil, add the tomato paste and fry for 3 minutes, then add the blended mixture and cook for 15 minutes until reduced.'),
    ('Jollof Rice with Chicken', 4, 'Add the washed rice, stock and bay leaves. Stir once, cover tightly and cook on low for 25–30 minutes.'),
    ('Jollof Rice with Chicken', 5, 'Fluff the rice and serve with the roast chicken.'),
    ('Somali Chicken Suqaar', 1, 'Cut the chicken into small cubes and season with xawaash and salt.'),
    ('Somali Chicken Suqaar', 2, 'Fry the chicken in hot oil for 6–8 minutes until browned.'),
    ('Somali Chicken Suqaar', 3, 'Add the onion, garlic, diced carrot and pepper and cook for 5 minutes.'),
    ('Somali Chicken Suqaar', 4, 'Add the chopped tomato and cook until the vegetables are just tender.'),
    ('Somali Chicken Suqaar', 5, 'Finish with coriander and lime juice. Serve with rice, pasta or flatbread.'),
    ('Mujaddara', 1, 'Simmer the lentils in plenty of water for 15 minutes until just tender, then drain.'),
    ('Mujaddara', 2, 'Slowly fry the thinly sliced onions in the oil for 25–30 minutes until deep brown and crisp. Remove half for topping.'),
    ('Mujaddara', 3, 'Add the rice and cumin to the pan with the remaining onions and stir for 1 minute.'),
    ('Mujaddara', 4, 'Add the lentils, salt and 2 cups of water. Cover and simmer for 18 minutes until the rice is cooked.'),
    ('Mujaddara', 5, 'Serve topped with crispy onions and a spoonful of yogurt.'),
    ('Maqluba', 1, 'Boil the chicken with the halved onion, cinnamon stick, bay leaves and salt for 40 minutes. Keep the broth.'),
    ('Maqluba', 2, 'Soak the rice for 30 minutes, then drain and season with baharat and turmeric.'),
    ('Maqluba', 3, 'Slice the eggplant and potatoes and break the cauliflower into florets. Fry (or roast with oil) until golden.'),
    ('Maqluba', 4, 'Layer in a large pot: chicken pieces, then the fried vegetables, then the rice.'),
    ('Maqluba', 5, 'Pour over enough hot broth to cover the rice by 2 cm. Cover and cook on low for 30–35 minutes.'),
    ('Maqluba', 6, 'Rest for 10 minutes, place a large tray on top and flip the pot in one confident move. Top with toasted almonds.'),
    ('Harira', 1, 'Brown the diced lamb in a large pot with a little oil, then add the chopped onion, celery and spices.'),
    ('Harira', 2, 'Add the tomatoes, tomato paste, lentils, half the chopped herbs and 2 litres of water. Simmer for 40 minutes.'),
    ('Harira', 3, 'Add the drained chickpeas and vermicelli and cook for 10 minutes.'),
    ('Harira', 4, 'Whisk the flour with a cup of cold water and stir it in slowly, simmering for 5 minutes until silky.'),
    ('Harira', 5, 'Stir in the remaining herbs and serve with lemon wedges and dates.'),
    ('Classic Hummus', 1, 'Drain the chickpeas (for extra smoothness, simmer them for 10 minutes and slip off the skins).'),
    ('Classic Hummus', 2, 'Blend the tahini, lemon juice, garlic and salt until thick and pale.'),
    ('Classic Hummus', 3, 'Add the chickpeas and blend, pouring in the ice water a little at a time, for 3–4 minutes until very smooth.'),
    ('Classic Hummus', 4, 'Spread in a bowl, drizzle with olive oil and dust with paprika.'),
    ('Date & Nut Energy Balls', 1, 'Pit the dates. If they are firm, soak them in warm water for 10 minutes and drain.'),
    ('Date & Nut Energy Balls', 2, 'Pulse the nuts in a food processor until finely chopped.'),
    ('Date & Nut Energy Balls', 3, 'Add the dates, cocoa and cinnamon and blend until the mixture sticks together.'),
    ('Date & Nut Energy Balls', 4, 'Roll into 16 balls and coat in coconut. Chill for 30 minutes.'),
    ('Basbousa', 1, 'Make the syrup: boil 1 cup of the sugar with the water for 8 minutes, add a squeeze of lemon and the rose water, then cool.'),
    ('Basbousa', 2, 'Heat the oven to 180°C (350°F) and grease a 23 × 33 cm tin.'),
    ('Basbousa', 3, 'Mix the semolina, remaining sugar, coconut, baking powder, melted butter and yogurt into a thick batter.'),
    ('Basbousa', 4, 'Spread in the tin, score into diamonds and press an almond into each.'),
    ('Basbousa', 5, 'Bake for 30–35 minutes until golden, then pour the cool syrup over the hot cake.'),
    ('Basbousa', 6, 'Let it absorb the syrup for at least 1 hour before cutting.'),
    ('Kheer (Rice Pudding)', 1, 'Rinse and soak the rice for 20 minutes, then crush it lightly with your fingers.'),
    ('Kheer (Rice Pudding)', 2, 'Bring the milk to the boil with the crushed cardamom, add the rice and simmer on low for 40 minutes, stirring often.'),
    ('Kheer (Rice Pudding)', 3, 'When thick and creamy, stir in the sugar and cook for 5 more minutes.'),
    ('Kheer (Rice Pudding)', 4, 'Add the rose water, then serve warm or chilled, topped with chopped nuts.'),
    ('Lemon Herb Baked Salmon', 1, 'Heat the oven to 200°C (400°F) and line a tray with parchment.'),
    ('Lemon Herb Baked Salmon', 2, 'Place the salmon on the tray and season with salt and pepper.'),
    ('Lemon Herb Baked Salmon', 3, 'Mix the oil, crushed garlic, lemon zest and juice and spoon over the fish.'),
    ('Lemon Herb Baked Salmon', 4, 'Bake for 12–15 minutes until the salmon flakes easily.'),
    ('Lemon Herb Baked Salmon', 5, 'Scatter with chopped dill and serve with rice or roasted vegetables.'),
    ('Chicken Kabsa', 1, 'Soak the rice for 30 minutes.'),
    ('Chicken Kabsa', 2, 'Fry the chopped onion in the oil until golden, add the garlic, kabsa spice and chicken pieces and brown for 5 minutes.'),
    ('Chicken Kabsa', 3, 'Add the chopped tomatoes, tomato paste, pierced dried limes, grated carrot and 5 cups of water. Simmer for 35 minutes until the chicken is tender.'),
    ('Chicken Kabsa', 4, 'Remove the chicken and roast it in a hot oven for 10 minutes to crisp the skin.'),
    ('Chicken Kabsa', 5, 'Add the drained rice to the broth (topping up to cover by 1 cm), cover and cook on low for 20 minutes.'),
    ('Chicken Kabsa', 6, 'Serve the rice on a large platter topped with the chicken, raisins and almonds.'),
    ('Msemen with Honey', 1, 'Mix the flour, 50 g of the semolina, salt and sugar in a large bowl, then gradually add the warm water and knead for 10 minutes until the dough is smooth and elastic.'),
    ('Msemen with Honey', 2, 'Divide the dough into 8 equal balls, coat them lightly with oil, cover and rest for 15 minutes.'),
    ('Msemen with Honey', 3, 'Melt the butter and mix it with 2 tbsp of the oil to make a brushing mixture. Mix the remaining semolina into this to make a spreadable paste.'),
    ('Msemen with Honey', 4, 'Oil your work surface and flatten one ball into a very thin, almost see-through square using oiled fingers, then brush it with the butter mixture.'),
    ('Msemen with Honey', 5, 'Fold the square into thirds like a letter, brush again, and fold into thirds the other way to make a small square. Repeat with the remaining balls.'),
    ('Msemen with Honey', 6, 'Gently flatten each folded square to about 12 cm wide with your palm.'),
    ('Msemen with Honey', 7, 'Heat a non-stick frying pan over medium heat and cook each msemen for 3 to 4 minutes per side, until golden and crisp at the edges.'),
    ('Msemen with Honey', 8, 'Warm the honey for 20 seconds in the microwave and serve the msemen hot with the honey for drizzling.'),
    ('Baghrir (Thousand-Hole Pancakes)', 1, 'Put the semolina, flour, yeast, baking powder, sugar and salt in a blender and add the warm water.'),
    ('Baghrir (Thousand-Hole Pancakes)', 2, 'Blend on high for 2 minutes until the batter is completely smooth and slightly frothy.'),
    ('Baghrir (Thousand-Hole Pancakes)', 3, 'Pour into a bowl, cover and leave in a warm place for 30 minutes until bubbly on top.'),
    ('Baghrir (Thousand-Hole Pancakes)', 4, 'Heat a non-stick frying pan over medium-low heat without any oil.'),
    ('Baghrir (Thousand-Hole Pancakes)', 5, 'Pour in a small ladle of batter and let it spread. Cook for 2 to 3 minutes until the surface is covered with holes and looks dry; do not flip.'),
    ('Baghrir (Thousand-Hole Pancakes)', 6, 'Slide the pancake onto a clean tea towel and repeat with the remaining batter, stirring the batter between each one.'),
    ('Baghrir (Thousand-Hole Pancakes)', 7, 'Melt the butter with the honey in a small pan over low heat for 2 minutes.'),
    ('Baghrir (Thousand-Hole Pancakes)', 8, 'Serve the pancakes holes-side up, generously drizzled with the warm honey butter.'),
    ('Bissara (Fava Bean Soup)', 1, 'Rinse the split fava beans and soak them in cold water for 2 hours if you have time, then drain.'),
    ('Bissara (Fava Bean Soup)', 2, 'Put the beans, peeled garlic cloves and water into a large pot and bring to the boil over high heat.'),
    ('Bissara (Fava Bean Soup)', 3, 'Reduce to a simmer, cover and cook for 45 to 60 minutes, stirring now and then, until the beans are completely soft.'),
    ('Bissara (Fava Bean Soup)', 4, 'Stir in the salt and half of the cumin, then blend with a stick blender until very smooth, adding hot water if too thick.'),
    ('Bissara (Fava Bean Soup)', 5, 'Ladle into bowls and make a small well in the centre of each.'),
    ('Bissara (Fava Bean Soup)', 6, 'Pour 1 tbsp olive oil into each well and sprinkle with the remaining cumin and the paprika.'),
    ('Bissara (Fava Bean Soup)', 7, 'Serve hot with lemon wedges and crusty bread.'),
    ('Lamb Tagine with Prunes and Almonds', 1, 'Cut the lamb into 5 cm chunks and grate one onion; slice the other two onions into half-moons.'),
    ('Lamb Tagine with Prunes and Almonds', 2, 'In a heavy pot or tagine, combine the lamb, grated onion, crushed garlic, olive oil, ginger, half the cinnamon, turmeric, saffron, pepper and salt, and stir over medium heat for 5 minutes.'),
    ('Lamb Tagine with Prunes and Almonds', 3, 'Add the water, bring to the boil, then cover and simmer on low heat for 1 hour 20 minutes until the lamb is nearly tender.'),
    ('Lamb Tagine with Prunes and Almonds', 4, 'Add the sliced onions and cook for a further 15 minutes.'),
    ('Lamb Tagine with Prunes and Almonds', 5, 'Add the prunes, honey and remaining cinnamon, and cook uncovered for 15 minutes until the sauce is thick and glossy.'),
    ('Lamb Tagine with Prunes and Almonds', 6, 'Meanwhile, toast the almonds in a dry pan over medium heat for 3 minutes until golden, then toast the sesame seeds for 1 minute.'),
    ('Lamb Tagine with Prunes and Almonds', 7, 'Top the tagine with the almonds, sesame seeds and chopped coriander, and serve with couscous or bread.'),
    ('Chicken Pastilla', 1, 'Put the chicken, grated onions, crushed garlic, ginger, turmeric, saffron, half the cinnamon, pepper, salt and water in a wide pot and simmer, covered, for 40 minutes.'),
    ('Chicken Pastilla', 2, 'Lift out the chicken, shred the meat discarding skin and bones, and keep warm.'),
    ('Chicken Pastilla', 3, 'Boil the remaining sauce uncovered for 10 minutes until reduced to about 150 ml, add the chopped herbs, then lower the heat and pour in 4 beaten eggs, stirring gently until just set like scrambled eggs. Mix with the chicken and cool.'),
    ('Chicken Pastilla', 4, 'Toast the almonds in a dry pan over medium heat for 4 minutes, chop roughly and mix with 1 tbsp icing sugar and half the remaining cinnamon.'),
    ('Chicken Pastilla', 5, 'Heat the oven to 180C (160C fan). Melt the butter and brush a 26 cm round baking tin.'),
    ('Chicken Pastilla', 6, 'Layer 5 buttered filo sheets overlapping in the tin so they hang over the edges, add half the chicken, then the almond mix, then the rest of the chicken.'),
    ('Chicken Pastilla', 7, 'Fold the overhanging filo over the filling and cover with 5 more buttered sheets, tucking the edges under. Brush the top with the remaining beaten egg and butter.'),
    ('Chicken Pastilla', 8, 'Bake for 30 minutes until deep golden, then dust with the remaining icing sugar and cinnamon in a lattice pattern. Rest 10 minutes before slicing.'),
    ('Couscous with Seven Vegetables', 1, 'Put the beef, sliced onions, olive oil, ginger, turmeric, pepper, saffron and half the salt in a large pot and stir over medium heat for 5 minutes.'),
    ('Couscous with Seven Vegetables', 2, 'Add the water and bring to the boil, then cover and simmer on low heat for 45 minutes.'),
    ('Couscous with Seven Vegetables', 3, 'Add the carrots, turnips and tomatoes (cut in large chunks) with the coriander tied in a bunch, and cook for 15 minutes.'),
    ('Couscous with Seven Vegetables', 4, 'Add the pumpkin, cabbage wedges, courgettes and chickpeas and cook for another 20 minutes until all the vegetables are tender.'),
    ('Couscous with Seven Vegetables', 5, 'While that cooks, put the couscous in a large bowl, sprinkle with 500 ml warm water and the remaining salt, and rub the grains with your hands for 2 minutes. Cover for 10 minutes.'),
    ('Couscous with Seven Vegetables', 6, 'Fluff the couscous with a fork, stir in the butter and steam over a pot of simmering water (or microwave covered for 3 minutes) until hot and light.'),
    ('Couscous with Seven Vegetables', 7, 'Mound the couscous on a large platter, arrange the meat and vegetables on top, and ladle over some broth. Serve the rest of the broth separately.'),
    ('Zaalouk (Aubergine Salad)', 1, 'Peel the aubergines in stripes, cut into 2 cm cubes, sprinkle with salt and leave for 15 minutes, then rinse and pat dry.'),
    ('Zaalouk (Aubergine Salad)', 2, 'Boil the aubergine cubes in water for 10 minutes until soft, then drain well and mash roughly with a fork.'),
    ('Zaalouk (Aubergine Salad)', 3, 'Grate the tomatoes, discarding the skins, or chop them finely.'),
    ('Zaalouk (Aubergine Salad)', 4, 'Heat the olive oil in a wide pan over medium heat and fry the crushed garlic for 30 seconds.'),
    ('Zaalouk (Aubergine Salad)', 5, 'Add the tomatoes, cumin, paprika and salt and cook for 10 minutes until thickened.'),
    ('Zaalouk (Aubergine Salad)', 6, 'Add the aubergine and cook for 15 minutes, stirring and mashing until thick and jammy.'),
    ('Zaalouk (Aubergine Salad)', 7, 'Stir in the chopped coriander, parsley and lemon juice and serve warm or cold with bread.'),
    ('Kefta Mkaouara (Meatball Tagine with Eggs)', 1, 'Grate the onion and mix it with the minced beef, finely chopped parsley and coriander, 1 tsp cumin, 1 tsp paprika, pepper and 1 tsp salt until well combined.'),
    ('Kefta Mkaouara (Meatball Tagine with Eggs)', 2, 'Shape into walnut-sized meatballs, about 20 in total.'),
    ('Kefta Mkaouara (Meatball Tagine with Eggs)', 3, 'Heat the olive oil in a wide, lidded pan over medium heat and fry the crushed garlic for 30 seconds.'),
    ('Kefta Mkaouara (Meatball Tagine with Eggs)', 4, 'Add the tomatoes, tomato puree, water and remaining cumin, paprika and salt, and simmer for 8 minutes.'),
    ('Kefta Mkaouara (Meatball Tagine with Eggs)', 5, 'Add the meatballs, cover and cook on medium-low for 15 minutes, turning them once.'),
    ('Kefta Mkaouara (Meatball Tagine with Eggs)', 6, 'Make 4 small wells in the sauce and crack an egg into each. Cover and cook for 5 to 6 minutes until the whites are set but the yolks are still soft.'),
    ('Kefta Mkaouara (Meatball Tagine with Eggs)', 7, 'Sprinkle with extra herbs and serve straight from the pan with crusty bread.'),
    ('Chorba Frik (Lamb & Freekeh Soup)', 1, 'Cut the lamb into 2 cm cubes and finely chop the onion and celery.'),
    ('Chorba Frik (Lamb & Freekeh Soup)', 2, 'Heat the olive oil in a large pot over medium heat and brown the lamb for 5 minutes, then add the onion and celery and cook for 4 minutes.'),
    ('Chorba Frik (Lamb & Freekeh Soup)', 3, 'Stir in the tomato puree, cinnamon, pepper, turmeric and salt and cook for 2 minutes.'),
    ('Chorba Frik (Lamb & Freekeh Soup)', 4, 'Add the chopped tomatoes and water, bring to the boil, then cover and simmer for 40 minutes until the lamb is tender.'),
    ('Chorba Frik (Lamb & Freekeh Soup)', 5, 'Rinse the freekeh and add it with the chickpeas, then simmer for 20 to 25 minutes until the grains are soft.'),
    ('Chorba Frik (Lamb & Freekeh Soup)', 6, 'Stir in most of the chopped coriander and mint and cook for 3 more minutes.'),
    ('Chorba Frik (Lamb & Freekeh Soup)', 7, 'Serve hot with lemon wedges and the remaining herbs on top.'),
    ('Mhadjeb (Stuffed Semolina Flatbread)', 1, 'Mix the semolina with 1 tsp salt and gradually add the warm water, kneading for 8 minutes into a smooth, firm dough. Cover and rest for 20 minutes.'),
    ('Mhadjeb (Stuffed Semolina Flatbread)', 2, 'For the filling, heat 2 tbsp oil in a pan over medium heat and soften the finely chopped onions and green pepper for 8 minutes.'),
    ('Mhadjeb (Stuffed Semolina Flatbread)', 3, 'Add the crushed garlic, grated tomatoes, tomato puree, paprika, cumin, pepper and the remaining salt, and cook for 15 minutes until thick and almost dry. Cool completely.'),
    ('Mhadjeb (Stuffed Semolina Flatbread)', 4, 'Divide the dough into 8 balls, oil your hands and surface, and stretch each into a thin 15 cm square.'),
    ('Mhadjeb (Stuffed Semolina Flatbread)', 5, 'Spoon 2 tbsp filling along the centre of a square, then fold the sides over to enclose it into a flat rectangle. Repeat with the rest.'),
    ('Mhadjeb (Stuffed Semolina Flatbread)', 6, 'Heat a lightly oiled non-stick pan over medium heat and cook each mhadjeb for 3 to 4 minutes per side until golden and crisp.'),
    ('Mhadjeb (Stuffed Semolina Flatbread)', 7, 'Serve hot, cut in halves, with mint tea.'),
    ('Chtitha Djej (Spiced Chicken Stew)', 1, 'Season the chicken with half of the salt and pepper.'),
    ('Chtitha Djej (Spiced Chicken Stew)', 2, 'Heat the olive oil in a heavy pot over medium-high heat and brown the chicken for 3 to 4 minutes per side. Remove and set aside.'),
    ('Chtitha Djej (Spiced Chicken Stew)', 3, 'In the same pot soften the grated onion over medium heat for 5 minutes, then add the crushed garlic, tomato puree, paprika, harissa and cumin and cook for 2 minutes.'),
    ('Chtitha Djej (Spiced Chicken Stew)', 4, 'Add the chopped tomatoes, water and remaining salt, and return the chicken to the pot.'),
    ('Chtitha Djej (Spiced Chicken Stew)', 5, 'Cover and simmer on low heat for 30 minutes.'),
    ('Chtitha Djej (Spiced Chicken Stew)', 6, 'Add the chickpeas and olives and simmer uncovered for 10 minutes until the sauce is thick.'),
    ('Chtitha Djej (Spiced Chicken Stew)', 7, 'Scatter with chopped coriander and serve with bread or rice.'),
    ('Makrout (Date Semolina Cookies)', 1, 'Melt 150 g butter and rub it into the semolina, flour and salt with your fingertips for 5 minutes, then rest for 30 minutes.'),
    ('Makrout (Date Semolina Cookies)', 2, 'Add the orange blossom water and enough warm water to bring it together into a soft, smooth dough. Do not overwork it.'),
    ('Makrout (Date Semolina Cookies)', 3, 'Knead the dates with the cinnamon and 20 g softened butter into a smooth paste and roll into a log about 1.5 cm thick.'),
    ('Makrout (Date Semolina Cookies)', 4, 'Roll the dough into a log about 3 cm thick, press a channel along the top with your finger, lay the date log inside and pinch the dough closed over it.'),
    ('Makrout (Date Semolina Cookies)', 5, 'Roll gently to smooth, flatten the top slightly and cut into diamonds about 4 cm wide.'),
    ('Makrout (Date Semolina Cookies)', 6, 'Heat the oil in a deep pan to 170C and fry the cookies in batches for 3 to 4 minutes until golden. Drain on paper towels.'),
    ('Makrout (Date Semolina Cookies)', 7, 'Warm the honey gently and dip each hot cookie in it for 30 seconds, then place on a rack to set.'),
    ('Lablabi (Chickpea Soup)', 1, 'Put the chickpeas with their liquid, water, 3 crushed garlic cloves, 1 tsp cumin and the salt in a pot and simmer over medium heat for 20 minutes.'),
    ('Lablabi (Chickpea Soup)', 2, 'Mash a few chickpeas against the side of the pot to thicken the broth slightly.'),
    ('Lablabi (Chickpea Soup)', 3, 'Bring a small pan of water to a gentle boil and cook the eggs for 7 minutes for soft-boiled, then cool in cold water and peel.'),
    ('Lablabi (Chickpea Soup)', 4, 'Tear the stale bread into bite-size pieces and divide among 4 bowls.'),
    ('Lablabi (Chickpea Soup)', 5, 'Mix the remaining crushed garlic, remaining cumin, harissa, lemon juice and olive oil in a small bowl.'),
    ('Lablabi (Chickpea Soup)', 6, 'Ladle the hot chickpeas and broth over the bread and stir in the harissa mixture.'),
    ('Lablabi (Chickpea Soup)', 7, 'Top each bowl with a halved egg, flaked tuna, capers and olives and serve immediately.'),
    ('Brik à l''Oeuf (Egg Brik)', 1, 'Drain the tuna and mix with finely chopped parsley, sliced spring onions, capers, mozzarella, salt and pepper.'),
    ('Brik à l''Oeuf (Egg Brik)', 2, 'Lay one filo sheet flat (fold it in half if it is thin) and place a quarter of the tuna mixture in the centre, shaping a small nest in the middle.'),
    ('Brik à l''Oeuf (Egg Brik)', 3, 'Carefully crack an egg into the nest, keeping the yolk whole.'),
    ('Brik à l''Oeuf (Egg Brik)', 4, 'Quickly fold the filo over the filling into a triangle and seal the edges with a little water.'),
    ('Brik à l''Oeuf (Egg Brik)', 5, 'Heat the oil in a wide pan over medium-high heat to about 175C.'),
    ('Brik à l''Oeuf (Egg Brik)', 6, 'Slide in a brik and fry for 1 to 2 minutes per side until deep golden and crisp, spooning oil over the top. Drain on paper towels.'),
    ('Brik à l''Oeuf (Egg Brik)', 7, 'Serve hot with lemon wedges, taking care as the egg is still runny inside.'),
    ('Tunisian Fish Couscous', 1, 'Heat the olive oil in a large pot over medium heat and soften the chopped onion for 5 minutes.'),
    ('Tunisian Fish Couscous', 2, 'Add the crushed garlic, tomato puree, harissa, caraway and turmeric and cook for 2 minutes, stirring.'),
    ('Tunisian Fish Couscous', 3, 'Pour in the water, add 1 tsp salt and the carrots and potatoes (in large chunks), bring to the boil and simmer for 15 minutes.'),
    ('Tunisian Fish Couscous', 4, 'Add the courgettes and chickpeas and cook for 10 minutes.'),
    ('Tunisian Fish Couscous', 5, 'Cut the fish into large pieces, lay them on top of the vegetables, cover and cook gently for 8 to 10 minutes until the fish flakes.'),
    ('Tunisian Fish Couscous', 6, 'Meanwhile, put the couscous in a bowl with the remaining salt, pour over 300 ml boiling water, cover for 5 minutes, then fluff with a fork.'),
    ('Tunisian Fish Couscous', 7, 'Pile the couscous on a platter, top with the fish and vegetables, ladle over some broth and serve with lemon wedges.'),
    ('Sharba Libiya (Lamb & Orzo Soup)', 1, 'Cut the lamb into small 2 cm cubes and finely chop the onion.'),
    ('Sharba Libiya (Lamb & Orzo Soup)', 2, 'Heat the olive oil in a large pot over medium heat and brown the lamb for 5 minutes, then add the onion and cook for 4 minutes.'),
    ('Sharba Libiya (Lamb & Orzo Soup)', 3, 'Stir in the tomato puree, turmeric, paprika, cinnamon, pepper, half the dried mint and salt and cook for 2 minutes.'),
    ('Sharba Libiya (Lamb & Orzo Soup)', 4, 'Add the chopped tomatoes and water, bring to the boil, cover and simmer for 40 minutes until the lamb is tender.'),
    ('Sharba Libiya (Lamb & Orzo Soup)', 5, 'Add the chickpeas and orzo and cook for 10 minutes, stirring now and then, until the orzo is soft.'),
    ('Sharba Libiya (Lamb & Orzo Soup)', 6, 'Stir in the chopped parsley and remaining mint, and squeeze in the juice of half the lemon.'),
    ('Sharba Libiya (Lamb & Orzo Soup)', 7, 'Serve hot with the remaining lemon cut into wedges.'),
    ('Koshari', 1, 'Slice the onions thinly, toss with the flour and a pinch of salt, and fry in the oil in batches over medium-high heat for 8 to 10 minutes until dark golden and crisp. Drain on paper towels and keep the oil.'),
    ('Koshari', 2, 'Simmer the lentils in plenty of water for 20 minutes until just tender, then drain.'),
    ('Koshari', 3, 'In 1 tbsp of the onion oil, toast the vermicelli until golden, add the rice, 400 ml water and 0.5 tsp salt, bring to the boil, cover and cook on low for 15 minutes. Rest 5 minutes.'),
    ('Koshari', 4, 'Cook the macaroni in salted boiling water for 8 minutes and drain.'),
    ('Koshari', 5, 'For the sauce, fry the crushed garlic in 2 tbsp onion oil for 30 seconds, add the tomato puree, chopped tomatoes, 1 tsp cumin, chilli flakes and salt, and simmer for 15 minutes.'),
    ('Koshari', 6, 'For the dressing (daqqa), mix the vinegar with 3 tbsp water, 1 crushed garlic clove and the remaining cumin.'),
    ('Koshari', 7, 'Layer the rice, lentils, macaroni and warmed chickpeas in bowls, ladle over the tomato sauce, drizzle with the garlic vinegar and top with crispy onions.'),
    ('Molokhia with Chicken', 1, 'Put the chicken, halved onion, cardamom, bay leaves, 1 tsp salt and water in a large pot, bring to the boil and skim any foam. Simmer for 40 minutes until tender.'),
    ('Molokhia with Chicken', 2, 'Lift out the chicken, strain the broth and keep 1 litre. Brown the chicken pieces under a hot grill for 5 minutes if you like.'),
    ('Molokhia with Chicken', 3, 'Defrost the molokhia and bring 1 litre of broth to a gentle simmer in a clean pot.'),
    ('Molokhia with Chicken', 4, 'Add the molokhia and remaining salt and cook gently for 5 to 8 minutes without boiling hard or covering, stirring occasionally.'),
    ('Molokhia with Chicken', 5, 'Heat the ghee in a small pan over medium heat, fry the crushed garlic with the coriander for 1 minute until golden and fragrant.'),
    ('Molokhia with Chicken', 6, 'Pour the garlic mixture into the molokhia; it will sizzle. Stir and turn off the heat, then add a squeeze of lemon.'),
    ('Molokhia with Chicken', 7, 'Cook the rice according to the packet and serve with the molokhia and chicken.'),
    ('Hawawshi (Spiced Beef Bread)', 1, 'Heat the oven to 220C (200C fan).'),
    ('Hawawshi (Spiced Beef Bread)', 2, 'Finely chop the onion, pepper, tomato and parsley, and mix with the beef, crushed garlic, cumin, coriander, paprika, pepper and salt, kneading well with your hands.'),
    ('Hawawshi (Spiced Beef Bread)', 3, 'Cut each pita open along one side to make a pocket and brush the outside with melted butter.'),
    ('Hawawshi (Spiced Beef Bread)', 4, 'Stuff each pita with a quarter of the meat mixture and spread it evenly to the edges.'),
    ('Hawawshi (Spiced Beef Bread)', 5, 'Place on a baking tray and bake for 20 to 25 minutes, turning halfway, until the bread is crisp and golden and the meat is cooked through.'),
    ('Hawawshi (Spiced Beef Bread)', 6, 'Rest for 3 minutes, then cut into wedges and serve hot with salad and tahini or yogurt.'),
    ('Om Ali (Bread Pudding)', 1, 'Heat the oven to 200C (180C fan). Bake the puff pastry on a tray for 15 minutes until golden, puffed and crisp, then break into rough pieces.'),
    ('Om Ali (Bread Pudding)', 2, 'Lower the oven to 180C (160C fan).'),
    ('Om Ali (Bread Pudding)', 3, 'Heat the milk, half the cream, sugar and vanilla powder in a pan over medium heat until the sugar dissolves and it is just steaming.'),
    ('Om Ali (Bread Pudding)', 4, 'Spread the pastry pieces in a baking dish and scatter over the chopped pistachios and almonds, coconut and raisins.'),
    ('Om Ali (Bread Pudding)', 5, 'Pour the hot milk mixture over, pressing the pastry down gently so it soaks up the liquid.'),
    ('Om Ali (Bread Pudding)', 6, 'Drizzle the rest of the cream on top and sprinkle with cinnamon.'),
    ('Om Ali (Bread Pudding)', 7, 'Bake for 20 to 25 minutes until the top is golden and the edges bubble. Serve warm.'),
    ('Eggah (Herb Omelette)', 1, 'Heat the oven to 190C (170C fan).'),
    ('Eggah (Herb Omelette)', 2, 'Finely chop the parsley, coriander and spring onions.'),
    ('Eggah (Herb Omelette)', 3, 'Whisk the eggs in a large bowl with the flour, baking powder, cumin, pepper and salt until smooth.'),
    ('Eggah (Herb Omelette)', 4, 'Stir the herbs and spring onions into the eggs.'),
    ('Eggah (Herb Omelette)', 5, 'Heat the olive oil in an oven-safe non-stick pan over medium heat for 1 minute.'),
    ('Eggah (Herb Omelette)', 6, 'Pour in the egg mixture and cook for 3 minutes until the edges begin to set.'),
    ('Eggah (Herb Omelette)', 7, 'Transfer to the oven and bake for 12 to 15 minutes until puffed, golden and set in the centre.'),
    ('Eggah (Herb Omelette)', 8, 'Cut into wedges and serve warm or cold with pita and tomatoes.'),
    ('Mullah Bamia (Okra Stew)', 1, 'Cut the lamb into 3 cm pieces and finely chop the onions.'),
    ('Mullah Bamia (Okra Stew)', 2, 'Heat the oil in a heavy pot over medium heat, brown the lamb for 6 minutes, then add the onions and cook for 6 minutes until golden.'),
    ('Mullah Bamia (Okra Stew)', 3, 'Stir in the tomato puree, cumin, coriander, cinnamon and salt and cook for 2 minutes.'),
    ('Mullah Bamia (Okra Stew)', 4, 'Add the chopped tomatoes and water, cover and simmer on low heat for 45 minutes until the lamb is tender.'),
    ('Mullah Bamia (Okra Stew)', 5, 'Trim the okra tops and fry the okra in a little oil in a separate pan over medium-high heat for 5 minutes to reduce stickiness.'),
    ('Mullah Bamia (Okra Stew)', 6, 'Add the okra and crushed garlic to the stew and simmer, uncovered, for 15 minutes until the okra is tender and the sauce thick.'),
    ('Mullah Bamia (Okra Stew)', 7, 'Stir in the lemon juice and serve hot with rice.'),
    ('Labneh with Za''atar and Olive Oil', 1, 'If using homemade labneh, line a sieve with a clean cloth, add 600 g thick plain yogurt with a pinch of salt and let it drain in the fridge overnight until very thick; otherwise use ready-made labneh.'),
    ('Labneh with Za''atar and Olive Oil', 2, 'Spoon the labneh onto a shallow plate and use the back of a spoon to spread it into a wide, shallow bowl shape with a swirl.'),
    ('Labneh with Za''atar and Olive Oil', 3, 'Mix the za''atar with 1 tablespoon of the olive oil to make a loose paste.'),
    ('Labneh with Za''atar and Olive Oil', 4, 'Drizzle the remaining olive oil into the swirl and sprinkle the za''atar generously over the top.'),
    ('Labneh with Za''atar and Olive Oil', 5, 'Slice the cucumber and halve the cherry tomatoes, then arrange them around the plate with the olives and mint leaves.'),
    ('Labneh with Za''atar and Olive Oil', 6, 'Warm the pita in a dry pan over medium heat for 30 seconds on each side and serve straight away for scooping.'),
    ('Fatteh Hummus', 1, 'Heat the oven to 200C. Tear the pita into bite-size pieces, spread on a tray and bake for 8 to 10 minutes until golden and crisp.'),
    ('Fatteh Hummus', 2, 'Drain the chickpeas, reserving about 100 ml of the liquid. Warm the chickpeas with the reserved liquid and the cumin in a small pan over medium heat for 5 minutes, then keep warm.'),
    ('Fatteh Hummus', 3, 'Crush the garlic with a pinch of salt and whisk it into the yogurt with the tahini and lemon juice until smooth.'),
    ('Fatteh Hummus', 4, 'Spread the crisp pita over a large shallow dish and spoon the warm chickpeas and a little of their liquid on top.'),
    ('Fatteh Hummus', 5, 'Pour the yogurt sauce evenly over the chickpeas.'),
    ('Fatteh Hummus', 6, 'Melt the butter in a small pan over medium heat, add the pine nuts and cook for 1 to 2 minutes until golden, then stir in the paprika.'),
    ('Fatteh Hummus', 7, 'Pour the sizzling butter and pine nuts over the dish, scatter with parsley and serve immediately while the pita is still crunchy.'),
    ('Manaqish Jibneh (Cheese Flatbread)', 1, 'Stir the yeast and sugar into the warm water and leave for 5 minutes until foamy.'),
    ('Manaqish Jibneh (Cheese Flatbread)', 2, 'Mix the flour and salt in a large bowl, add the yeast water and 2 tablespoons of the olive oil, and knead for 8 minutes until smooth and elastic.'),
    ('Manaqish Jibneh (Cheese Flatbread)', 3, 'Cover the dough with a damp cloth and leave in a warm place for 1 hour until doubled in size.'),
    ('Manaqish Jibneh (Cheese Flatbread)', 4, 'Soak the akkawi cheese in cold water for 20 minutes to remove excess salt, then grate it and mix with the grated mozzarella.'),
    ('Manaqish Jibneh (Cheese Flatbread)', 5, 'Heat the oven to 240C with a baking tray inside. Divide the dough into 4 balls and roll each into a 20 cm round.'),
    ('Manaqish Jibneh (Cheese Flatbread)', 6, 'Press your fingertips into each round to dimple it, brush with the remaining oil and pile the cheese on top, leaving a 2 cm border.'),
    ('Manaqish Jibneh (Cheese Flatbread)', 7, 'Bake on the hot tray for 10 to 12 minutes until the edges are golden and the cheese is bubbling.'),
    ('Manaqish Jibneh (Cheese Flatbread)', 8, 'Serve warm with mint, tomato wedges and sliced cucumber on the side.'),
    ('Mfarakeh (Potato & Egg Scramble)', 1, 'Peel the potatoes and cut them into 1.5 cm cubes. Finely slice the onion.'),
    ('Mfarakeh (Potato & Egg Scramble)', 2, 'Heat the olive oil in a large non-stick frying pan over medium heat and fry the potatoes for 12 to 15 minutes, turning often, until golden and tender.'),
    ('Mfarakeh (Potato & Egg Scramble)', 3, 'Add the onion and a pinch of salt and cook for another 5 minutes until soft and lightly golden.'),
    ('Mfarakeh (Potato & Egg Scramble)', 4, 'Beat the eggs with the allspice, salt and pepper in a bowl.'),
    ('Mfarakeh (Potato & Egg Scramble)', 5, 'Reduce the heat to low, pour the eggs over the potatoes and stir gently for 2 to 3 minutes until just set but still soft.'),
    ('Mfarakeh (Potato & Egg Scramble)', 6, 'Sprinkle with sumac and chopped parsley and serve hot with bread.'),
    ('Tabbouleh', 1, 'Rinse the bulgur, drain, and soak in 2 tablespoons of the lemon juice for 20 minutes until softened.'),
    ('Tabbouleh', 2, 'Wash the parsley and mint well and dry them thoroughly with a clean towel or salad spinner so the salad is not watery.'),
    ('Tabbouleh', 3, 'Remove the thick stalks and chop the parsley very finely with a sharp knife, then finely chop the mint.'),
    ('Tabbouleh', 4, 'Dice the tomatoes into small cubes, discarding most of the watery seeds, and thinly slice the spring onions.'),
    ('Tabbouleh', 5, 'Combine the herbs, tomatoes, spring onions and bulgur in a large bowl.'),
    ('Tabbouleh', 6, 'Dress with the remaining lemon juice, olive oil, allspice and salt, and toss gently just before serving.'),
    ('Tabbouleh', 7, 'Serve in lettuce leaves for scooping.'),
    ('Warak Enab (Stuffed Vine Leaves)', 1, 'Rinse the vine leaves well in warm water, soak for 10 minutes to remove the brine, then drain and trim any hard stems.'),
    ('Warak Enab (Stuffed Vine Leaves)', 2, 'Rinse the rice and mix in a bowl with the minced lamb, finely chopped onion, parsley, mint, diced tomato, allspice, cinnamon, 2 tablespoons olive oil and salt.'),
    ('Warak Enab (Stuffed Vine Leaves)', 3, 'Lay a vine leaf shiny side down, put a heaped teaspoon of filling near the stem, fold in the sides and roll up tightly like a thin cigar.'),
    ('Warak Enab (Stuffed Vine Leaves)', 4, 'Slice the potatoes thickly and line the base of a heavy pot with them and the lamb chops. Pack the rolls tightly on top in layers, with the garlic cloves scattered in.'),
    ('Warak Enab (Stuffed Vine Leaves)', 5, 'Place an upturned plate on top to weigh the rolls down and pour in enough hot water to just cover, then add the lemon juice, remaining oil and a little salt.'),
    ('Warak Enab (Stuffed Vine Leaves)', 6, 'Bring to a boil, cover and simmer on low heat for 1 hour 15 minutes until the rice and leaves are tender.'),
    ('Warak Enab (Stuffed Vine Leaves)', 7, 'Let stand for 10 minutes, then invert onto a platter or serve straight from the pot with lemon wedges.'),
    ('Adas bi Hamod (Lentil & Chard Soup)', 1, 'Rinse the lentils and pick out any stones. Wash the silverbeet, strip the leaves from the stalks and chop both separately.'),
    ('Adas bi Hamod (Lentil & Chard Soup)', 2, 'Heat 2 tablespoons of the oil in a large pot over medium heat and cook the sliced onions for 8 minutes until golden.'),
    ('Adas bi Hamod (Lentil & Chard Soup)', 3, 'Add the lentils, water and cumin, bring to a boil, then cover and simmer on low for 20 minutes.'),
    ('Adas bi Hamod (Lentil & Chard Soup)', 4, 'Add the diced potatoes and chopped stalks and cook for 10 minutes, then stir in the leaves and cook for 5 minutes more until everything is tender.'),
    ('Adas bi Hamod (Lentil & Chard Soup)', 5, 'Crush the garlic with a pinch of salt and fry with the chopped coriander in the remaining oil for 1 minute until fragrant.'),
    ('Adas bi Hamod (Lentil & Chard Soup)', 6, 'Stir the garlic and coriander mixture into the soup with the lemon juice, season with salt and simmer for 3 more minutes before serving.'),
    ('Arayes (Grilled Meat-Stuffed Pita)', 1, 'Grate the onion and squeeze out the excess liquid, then finely chop the tomato and parsley.'),
    ('Arayes (Grilled Meat-Stuffed Pita)', 2, 'Mix the lamb, beef, onion, tomato, parsley, allspice, cumin, paprika, salt and pepper thoroughly with your hands.'),
    ('Arayes (Grilled Meat-Stuffed Pita)', 3, 'Cut each pita in half and open the pockets, then press about 3 tablespoons of the meat mixture into each half in a thin even layer.'),
    ('Arayes (Grilled Meat-Stuffed Pita)', 4, 'Brush the outsides of the pita with olive oil.'),
    ('Arayes (Grilled Meat-Stuffed Pita)', 5, 'Heat a griddle or large frying pan over medium heat and cook the stuffed pitas for 6 to 7 minutes per side, pressing gently, until the pita is crisp and the meat is cooked through.'),
    ('Arayes (Grilled Meat-Stuffed Pita)', 6, 'Cut into wedges and serve hot with yogurt for dipping.'),
    ('Sfeeha (Open Meat Pies)', 1, 'Mix the flour, yeast and salt, add the warm water and 2 tablespoons oil, and knead for 8 minutes until smooth. Cover and rest for 1 hour until doubled.'),
    ('Sfeeha (Open Meat Pies)', 2, 'Finely chop the onion and dice the tomatoes, draining off excess juice.'),
    ('Sfeeha (Open Meat Pies)', 3, 'Mix the lamb with the onion, tomato, pomegranate molasses, lemon juice, allspice, cinnamon, remaining olive oil, salt and pepper.'),
    ('Sfeeha (Open Meat Pies)', 4, 'Heat the oven to 230C. Divide the dough into 12 balls and roll each into a 10 cm round.'),
    ('Sfeeha (Open Meat Pies)', 5, 'Spread a heaped tablespoon of the filling over each round, leaving a small border, and press in a few pine nuts.'),
    ('Sfeeha (Open Meat Pies)', 6, 'Bake on lined trays for 12 to 15 minutes until the edges are golden and the meat is cooked.'),
    ('Sfeeha (Open Meat Pies)', 7, 'Serve warm with extra lemon wedges.'),
    ('Kibbeh bil Sanieh (Baked Kibbeh)', 1, 'Rinse the bulgur, soak it in cold water for 15 minutes, then drain and squeeze dry.'),
    ('Kibbeh bil Sanieh (Baked Kibbeh)', 2, 'Grate one onion and, in a food processor, blend it with the lean lamb, bulgur, 1 teaspoon allspice, cinnamon, salt, pepper and the ice cubes into a smooth paste, working in batches.'),
    ('Kibbeh bil Sanieh (Baked Kibbeh)', 3, 'For the filling, finely chop the remaining onions and fry in 1 tablespoon ghee over medium heat for 8 minutes until golden. Add the minced lamb and cook for 10 minutes until browned, then stir in the remaining allspice, salt, pepper and pine nuts. Cool slightly.'),
    ('Kibbeh bil Sanieh (Baked Kibbeh)', 4, 'Heat the oven to 200C and grease a 28 cm baking dish. Press half the kibbeh paste into the base in an even layer using wet hands.'),
    ('Kibbeh bil Sanieh (Baked Kibbeh)', 5, 'Spread the filling evenly on top, then flatten small pieces of the remaining paste in your palms and lay them over the filling, smoothing to seal.'),
    ('Kibbeh bil Sanieh (Baked Kibbeh)', 6, 'Score diamonds into the top with a knife, drizzle with the melted remaining ghee and the olive oil, and press a pine nut into each diamond if you like.'),
    ('Kibbeh bil Sanieh (Baked Kibbeh)', 7, 'Bake for 35 to 40 minutes until deep golden brown, cut along the scores and serve hot with cold yogurt.'),
    ('Shish Tawook', 1, 'Cut the chicken into 3 cm cubes.'),
    ('Shish Tawook', 2, 'Mix the yogurt, lemon juice, crushed garlic, tomato paste, olive oil, paprika, allspice, salt and pepper in a large bowl.'),
    ('Shish Tawook', 3, 'Add the chicken, coat well, cover and marinate in the fridge for at least 4 hours, or overnight.'),
    ('Shish Tawook', 4, 'Soak wooden skewers in water for 20 minutes, then thread the chicken onto them with wedges of red onion.'),
    ('Shish Tawook', 5, 'Heat a grill or griddle pan to medium-high and cook the skewers for 12 to 15 minutes, turning every 3 to 4 minutes, until charred and cooked through with no pink inside.'),
    ('Shish Tawook', 6, 'Rest for 5 minutes and serve with toum and warm bread.'),
    ('Kousa Mahshi (Stuffed Courgettes)', 1, 'Trim the courgettes and use a corer to hollow them out carefully, leaving walls about 5 mm thick. Wash well.'),
    ('Kousa Mahshi (Stuffed Courgettes)', 2, 'Rinse the rice and mix with the lamb, grated onion, allspice, cinnamon, 1 tablespoon tomato paste, 1 tablespoon olive oil and salt.'),
    ('Kousa Mahshi (Stuffed Courgettes)', 3, 'Fill each courgette about three-quarters full with the mixture, leaving room for the rice to swell.'),
    ('Kousa Mahshi (Stuffed Courgettes)', 4, 'Arrange the courgettes snugly in a wide pot in one layer.'),
    ('Kousa Mahshi (Stuffed Courgettes)', 5, 'Mix the chopped tomatoes, remaining tomato paste, crushed garlic, dried mint, lemon juice, water and salt, and pour over the courgettes.'),
    ('Kousa Mahshi (Stuffed Courgettes)', 6, 'Bring to a boil, then cover and simmer on low heat for 45 to 50 minutes until the courgettes are tender and the rice is cooked.'),
    ('Kousa Mahshi (Stuffed Courgettes)', 7, 'Serve warm with some of the sauce spooned over.'),
    ('Shakriyeh (Lamb in Yogurt Sauce)', 1, 'Place the lamb, halved onion, cinnamon stick, cardamom and 1 teaspoon salt in a pot with the water, bring to a boil and skim off any foam.'),
    ('Shakriyeh (Lamb in Yogurt Sauce)', 2, 'Cover and simmer on low heat for 1 hour 30 minutes until the lamb is very tender, then lift out the lamb and strain 300 ml of the stock.'),
    ('Shakriyeh (Lamb in Yogurt Sauce)', 3, 'In a large pot, whisk the yogurt with the cornflour and egg white until smooth, then heat over medium-low heat, stirring constantly in one direction, until it just comes to a gentle simmer.'),
    ('Shakriyeh (Lamb in Yogurt Sauce)', 4, 'Add the lamb and the strained stock and simmer on low for 15 minutes, stirring occasionally, without letting it boil hard.'),
    ('Shakriyeh (Lamb in Yogurt Sauce)', 5, 'Fry the crushed garlic and dried mint in 1 tablespoon of the ghee for 1 minute and stir into the sauce.'),
    ('Shakriyeh (Lamb in Yogurt Sauce)', 6, 'Meanwhile, cook the rice according to the packet. Toast the pine nuts in the remaining ghee until golden.'),
    ('Shakriyeh (Lamb in Yogurt Sauce)', 7, 'Serve the lamb and yogurt sauce over the rice, topped with the pine nuts.'),
    ('Musakhan (Sumac Onion Chicken)', 1, 'Rub the chicken with 1 tablespoon sumac, the allspice, cinnamon, cardamom, 2 tablespoons olive oil and salt, and leave for 20 minutes.'),
    ('Musakhan (Sumac Onion Chicken)', 2, 'Heat the oven to 200C. Roast the chicken on a tray for 40 to 45 minutes until golden and cooked through.'),
    ('Musakhan (Sumac Onion Chicken)', 3, 'Meanwhile, slice the onions thinly and cook with 4 tablespoons olive oil and salt in a wide pan over medium-low heat for 25 minutes until very soft and sweet.'),
    ('Musakhan (Sumac Onion Chicken)', 4, 'Stir in the remaining sumac and cook for 3 minutes more.'),
    ('Musakhan (Sumac Onion Chicken)', 5, 'Toast the pine nuts in a dry pan over medium heat for 2 minutes until golden.'),
    ('Musakhan (Sumac Onion Chicken)', 6, 'Brush the breads with olive oil and warm them in the oven for 5 minutes, then top each with a large spoonful of the onion mixture.'),
    ('Musakhan (Sumac Onion Chicken)', 7, 'Place the chicken on top, spoon over the roasting juices, scatter with pine nuts and serve with yogurt.'),
    ('Freekeh with Chicken', 1, 'Put the chicken, halved onion, cinnamon stick, bay leaves and salt in a pot with the water, bring to a boil and skim off the foam.'),
    ('Freekeh with Chicken', 2, 'Simmer on low heat for 35 minutes until cooked through, then remove the chicken and strain the broth.'),
    ('Freekeh with Chicken', 3, 'Rinse the freekeh several times and drain well.'),
    ('Freekeh with Chicken', 4, 'Heat 1 tablespoon ghee in a clean pot, add the freekeh, allspice and cumin and toast for 2 minutes, then add 700 ml of the hot broth.'),
    ('Freekeh with Chicken', 5, 'Bring to a boil, cover and simmer on low for 20 to 25 minutes until the liquid is absorbed and the grains are tender. Rest for 5 minutes.'),
    ('Freekeh with Chicken', 6, 'Brown the chicken pieces in a hot pan with a little of the remaining ghee for 4 minutes, and fry the almonds in the rest of the ghee until golden.'),
    ('Freekeh with Chicken', 7, 'Spread the freekeh on a platter, top with the chicken and almonds and serve with yogurt.'),
    ('Mansaf (Lamb in Jameed)', 1, 'Break the jameed into pieces, cover with warm water and soak overnight, then blend until smooth and strain through a sieve.'),
    ('Mansaf (Lamb in Jameed)', 2, 'Place the lamb in a pot with the onions, cardamom, bay leaves and 1.5 litres of water, bring to a boil, skim, and simmer for 1 hour 30 minutes until tender.'),
    ('Mansaf (Lamb in Jameed)', 3, 'Remove the lamb and strain the broth. Pour the jameed liquid and 500 ml of the broth into a pot and heat gently, stirring constantly in one direction, until it simmers; do not let it boil hard.'),
    ('Mansaf (Lamb in Jameed)', 4, 'Return the lamb to the jameed sauce and simmer on low for 30 minutes.'),
    ('Mansaf (Lamb in Jameed)', 5, 'Rinse the rice, cook it with the turmeric, 1 tablespoon ghee, salt and 700 ml water, covered on low heat for 18 minutes, then rest 5 minutes.'),
    ('Mansaf (Lamb in Jameed)', 6, 'Fry the almonds and pine nuts in the remaining ghee until golden.'),
    ('Mansaf (Lamb in Jameed)', 7, 'Layer the flatbread on a large platter, top with rice, then arrange the lamb on top, scatter with nuts and parsley, and serve the warm jameed sauce on the side.'),
    ('Iraqi Dolma', 1, 'Slice the tops off the peppers, tomatoes and aubergines and scoop out the insides, keeping the tomato flesh. Peel 2 onions, cut in half, boil for 10 minutes and separate the layers.'),
    ('Iraqi Dolma', 2, 'Rinse the rice and mix with the lamb, chopped parsley, chopped tomato flesh, half the tomato paste, the spices, 2 tablespoons oil and salt.'),
    ('Iraqi Dolma', 3, 'Rinse the vine leaves, then stuff the vegetables loosely (about three-quarters full) and roll the onion layers and vine leaves around about a tablespoon of filling each.'),
    ('Iraqi Dolma', 4, 'Pack everything snugly in a wide heavy pot, with the remaining onion sliced across the base.'),
    ('Iraqi Dolma', 5, 'Mix the water, remaining tomato paste, tamarind, sugar, remaining oil and salt, and pour over to just cover. Weigh the dolma down with an upturned plate.'),
    ('Iraqi Dolma', 6, 'Bring to a boil, cover and simmer on low heat for 1 hour 15 minutes until the rice and vegetables are soft.'),
    ('Iraqi Dolma', 7, 'Rest for 10 minutes, then invert onto a large platter or serve from the pot.'),
    ('Masgouf-Style Baked Fish', 1, 'Ask the fishmonger to scale and gut the fish and butterfly it open along the belly; pat dry with paper towels.'),
    ('Masgouf-Style Baked Fish', 2, 'Blend the tamarind, turmeric, crushed garlic, olive oil, lemon juice, cumin, salt and pepper into a marinade.'),
    ('Masgouf-Style Baked Fish', 3, 'Rub the marinade all over and inside the fish and leave to marinate for 30 minutes.'),
    ('Masgouf-Style Baked Fish', 4, 'Heat the oven to 220C. Slice the onions and tomatoes and spread them over a large roasting tray.'),
    ('Masgouf-Style Baked Fish', 5, 'Lay the fish skin side up on the vegetables and bake for 35 to 40 minutes, basting once with the juices, until the skin is crisp and the flesh flakes easily.'),
    ('Masgouf-Style Baked Fish', 6, 'Scatter with chopped parsley and serve with the roasted onions, tomatoes and flatbread.'),
    ('Muhammara', 1, 'Heat the oven to 230C. Roast the whole peppers on a tray for 25 minutes, turning once, until blistered and blackened in places.'),
    ('Muhammara', 2, 'Place the hot peppers in a bowl, cover with a plate for 10 minutes, then peel off the skins and remove the seeds.'),
    ('Muhammara', 3, 'Toast the walnuts in a dry pan over medium heat for 3 minutes until fragrant.'),
    ('Muhammara', 4, 'Blend the peppers, walnuts, breadcrumbs, pomegranate molasses, garlic, cumin, chilli flakes, lemon juice and 4 tablespoons olive oil until thick and slightly coarse.'),
    ('Muhammara', 5, 'Season with salt, spoon into a bowl and make a well in the centre.'),
    ('Muhammara', 6, 'Drizzle with the remaining oil and serve with warm pita.'),
    ('Baba Ghanoush', 1, 'Prick the aubergines all over with a fork and char them directly over a gas flame or under a hot grill for 20 to 25 minutes, turning often, until the skin is blackened and the flesh collapses.'),
    ('Baba Ghanoush', 2, 'Transfer to a bowl, cover and cool for 10 minutes, then slit open and scoop out the soft flesh, draining off any bitter liquid.'),
    ('Baba Ghanoush', 3, 'Chop the flesh finely with a knife for a rustic texture.'),
    ('Baba Ghanoush', 4, 'Mash the garlic with a pinch of salt and mix with the tahini, lemon juice and yogurt.'),
    ('Baba Ghanoush', 5, 'Stir the tahini mixture into the aubergine and season to taste.'),
    ('Baba Ghanoush', 6, 'Spread in a bowl, drizzle with olive oil and top with parsley and pomegranate seeds, serving with pita.'),
    ('Knafeh Nabulsieh', 1, 'Make the syrup: boil the sugar, water and lemon juice for 8 minutes until slightly thick, stir in the orange blossom water and cool.'),
    ('Knafeh Nabulsieh', 2, 'If using nabulsi cheese, slice it and soak in cold water for 3 hours, changing the water, to remove salt; mix with mozzarella for the best melt.'),
    ('Knafeh Nabulsieh', 3, 'Melt the butter and pull the kataifi apart into short strands by hand, then rub with the butter until every strand is coated.'),
    ('Knafeh Nabulsieh', 4, 'Heat the oven to 200C. Press two-thirds of the pastry firmly into the base of a buttered 25 cm round tin.'),
    ('Knafeh Nabulsieh', 5, 'Warm the milk with the semolina for 2 minutes, then spread over the pastry and cover with the sliced cheese.'),
    ('Knafeh Nabulsieh', 6, 'Top with the remaining pastry and press down gently, then bake for 25 to 30 minutes until deep golden.'),
    ('Knafeh Nabulsieh', 7, 'Turn out onto a plate, immediately pour over most of the cooled syrup, scatter with crushed pistachios and serve warm.'),
    ('Maamoul (Date-Filled Cookies)', 1, 'Melt the butter and mix into the semolina, flour, mahlab and 2 tablespoons icing sugar. Cover and rest for at least 2 hours, or overnight.'),
    ('Maamoul (Date-Filled Cookies)', 2, 'Warm the milk, stir in the yeast and orange blossom water, then work into the dough until it holds together and is soft.'),
    ('Maamoul (Date-Filled Cookies)', 3, 'Knead the date paste with the cinnamon and roll into 20 small balls.'),
    ('Maamoul (Date-Filled Cookies)', 4, 'Heat the oven to 180C. Take a walnut-sized piece of dough, flatten it in your palm, put a date ball in the centre and seal the dough around it.'),
    ('Maamoul (Date-Filled Cookies)', 5, 'Press into a maamoul mould, or flatten gently and pinch the top with tongs for decoration, then tap out onto a lined tray.'),
    ('Maamoul (Date-Filled Cookies)', 6, 'Bake for 18 to 20 minutes until pale golden on the base; the tops should stay pale.'),
    ('Maamoul (Date-Filled Cookies)', 7, 'Cool completely on the tray and dust with icing sugar.'),
    ('Balaleet (Sweet Vermicelli with Eggs)', 1, 'Soak the saffron threads in 3 tablespoons of hot water for 10 minutes.'),
    ('Balaleet (Sweet Vermicelli with Eggs)', 2, 'Melt the ghee in a wide pan over medium heat, break the vermicelli into short pieces and fry for 3 to 4 minutes, stirring constantly, until golden brown.'),
    ('Balaleet (Sweet Vermicelli with Eggs)', 3, 'Pour in the water, add the sugar, cardamom and a pinch of salt, and bring to the boil. Reduce to low heat, cover and cook for 8 to 10 minutes until the noodles are tender and the liquid is absorbed.'),
    ('Balaleet (Sweet Vermicelli with Eggs)', 4, 'Stir in the saffron liquid and rose water, then cover and leave on the lowest heat for 3 more minutes. Transfer to a serving plate.'),
    ('Balaleet (Sweet Vermicelli with Eggs)', 5, 'Whisk the eggs with a pinch of salt and the turmeric. Heat the oil in a non-stick pan over medium heat and pour in the eggs.'),
    ('Balaleet (Sweet Vermicelli with Eggs)', 6, 'Cook for 2 to 3 minutes until set, without folding, to make a thin flat omelette. Slide it over the vermicelli and serve warm.'),
    ('Chebab (Saffron Pancakes)', 1, 'Crush the saffron and steep it in 2 tablespoons of hot water for 10 minutes.'),
    ('Chebab (Saffron Pancakes)', 2, 'In a large bowl mix the flour, semolina, yeast, sugar, cardamom and salt. Add the eggs, milk, warm water and saffron liquid and whisk to a smooth, thin batter.'),
    ('Chebab (Saffron Pancakes)', 3, 'Cover the bowl and leave in a warm place for 45 minutes until bubbly.'),
    ('Chebab (Saffron Pancakes)', 4, 'Heat a non-stick frying pan over medium heat and brush with a little ghee.'),
    ('Chebab (Saffron Pancakes)', 5, 'Pour in a ladle of batter and spread slightly. Cook for 2 minutes until bubbles form and the underside is golden, then flip and cook 1 minute more.'),
    ('Chebab (Saffron Pancakes)', 6, 'Repeat with the remaining batter, adding ghee as needed, and serve warm with cream cheese and a drizzle of date syrup.'),
    ('Kuku Sabzi (Herb Frittata)', 1, 'Wash the herbs, spinach and spring onions well, dry them thoroughly and chop very finely. Chop the walnuts roughly.'),
    ('Kuku Sabzi (Herb Frittata)', 2, 'Heat the oven to 180C. Whisk the eggs in a large bowl with the flour, baking powder, turmeric, salt and pepper.'),
    ('Kuku Sabzi (Herb Frittata)', 3, 'Fold the chopped herbs, spinach, spring onions, walnuts and barberries into the eggs until the mixture looks mostly green.'),
    ('Kuku Sabzi (Herb Frittata)', 4, 'Heat 3 tablespoons of oil in an oven-proof 24 cm non-stick pan over medium heat and pour in the mixture, pressing it flat.'),
    ('Kuku Sabzi (Herb Frittata)', 5, 'Cook on the hob for 4 minutes until the edges set, then bake for 20 minutes until firm and golden on top.'),
    ('Kuku Sabzi (Herb Frittata)', 6, 'Rest for 5 minutes, cut into wedges and serve warm or cold with yogurt and flatbread.'),
    ('Harees (Wheat & Chicken Porridge)', 1, 'Rinse the cracked wheat and soak it in cold water for at least 2 hours, or overnight, then drain.'),
    ('Harees (Wheat & Chicken Porridge)', 2, 'Put the chicken, halved onion, cinnamon stick, cardamom pods, salt and water in a large heavy pot. Bring to the boil, skim off any foam and simmer on low for 45 minutes until the chicken is very tender.'),
    ('Harees (Wheat & Chicken Porridge)', 3, 'Lift out the chicken, discard the bones and skin, and shred the meat finely. Remove the onion and spices from the stock.'),
    ('Harees (Wheat & Chicken Porridge)', 4, 'Add the wheat to the stock and cook on low heat for 1 hour, stirring every 10 minutes, until the grains soften.'),
    ('Harees (Wheat & Chicken Porridge)', 5, 'Return the chicken to the pot and cook for another 45 to 60 minutes, stirring often, then mash vigorously with a wooden spoon or potato masher until thick and smooth like porridge.'),
    ('Harees (Wheat & Chicken Porridge)', 6, 'Melt the ghee with the cinnamon and cumin, then spoon the harees into bowls and pour the spiced ghee on top.'),
    ('Jareesh (Crushed Wheat with Chicken)', 1, 'Rinse the crushed wheat and soak it in cold water for 2 hours, then drain.'),
    ('Jareesh (Crushed Wheat with Chicken)', 2, 'Melt 2 tablespoons of ghee in a large pot and fry 1 chopped onion and the crushed garlic for 5 minutes over medium heat until golden.'),
    ('Jareesh (Crushed Wheat with Chicken)', 3, 'Add the chicken, cumin, coriander, cardamom, salt, pepper and the pierced dried lime. Cook for 5 minutes, then pour in the water and simmer for 40 minutes.'),
    ('Jareesh (Crushed Wheat with Chicken)', 4, 'Remove the chicken, shred the meat and set it aside. Add the wheat to the stock and cook on low heat for 45 minutes, stirring often, until soft.'),
    ('Jareesh (Crushed Wheat with Chicken)', 5, 'Stir in the yogurt, milk and shredded chicken and cook for 15 minutes more, mashing lightly, until thick and creamy.'),
    ('Jareesh (Crushed Wheat with Chicken)', 6, 'Thinly slice the remaining onions and fry in the rest of the ghee for 12 to 15 minutes until deep brown. Serve the jareesh topped with the crisp onions.'),
    ('Saltah', 1, 'Soak the fenugreek seeds in cold water for 4 hours or overnight, then drain and rinse well three times.'),
    ('Saltah', 2, 'Heat the oil in a pot over medium heat, fry the chopped onion for 6 minutes, then add the diced beef and brown for 8 minutes.'),
    ('Saltah', 3, 'Add half the garlic, cumin, coriander, turmeric, tomato paste, chopped tomatoes and salt. Cook for 5 minutes, then add the water and simmer, covered, for 40 minutes until the beef is tender.'),
    ('Saltah', 4, 'Add the diced potatoes and cook for 15 more minutes until soft. Keep the stew at a gentle simmer.'),
    ('Saltah', 5, 'Blend the soaked fenugreek with the remaining garlic, green chilli, fresh coriander, a pinch of salt and 100 ml of cold water for 2 minutes until very frothy.'),
    ('Saltah', 6, 'Pour the stew into small hot stone or heavy bowls, spoon the whipped hilbeh on top and serve immediately with flatbread.'),
    ('Ash Reshteh (Noodle & Bean Soup)', 1, 'Soak the chickpeas and kidney beans in cold water overnight, then drain.'),
    ('Ash Reshteh (Noodle & Bean Soup)', 2, 'Fry 1 chopped onion in 2 tablespoons of oil until golden, stir in the turmeric, then add the soaked beans, chickpeas and water. Simmer for 45 minutes until nearly tender.'),
    ('Ash Reshteh (Noodle & Bean Soup)', 3, 'Add the lentils, salt and pepper and cook for 15 minutes more.'),
    ('Ash Reshteh (Noodle & Bean Soup)', 4, 'Stir in the finely chopped parsley, coriander, spinach and spring onions and simmer for 10 minutes.'),
    ('Ash Reshteh (Noodle & Bean Soup)', 5, 'Break the noodles in half, add them and cook for 8 to 10 minutes, stirring so they do not stick, until soft.'),
    ('Ash Reshteh (Noodle & Bean Soup)', 6, 'Slice the second onion and fry in the remaining oil for 12 minutes until dark golden; remove half, then add the garlic and mint to the pan and fry for 30 seconds.'),
    ('Ash Reshteh (Noodle & Bean Soup)', 7, 'Serve the soup in bowls topped with yogurt, fried onion and the garlic mint oil.'),
    ('Bolani (Potato Stuffed Flatbread)', 1, 'Mix the flour, 1 teaspoon of salt, 1 tablespoon of oil and warm water to a soft dough. Knead for 5 minutes, cover and rest for 30 minutes.'),
    ('Bolani (Potato Stuffed Flatbread)', 2, 'Boil the peeled, chopped potatoes for 15 minutes until soft, drain and mash. Mix in the chopped spring onions, fresh coriander, finely chopped chilli, ground coriander, chilli flakes and remaining salt.'),
    ('Bolani (Potato Stuffed Flatbread)', 3, 'Divide the dough into 4 balls and roll each into a thin circle about 22 cm wide.'),
    ('Bolani (Potato Stuffed Flatbread)', 4, 'Spread a quarter of the filling over half of each circle, fold the other half over and press the edges firmly to seal.'),
    ('Bolani (Potato Stuffed Flatbread)', 5, 'Heat 1 tablespoon of oil in a large frying pan over medium heat and fry each bolani for 3 to 4 minutes per side until golden and blistered, adding oil as needed.'),
    ('Bolani (Potato Stuffed Flatbread)', 6, 'Stir the dried mint into the yogurt and serve it with the hot bolani.'),
    ('Chicken Mandi', 1, 'Mix the cumin, coriander, turmeric, cardamom, pepper, cinnamon, tomato paste, 1 tablespoon of ghee, crushed garlic and 1 teaspoon of salt into a paste and rub it over the chicken. Marinate for 1 hour or overnight.'),
    ('Chicken Mandi', 2, 'Heat the oven to 200C. Place the chicken on a rack set over a deep tray, cover tightly with foil and roast for 50 minutes, then uncover for 10 minutes to brown.'),
    ('Chicken Mandi', 3, 'Meanwhile rinse the rice until the water runs clear and soak it for 20 minutes.'),
    ('Chicken Mandi', 4, 'Fry the sliced onion in the remaining ghee for 8 minutes, add the pierced dried limes and 1 teaspoon of salt, then add the water and bring to the boil.'),
    ('Chicken Mandi', 5, 'Add the drained rice, cover and cook on low heat for 15 minutes, then rest for 10 minutes off the heat.'),
    ('Chicken Mandi', 6, 'Toast the almonds in a dry pan for 2 minutes. Pile the rice onto a platter, place the chicken on top and scatter over the raisins and almonds.'),
    ('Fahsa (Shredded Lamb Stew)', 1, 'Melt the ghee in a heavy pot over medium heat and fry the chopped onions for 8 minutes until golden.'),
    ('Fahsa (Shredded Lamb Stew)', 2, 'Add the lamb chunks and brown on all sides for 8 minutes, then stir in the garlic, tomato paste and all the spices for 2 minutes.'),
    ('Fahsa (Shredded Lamb Stew)', 3, 'Pour in the water, add the salt, bring to the boil and skim. Cover and simmer on low for 2 hours until the meat falls apart.'),
    ('Fahsa (Shredded Lamb Stew)', 4, 'Lift out the lamb, shred it with two forks and return it to the broth.'),
    ('Fahsa (Shredded Lamb Stew)', 5, 'Add the chopped tomatoes and green chillies and simmer uncovered for 15 minutes until the broth is slightly thickened.'),
    ('Fahsa (Shredded Lamb Stew)', 6, 'Stir in the chopped fresh coriander and serve very hot in bowls with flatbread for scooping.'),
    ('Machboos Samak (Spiced Fish & Rice)', 1, 'Rub the fish with turmeric, 1 teaspoon of baharat and 1 teaspoon of salt and leave for 15 minutes. Rinse the rice and soak it for 20 minutes.'),
    ('Machboos Samak (Spiced Fish & Rice)', 2, 'Heat 3 tablespoons of oil and fry the fish for 2 minutes per side until golden but not cooked through. Set aside.'),
    ('Machboos Samak (Spiced Fish & Rice)', 3, 'In the same pot, fry the sliced onions in the remaining oil for 8 minutes, then add the garlic, cinnamon, remaining baharat, tomato paste, chopped tomatoes and pierced dried limes. Cook for 8 minutes into a thick sauce.'),
    ('Machboos Samak (Spiced Fish & Rice)', 4, 'Pour in the water, add the chilli and 1 teaspoon of salt and bring to the boil. Add the drained rice and stir once.'),
    ('Machboos Samak (Spiced Fish & Rice)', 5, 'Cover and cook on low heat for 12 minutes, then lay the fish on top, cover again and steam for 10 minutes until the rice is fluffy and the fish flakes.'),
    ('Machboos Samak (Spiced Fish & Rice)', 6, 'Scatter with coriander and serve straight from the pot.'),
    ('Shuwa-Style Slow-Roast Lamb', 1, 'Blend the garlic, all the spices, vinegar, tamarind, oil and salt into a thick paste.'),
    ('Shuwa-Style Slow-Roast Lamb', 2, 'Pierce the lamb all over with a knife and rub in the paste, working it deep into the cuts. Cover and marinate in the fridge for at least 12 hours.'),
    ('Shuwa-Style Slow-Roast Lamb', 3, 'Heat the oven to 160C. Soften the banana leaves over a flame or in hot water for 30 seconds, then wrap the lamb tightly in them and then in foil.'),
    ('Shuwa-Style Slow-Roast Lamb', 4, 'Place on a deep tray and roast for 4 to 5 hours until the meat falls off the bone.'),
    ('Shuwa-Style Slow-Roast Lamb', 5, 'While the lamb rests, rinse the rice and cook it in lightly salted boiling water for 10 minutes, drain, then steam covered for 10 minutes.'),
    ('Shuwa-Style Slow-Roast Lamb', 6, 'Unwrap the lamb, shred the meat into large pieces and serve on the rice with the pan juices spooned over.'),
    ('Ghormeh Sabzi', 1, 'Fry the chopped onions in 2 tablespoons of oil for 10 minutes until golden, add the turmeric and the lamb cubes and brown for 8 minutes.'),
    ('Ghormeh Sabzi', 2, 'Add the water, salt and pepper, cover and simmer on low heat for 1 hour.'),
    ('Ghormeh Sabzi', 3, 'Finely chop the parsley, coriander and spring onions. Fry them in the remaining oil over medium-low heat for 15 minutes, stirring often, until dark green and fragrant, then stir in the fenugreek leaves.'),
    ('Ghormeh Sabzi', 4, 'Add the fried herbs and the pierced dried limes to the lamb and simmer for 45 minutes.'),
    ('Ghormeh Sabzi', 5, 'Add the drained kidney beans and cook for 15 minutes more until the oil rises and the sauce is dark and thick.'),
    ('Ghormeh Sabzi', 6, 'Meanwhile boil the rice in salted water for 10 minutes, drain, and steam covered on low heat for 15 minutes, then stir in saffron dissolved in 2 tablespoons of hot water. Serve the stew over the rice.'),
    ('Fesenjan (Pomegranate Walnut Chicken)', 1, 'Toast the walnuts in a dry pan over medium heat for 5 minutes, cool slightly, then grind them to a coarse paste in a food processor.'),
    ('Fesenjan (Pomegranate Walnut Chicken)', 2, 'Fry the sliced onions in the oil for 10 minutes until golden, add the turmeric and chicken thighs and brown for 6 minutes.'),
    ('Fesenjan (Pomegranate Walnut Chicken)', 3, 'Add the ground walnuts, water, salt, pepper and cinnamon. Bring to the boil, cover and simmer on very low heat for 45 minutes, stirring often to prevent sticking.'),
    ('Fesenjan (Pomegranate Walnut Chicken)', 4, 'Stir in the pomegranate molasses and sugar and cook uncovered for 25 minutes until the sauce is thick, dark brown and the oil has risen. Adjust sweet-sour balance to taste.'),
    ('Fesenjan (Pomegranate Walnut Chicken)', 5, 'Boil the rice in salted water for 10 minutes, drain, and steam covered for 15 minutes.'),
    ('Fesenjan (Pomegranate Walnut Chicken)', 6, 'Serve the chicken and sauce over the rice, scattered with pomegranate seeds.'),
    ('Jeweled Rice (Javaher Polow)', 1, 'Rinse the rice and soak it for 2 hours in water with 1 tablespoon of salt. Steep the saffron in 3 tablespoons of hot water.'),
    ('Jeweled Rice (Javaher Polow)', 2, 'Peel the orange zest into thin strips and julienne the carrots. Simmer the zest in water for 5 minutes, drain, then simmer the zest and carrot with the sugar and 250 ml water for 10 minutes until syrupy.'),
    ('Jeweled Rice (Javaher Polow)', 3, 'Fry the barberries in 1 tablespoon of butter for 30 seconds, then toast the pistachios and almonds in a dry pan for 2 minutes.'),
    ('Jeweled Rice (Javaher Polow)', 4, 'Boil plenty of water with the remaining salt, add the drained rice and cook for 7 minutes until al dente, then drain.'),
    ('Jeweled Rice (Javaher Polow)', 5, 'Melt the rest of the butter with the oil in a non-stick pot. Mix 2 tablespoons of saffron water with the yogurt and a cup of rice, and spread this at the bottom to make a tahdig.'),
    ('Jeweled Rice (Javaher Polow)', 6, 'Mound the remaining rice on top in layers with the carrots, zest, barberries and nuts, poke holes with a spoon handle, cover with a towel-wrapped lid and cook on low for 45 minutes.'),
    ('Jeweled Rice (Javaher Polow)', 7, 'Drizzle the remaining saffron water over the top and serve, breaking up the golden crust.'),
    ('Joojeh Kabab (Saffron Chicken Kebab)', 1, 'Steep the saffron in 3 tablespoons of hot water for 10 minutes.'),
    ('Joojeh Kabab (Saffron Chicken Kebab)', 2, 'Grate the onion and squeeze out the juice. Mix the onion with the yogurt, lemon juice, saffron water, oil, crushed garlic, salt, pepper and turmeric.'),
    ('Joojeh Kabab (Saffron Chicken Kebab)', 3, 'Cut the chicken into large chunks, coat in the marinade and refrigerate for at least 4 hours or overnight.'),
    ('Joojeh Kabab (Saffron Chicken Kebab)', 4, 'Thread the chicken onto skewers and thread the whole tomatoes on separate skewers.'),
    ('Joojeh Kabab (Saffron Chicken Kebab)', 5, 'Grill over hot coals or a very hot grill pan for 12 to 15 minutes, turning every 3 minutes, until charred and cooked through, and grill the tomatoes until blistered.'),
    ('Joojeh Kabab (Saffron Chicken Kebab)', 6, 'Brush the chicken with melted butter and serve with the tomatoes and warm flatbread.'),
    ('Kabuli Pulao', 1, 'Soak the rice in cold water for 30 minutes. Fry the sliced onions in 4 tablespoons of oil for 12 minutes until deep brown, then add the lamb and brown for 8 minutes.'),
    ('Kabuli Pulao', 2, 'Add the water, salt, cumin and pepper, cover and simmer for 1 hour until the lamb is tender. Remove the lamb and measure out 650 ml of stock.'),
    ('Kabuli Pulao', 3, 'Cut the carrots into matchsticks. Fry in 1 tablespoon of oil for 5 minutes, add the sugar and cook 3 minutes until caramelised, then add the raisins for 1 minute. Set aside.'),
    ('Kabuli Pulao', 4, 'In a heavy pot caramelise 1 tablespoon of sugar with the remaining oil until dark brown, stir in the stock and bring to the boil.'),
    ('Kabuli Pulao', 5, 'Add the drained rice, cardamom, cinnamon and the lamb, cover and cook on low for 15 minutes, then rest for 10 minutes.'),
    ('Kabuli Pulao', 6, 'Toast the nuts in a dry pan, then pile the rice onto a platter, top with the carrots, raisins and nuts.'),
    ('Mantu (Beef Dumplings)', 1, 'Knead the flour, 150 ml water and a pinch of salt into a firm dough for 8 minutes, cover and rest for 30 minutes.'),
    ('Mantu (Beef Dumplings)', 2, 'Finely chop 1 onion and mix with the beef, coriander, pepper and 1 teaspoon of salt.'),
    ('Mantu (Beef Dumplings)', 3, 'Roll the dough very thin, cut into 8 cm squares, put a spoonful of filling in the centre, and pinch the corners together to seal.'),
    ('Mantu (Beef Dumplings)', 4, 'Fry the second chopped onion in oil for 8 minutes, add the tomato paste, chopped tomatoes and cooked split peas with 200 ml water, and simmer for 20 minutes into a sauce.'),
    ('Mantu (Beef Dumplings)', 5, 'Steam the mantu in a lightly oiled steamer for 25 minutes until the dough is translucent.'),
    ('Mantu (Beef Dumplings)', 6, 'Mix the yogurt with crushed garlic and a pinch of salt. Spoon yogurt on a plate, arrange the mantu on top, pour over the sauce and sprinkle with mint.'),
    ('Mutabbaq (Stuffed Pan-Fried Pastry)', 1, 'Mix the flour, 1 teaspoon of salt, warm water and 2 tablespoons of oil into a soft dough, knead for 5 minutes, divide into 6 balls, coat in oil and rest for 30 minutes.'),
    ('Mutabbaq (Stuffed Pan-Fried Pastry)', 2, 'Fry the chopped onion and beef in 1 tablespoon of oil over medium-high heat for 8 minutes until browned, then add the cumin, coriander, pepper and remaining salt. Cool slightly.'),
    ('Mutabbaq (Stuffed Pan-Fried Pastry)', 3, 'Beat the eggs and stir in the beef, chopped spring onions and parsley.'),
    ('Mutabbaq (Stuffed Pan-Fried Pastry)', 4, 'Stretch one dough ball on an oiled surface into a very thin 30 cm square.'),
    ('Mutabbaq (Stuffed Pan-Fried Pastry)', 5, 'Spoon a sixth of the filling in the centre and fold the four sides over to make a sealed square parcel.'),
    ('Mutabbaq (Stuffed Pan-Fried Pastry)', 6, 'Fry the parcels in a lightly oiled pan over medium heat for 3 to 4 minutes per side until deep golden and the egg is set, then cut into pieces and serve hot with lemon.'),
    ('Luqaimat (Date Syrup Dumplings)', 1, 'Mix the flour, cornflour, yeast, sugar, cardamom and salt in a bowl, then stir in the milk, warm water and saffron to make a thick, sticky batter.'),
    ('Luqaimat (Date Syrup Dumplings)', 2, 'Cover and let it rise in a warm place for 1 hour until doubled and bubbly.'),
    ('Luqaimat (Date Syrup Dumplings)', 3, 'Heat the oil in a deep pan to 170C, or until a drop of batter sizzles and floats immediately.'),
    ('Luqaimat (Date Syrup Dumplings)', 4, 'Scoop the batter with a wet spoon or squeeze through your fist and drop small balls into the hot oil, frying 4 to 5 balls at once.'),
    ('Luqaimat (Date Syrup Dumplings)', 5, 'Fry for 3 to 4 minutes, turning, until deep golden, then drain on kitchen paper.'),
    ('Luqaimat (Date Syrup Dumplings)', 6, 'Toss in warm date syrup, sprinkle with toasted sesame seeds and serve straight away.'),
    ('Sholeh Zard (Saffron Rice Pudding)', 1, 'Rinse the rice well until the water runs clear. Steep the saffron in 4 tablespoons of hot water for 15 minutes.'),
    ('Sholeh Zard (Saffron Rice Pudding)', 2, 'Put the rice and water in a heavy pot, bring to the boil, then simmer on low heat for 35 to 40 minutes, stirring occasionally, until the grains break down and it is thick.'),
    ('Sholeh Zard (Saffron Rice Pudding)', 3, 'Stir in the sugar, saffron liquid and butter and cook for 10 minutes more, stirring often, until glossy and the colour is deep yellow.'),
    ('Sholeh Zard (Saffron Rice Pudding)', 4, 'Add the rose water and cardamom and cook for 5 minutes.'),
    ('Sholeh Zard (Saffron Rice Pudding)', 5, 'Pour the pudding into a serving dish or individual bowls and smooth the top. Cool for 1 hour, then chill for 2 hours until set.'),
    ('Sholeh Zard (Saffron Rice Pudding)', 6, 'Decorate with lines of cinnamon, pistachios and almonds before serving.'),
    ('Shor Nakhod (Chickpea & Potato Salad)', 1, 'Peel the potatoes, cut into 2 cm cubes and boil in salted water for 12 to 15 minutes until just tender. Drain and cool for 10 minutes.'),
    ('Shor Nakhod (Chickpea & Potato Salad)', 2, 'Drain and rinse the chickpeas.'),
    ('Shor Nakhod (Chickpea & Potato Salad)', 3, 'Thinly slice the red onion and finely chop the coriander, mint and chilli.'),
    ('Shor Nakhod (Chickpea & Potato Salad)', 4, 'Whisk the lemon juice, vinegar, olive oil, cumin, chilli flakes, salt and pepper in a large bowl.'),
    ('Shor Nakhod (Chickpea & Potato Salad)', 5, 'Add the potatoes, chickpeas, onion and herbs and gently toss until coated.'),
    ('Shor Nakhod (Chickpea & Potato Salad)', 6, 'Leave for 15 minutes so the flavours soak in, then serve at room temperature.'),
    ('Aloo Paratha', 1, 'Mix the flour with 1 tsp salt, then add the water gradually and knead for 5 minutes into a soft dough. Cover and rest for 20 minutes.'),
    ('Aloo Paratha', 2, 'Meanwhile boil the whole potatoes in salted water for 20 minutes until tender, then drain, peel and mash until completely smooth with no lumps.'),
    ('Aloo Paratha', 3, 'Mix the mash with finely chopped green chillies, chopped coriander, cumin, ground coriander, chilli powder, dried pomegranate seeds and the remaining salt.'),
    ('Aloo Paratha', 4, 'Divide the dough into 8 balls. Roll one into a 10 cm circle, place a spoonful of filling in the centre, pinch the edges closed to seal, then gently flatten and roll to a 16 cm round, dusting with flour as needed.'),
    ('Aloo Paratha', 5, 'Heat a flat pan or tawa over medium-high heat. Cook a paratha for 1 minute until pale spots appear, flip, brush with ghee and cook 1-2 minutes.'),
    ('Aloo Paratha', 6, 'Flip again, brush the other side with ghee and cook until golden brown with crisp spots, about 1 minute. Keep warm in a cloth while you cook the rest and serve with yogurt.'),
    ('Masala Omelette', 1, 'Finely chop the onion, tomato, green chillies and coriander. Squeeze the chopped tomato lightly to remove extra juice.'),
    ('Masala Omelette', 2, 'Crack the eggs into a large bowl and add the turmeric, chilli powder and salt. Whisk for 1 minute until frothy.'),
    ('Masala Omelette', 3, 'Stir the chopped vegetables and coriander into the eggs.'),
    ('Masala Omelette', 4, 'Heat 1 tbsp oil in a non-stick frying pan over medium heat. Pour in a quarter of the mixture and tilt to spread it evenly.'),
    ('Masala Omelette', 5, 'Cook for 2 minutes until the edges set, dot with a little butter, flip and cook 1 minute more until golden.'),
    ('Masala Omelette', 6, 'Repeat with the remaining mixture, adding oil each time, and serve hot with toast.'),
    ('Mas Huni (Tuna & Coconut) with Roshi', 1, 'Mix the flour with 0.5 tsp salt, add the warm water and oil, and knead for 5 minutes into a smooth soft dough. Cover and rest for 15 minutes.'),
    ('Mas Huni (Tuna & Coconut) with Roshi', 2, 'Drain the tuna well and flake it into a bowl with a fork.'),
    ('Mas Huni (Tuna & Coconut) with Roshi', 3, 'Finely slice the onion, green chillies and curry leaves. Add them to the tuna with the grated coconut and the remaining salt.'),
    ('Mas Huni (Tuna & Coconut) with Roshi', 4, 'Squeeze in the lime juice and mix well with your hands, pressing so the flavours combine.'),
    ('Mas Huni (Tuna & Coconut) with Roshi', 5, 'Divide the dough into 8 balls and roll each into a very thin round about 18 cm wide.'),
    ('Mas Huni (Tuna & Coconut) with Roshi', 6, 'Cook each roshi in a dry pan over medium-high heat for about 1 minute per side until it has light brown spots. Serve warm with the mas huni.'),
    ('Chapli Kebab', 1, 'Coarsely crush the coriander seeds and pomegranate seeds in a mortar. Finely chop the onion, tomato, chillies and coriander.'),
    ('Chapli Kebab', 2, 'In a large bowl combine the beef, chopped vegetables, crushed seeds, cumin, chilli flakes, garam masala, salt, egg and cornflour.'),
    ('Chapli Kebab', 3, 'Knead the mixture firmly with your hands for 3 minutes until sticky and well bound, then chill for 30 minutes.'),
    ('Chapli Kebab', 4, 'Shape into 8 flat patties about 10 cm wide and 1 cm thick, pressing a slight dimple in the centre.'),
    ('Chapli Kebab', 5, 'Heat the oil in a wide frying pan over medium heat. Fry the patties in batches for 4-5 minutes per side until deep brown and cooked through.'),
    ('Chapli Kebab', 6, 'Drain on paper towels and serve hot with lemon wedges, naan and mint chutney.'),
    ('Chana Masala', 1, 'Heat the oil in a deep pan over medium heat. Add the finely chopped onions and cook for 10 minutes until deep golden.'),
    ('Chana Masala', 2, 'Stir in the grated garlic and ginger and cook for 1 minute.'),
    ('Chana Masala', 3, 'Add the chopped tomatoes, cumin, ground coriander, turmeric, chilli powder and salt. Cook for 8 minutes, mashing the tomatoes, until the oil separates.'),
    ('Chana Masala', 4, 'Drain and rinse the chickpeas, add them with the water and bring to the boil.'),
    ('Chana Masala', 5, 'Simmer over low heat for 15 minutes, lightly crushing a few chickpeas against the pan to thicken the gravy.'),
    ('Chana Masala', 6, 'Stir in the garam masala and amchur, simmer 2 minutes, and finish with chopped coriander. Serve with rice or bhatura.'),
    ('Rajma Chawal', 1, 'Rinse the rice until the water runs clear, then soak for 20 minutes. Boil in plenty of salted water for 8-10 minutes until tender, drain and keep covered.'),
    ('Rajma Chawal', 2, 'Heat the oil in a deep pot over medium heat and add the cumin seeds until they sizzle, about 30 seconds.'),
    ('Rajma Chawal', 3, 'Add the finely chopped onions and cook for 10 minutes until golden. Stir in the garlic and ginger for 1 minute.'),
    ('Rajma Chawal', 4, 'Add the puréed tomatoes, turmeric, chilli powder, coriander and salt. Cook for 10 minutes until thick and the oil separates.'),
    ('Rajma Chawal', 5, 'Add the drained kidney beans and water. Simmer on low for 20 minutes, mashing some beans to thicken the gravy.'),
    ('Rajma Chawal', 6, 'Stir in the garam masala, scatter with coriander and serve over the rice.'),
    ('Aloo Gobi', 1, 'Cut the cauliflower into medium florets and the potatoes into 2.5 cm cubes.'),
    ('Aloo Gobi', 2, 'Heat the oil in a wide pan over medium heat and add the cumin seeds until they sizzle, about 30 seconds.'),
    ('Aloo Gobi', 3, 'Add the sliced onion and cook for 6 minutes until soft, then add the grated ginger and garlic for 1 minute.'),
    ('Aloo Gobi', 4, 'Stir in the chopped tomatoes, turmeric, coriander, chilli powder and salt and cook for 5 minutes until jammy.'),
    ('Aloo Gobi', 5, 'Add the potatoes and cauliflower, stir to coat, then cover and cook on low heat for 15-18 minutes, stirring now and then, until tender.'),
    ('Aloo Gobi', 6, 'Uncover, cook 2 minutes to dry out any liquid, then sprinkle with garam masala and coriander. Serve with roti.'),
    ('Bhindi Masala (Okra Stir-Fry)', 1, 'Wash the okra and dry it thoroughly with a towel, then trim the ends and slice into 2 cm rounds. Dry okra prevents sliminess.'),
    ('Bhindi Masala (Okra Stir-Fry)', 2, 'Heat 2 tbsp oil in a wide non-stick pan over medium-high heat. Fry the okra for 8-10 minutes, stirring now and then, until lightly browned and no longer sticky. Remove to a plate.'),
    ('Bhindi Masala (Okra Stir-Fry)', 3, 'In the same pan heat the remaining oil over medium heat and add the cumin seeds for 30 seconds.'),
    ('Bhindi Masala (Okra Stir-Fry)', 4, 'Add the sliced onions and cook for 7 minutes until golden, then add the chopped garlic for 1 minute.'),
    ('Bhindi Masala (Okra Stir-Fry)', 5, 'Stir in the diced tomato, turmeric, coriander, chilli powder and salt and cook for 4 minutes until soft.'),
    ('Bhindi Masala (Okra Stir-Fry)', 6, 'Return the okra, sprinkle with amchur, toss for 2 minutes and finish with chopped coriander. Serve with roti or rice.'),
    ('Khichuri', 1, 'Dry roast the moong dal in a pan over medium heat for 3 minutes until fragrant and pale golden. Rinse it with the rice together until the water runs clear.'),
    ('Khichuri', 2, 'Heat the ghee in a heavy pot over medium heat and add the bay leaves, cinnamon, cardamom, cloves and cumin seeds for 30 seconds.'),
    ('Khichuri', 3, 'Add the sliced onion and cook for 6 minutes until golden, then stir in the grated ginger and garlic for 1 minute.'),
    ('Khichuri', 4, 'Add the peeled and diced potato, turmeric and salt, then stir in the rice and dal for 1 minute.'),
    ('Khichuri', 5, 'Pour in the water, add the slit green chillies and bring to the boil. Reduce to low, cover and cook for 25 minutes, stirring occasionally, until soft and porridge-like.'),
    ('Khichuri', 6, 'Adjust consistency with hot water if too thick, stir in coriander and serve hot with fried eggs or beef bhuna.'),
    ('Nihari', 1, 'Heat the ghee in a heavy pot over medium heat, add the sliced onions and fry for 15 minutes until deep golden. Remove half for garnish.'),
    ('Nihari', 2, 'Add the beef, grated garlic and 1 tbsp ginger and sear for 8 minutes until browned on all sides.'),
    ('Nihari', 3, 'Stir in the cumin, coriander, chilli powder, turmeric, fennel, ground ginger, black cardamom, cinnamon and salt and fry for 3 minutes.'),
    ('Nihari', 4, 'Pour in 1.5 litres of water, bring to the boil, then cover and cook on the lowest heat for 3 hours, until the meat falls off the bone.'),
    ('Nihari', 5, 'Whisk the flour with 250 ml cold water until smooth, pour into the stew stirring constantly and simmer 15 minutes to thicken, adding more water if needed.'),
    ('Nihari', 6, 'Stir in the garam masala. Serve in bowls topped with the reserved onions, remaining julienned ginger, slit green chillies, coriander and lemon wedges.'),
    ('Haleem', 1, 'Rinse and soak the wheat, barley and both lentils together in water for 4 hours or overnight, then drain.'),
    ('Haleem', 2, 'Heat half the ghee in a large pot over medium heat and fry 2 sliced onions for 15 minutes until deep golden. Remove half for garnish.'),
    ('Haleem', 3, 'Add the beef, half the ginger and garlic, cumin, coriander, turmeric, chilli powder, yogurt and salt. Cook for 10 minutes, then add 1 litre of water.'),
    ('Haleem', 4, 'Cover and simmer for 90 minutes until the beef is tender. Add the soaked grains and 1.5 litres of water and cook 90 minutes more, stirring often so it does not stick.'),
    ('Haleem', 5, 'Mash vigorously with a wooden masher or blend briefly until the beef shreds into the grains and the haleem is thick and stretchy.'),
    ('Haleem', 6, 'Stir in the garam masala. Serve topped with the reserved onions, remaining ginger, slit chillies, mint and lemon wedges.'),
    ('Seekh Kebab', 1, 'Grate the onion and squeeze out all the liquid in a clean cloth. Finely chop the ginger, garlic, chillies, coriander and mint.'),
    ('Seekh Kebab', 2, 'In a large bowl mix the beef with the onion, herbs, spices, salt and gram flour. Knead hard for 5 minutes until sticky.'),
    ('Seekh Kebab', 3, 'Cover and chill for 1 hour, which helps the mixture hold on the skewers.'),
    ('Seekh Kebab', 4, 'Divide into 8 portions and press each firmly around a flat metal skewer into a 15 cm sausage shape, wetting your hands as you go.'),
    ('Seekh Kebab', 5, 'Heat a grill or griddle pan to high. Brush the kebabs with oil and cook for 10-12 minutes, turning every 3 minutes, until browned and cooked through.'),
    ('Seekh Kebab', 6, 'Rest for 3 minutes and serve with lemon wedges, naan, onion rings and chutney.'),
    ('Yakhni Pulao (Chicken Pulao)', 1, 'Put the chicken in a pot with 1.5 litres water, half the ginger and garlic, half the whole spices, 1 tsp salt and 1 sliced onion. Simmer for 35 minutes, then strain, keeping the chicken and 700 ml broth.'),
    ('Yakhni Pulao (Chicken Pulao)', 2, 'Rinse the rice until the water runs clear and soak it for 30 minutes, then drain.'),
    ('Yakhni Pulao (Chicken Pulao)', 3, 'Heat the oil in a heavy pot over medium heat and fry the remaining sliced onion for 10 minutes until dark golden.'),
    ('Yakhni Pulao (Chicken Pulao)', 4, 'Add the remaining whole spices, ginger and garlic and fry for 1 minute, then add the chicken pieces and brown for 5 minutes.'),
    ('Yakhni Pulao (Chicken Pulao)', 5, 'Add the rice, slit green chillies, remaining salt and the hot 700 ml broth. Boil on high until the liquid level reaches the rice.'),
    ('Yakhni Pulao (Chicken Pulao)', 6, 'Cover tightly, reduce to the lowest heat and steam for 15 minutes. Rest 5 minutes, fluff gently and serve with raita.'),
    ('Butter Chicken', 1, 'Mix the chicken with the yogurt, lemon juice, 1 tsp garam masala, turmeric, chilli powder, half the ginger and garlic and 0.5 tsp salt. Marinate for at least 1 hour.'),
    ('Butter Chicken', 2, 'Grill the chicken under a hot grill or roast at 220C for 12-15 minutes until charred at the edges. Set aside.'),
    ('Butter Chicken', 3, 'Melt the butter in a pan over medium heat, add the chopped onion and cook for 8 minutes until soft.'),
    ('Butter Chicken', 4, 'Add the remaining ginger and garlic for 1 minute, then the tomato purée, chopped tomatoes, cumin and remaining salt. Simmer for 15 minutes.'),
    ('Butter Chicken', 5, 'Blend the sauce until smooth and return it to the pan with the chicken. Simmer gently for 8 minutes.'),
    ('Butter Chicken', 6, 'Stir in the cream, crushed fenugreek leaves, sugar and remaining garam masala and warm through for 2 minutes. Garnish with coriander and serve with naan or rice.'),
    ('Chicken Tikka Masala', 1, 'Cut the chicken into 3 cm cubes and marinate with the yogurt, lemon juice, half the ginger and garlic, 1 tsp cumin, 1 tsp paprika, 1 tsp garam masala, turmeric and 1 tsp salt for at least 1 hour.'),
    ('Chicken Tikka Masala', 2, 'Thread onto skewers and grill or roast at 230C for 12-14 minutes until lightly charred and cooked through.'),
    ('Chicken Tikka Masala', 3, 'Heat the oil in a pan over medium heat and fry the chopped onion for 8 minutes until golden.'),
    ('Chicken Tikka Masala', 4, 'Add the remaining ginger and garlic and the chilli for 1 minute, then add the tomato purée, remaining spices and remaining salt for 1 minute.'),
    ('Chicken Tikka Masala', 5, 'Pour in the chopped tomatoes and simmer for 15 minutes until thick, then blend smooth if you prefer.'),
    ('Chicken Tikka Masala', 6, 'Add the chicken and cream, simmer gently for 5 minutes, and garnish with coriander. Serve with basmati rice or naan.'),
    ('Palak Paneer', 1, 'Boil a pot of water, blanch the spinach for 1 minute, then plunge into cold water. Drain, squeeze out water and blend with the green chillies to a smooth purée.'),
    ('Palak Paneer', 2, 'Cut the paneer into 2 cm cubes. Fry in 1 tbsp oil over medium heat for 4 minutes until lightly golden, then set aside.'),
    ('Palak Paneer', 3, 'Heat the remaining oil and ghee in a pan over medium heat. Add the cumin seeds for 30 seconds, then the chopped onion and cook for 7 minutes.'),
    ('Palak Paneer', 4, 'Add the grated ginger and garlic for 1 minute, then the chopped tomatoes, coriander, turmeric and salt. Cook for 6 minutes until soft.'),
    ('Palak Paneer', 5, 'Pour in the spinach purée and simmer for 5 minutes, adding a splash of water if too thick.'),
    ('Palak Paneer', 6, 'Stir in the paneer, garam masala and cream and heat for 2 minutes. Serve with roti or rice.'),
    ('Beef Bhuna', 1, 'Cut the beef into 4 cm cubes. Blend 2 onions with the ginger and garlic into a paste, and slice the remaining onion.'),
    ('Beef Bhuna', 2, 'Heat the oil in a heavy pan over medium heat. Add the whole spices and bay leaves for 30 seconds, then the sliced onion and fry 10 minutes until golden.'),
    ('Beef Bhuna', 3, 'Add the onion paste and cook for 10 minutes, stirring often, until it darkens.'),
    ('Beef Bhuna', 4, 'Add the cumin, coriander, turmeric, chilli powder and salt with a splash of water and cook 3 minutes, then add the beef and chopped tomatoes.'),
    ('Beef Bhuna', 5, 'Stir-fry the beef for 15 minutes on medium-high heat until sealed, then add the 200 ml water, cover and cook on low for 75 minutes until very tender.'),
    ('Beef Bhuna', 6, 'Uncover, increase the heat and stir for 10 minutes until the gravy clings to the meat and the oil separates. Add the green chillies and garam masala and serve with rice or paratha.'),
    ('Macher Jhol (Bengali Fish Curry)', 1, 'Rub the fish with 0.5 tsp turmeric and 0.5 tsp salt and rest for 10 minutes. Peel the potatoes and cut into thick wedges.'),
    ('Macher Jhol (Bengali Fish Curry)', 2, 'Heat 3 tbsp mustard oil in a pan over medium-high heat until it smokes lightly, then fry the fish 1-2 minutes per side until pale golden. Remove carefully.'),
    ('Macher Jhol (Bengali Fish Curry)', 3, 'In the same oil, fry the potato wedges for 5 minutes until lightly golden, then set aside.'),
    ('Macher Jhol (Bengali Fish Curry)', 4, 'Lower the heat to medium, add the nigella seeds and chopped onion and cook for 6 minutes. Add the grated ginger and garlic for 1 minute.'),
    ('Macher Jhol (Bengali Fish Curry)', 5, 'Add the chopped tomatoes, cumin, chilli powder, remaining turmeric and salt and cook 5 minutes. Pour in the water, add the potatoes and simmer for 8 minutes.'),
    ('Macher Jhol (Bengali Fish Curry)', 6, 'Gently add the fish and green chillies and simmer for 5 minutes. Drizzle with the remaining raw mustard oil, scatter coriander and serve with rice.'),
    ('Sri Lankan Chicken Curry', 1, 'Toss the chicken with the curry powder, turmeric, chilli powder, 1 tsp salt and half the grated ginger and garlic. Marinate for 30 minutes.'),
    ('Sri Lankan Chicken Curry', 2, 'Heat the coconut oil in a pot over medium heat and fry the sliced onions with the cinnamon, curry leaves and pandan for 8 minutes until soft.'),
    ('Sri Lankan Chicken Curry', 3, 'Add the remaining ginger and garlic and the green chillies for 1 minute.'),
    ('Sri Lankan Chicken Curry', 4, 'Add the chicken and diced tomato and cook for 8 minutes, turning, until sealed.'),
    ('Sri Lankan Chicken Curry', 5, 'Pour in the coconut milk plus 100 ml water, bring to a gentle simmer, cover and cook for 25 minutes until the chicken is tender.'),
    ('Sri Lankan Chicken Curry', 6, 'Uncover and simmer for 5 minutes to thicken. Season with lime juice and remaining salt and serve with rice and dhal.'),
    ('Vegetable Samosas', 1, 'Mix the flour with 1 tsp salt, rub in 70 ml oil, then add the water and knead for 5 minutes into a firm dough. Cover and rest for 30 minutes.'),
    ('Vegetable Samosas', 2, 'Boil the potatoes for 15-20 minutes until tender, then peel and roughly crush. Cook the peas in boiling water for 2 minutes and drain.'),
    ('Vegetable Samosas', 3, 'Heat 1 tbsp oil, add the cumin seeds, grated ginger and chopped chillies for 1 minute, then mix in the potato, peas, coriander, garam masala, chilli powder, amchur and remaining salt. Cool completely and stir in chopped fresh coriander.'),
    ('Vegetable Samosas', 4, 'Divide the dough into 8 balls, roll each into a 16 cm oval and cut in half. Shape each half into a cone, sealing the straight edge with a dab of water.'),
    ('Vegetable Samosas', 5, 'Fill each cone with 2 tbsp of filling, brush the open edge with water and pinch tightly closed.'),
    ('Vegetable Samosas', 6, 'Heat the frying oil to 160C in a deep pan. Fry in batches for 8-10 minutes over medium-low heat until deep golden, then drain and serve with tamarind or mint chutney.'),
    ('Vegetable Pakoras', 1, 'Slice the onions thinly, grate or finely slice the potato, and roughly chop the spinach, chillies and coriander.'),
    ('Vegetable Pakoras', 2, 'In a bowl combine the gram flour, rice flour, cumin seeds, ground coriander, chilli powder, turmeric and salt.'),
    ('Vegetable Pakoras', 3, 'Add the vegetables and mix, then pour in the water gradually to make a thick batter that coats the vegetables.'),
    ('Vegetable Pakoras', 4, 'Heat the oil in a deep pan to 170C, or until a drop of batter rises and sizzles at once.'),
    ('Vegetable Pakoras', 5, 'Drop in tablespoon-sized portions and fry in batches for 4-5 minutes, turning once, until deep golden and crisp.'),
    ('Vegetable Pakoras', 6, 'Drain on paper towels and serve hot with mint chutney or ketchup.'),
    ('Gulab Jamun', 1, 'Boil the sugar, water and crushed cardamom pods for 8 minutes to make a light syrup. Stir in the rose water and saffron and keep warm.'),
    ('Gulab Jamun', 2, 'Mix the milk powder, flour, baking powder and ghee in a bowl, then add the milk a little at a time to form a very soft, smooth dough. Do not overwork it.'),
    ('Gulab Jamun', 3, 'Rest the dough for 10 minutes, then roll into 16 smooth, crack-free balls with lightly greased hands.'),
    ('Gulab Jamun', 4, 'Heat the oil to about 130C over low heat. Fry the balls in batches for 8-10 minutes, stirring gently, until deep golden brown all over.'),
    ('Gulab Jamun', 5, 'Drain and drop straight into the warm syrup. Soak for at least 1 hour so they swell and become juicy.'),
    ('Gulab Jamun', 6, 'Serve warm, topped with chopped pistachios.'),
    ('Sheer Khurma', 1, 'Break the vermicelli into short lengths. Heat the ghee in a pan over medium heat and toast the vermicelli for 3 minutes until golden brown. Remove and set aside.'),
    ('Sheer Khurma', 2, 'In the same pan toast the sliced almonds, pistachios and raisins for 1-2 minutes, then remove half for garnish.'),
    ('Sheer Khurma', 3, 'Pour the milk into a heavy pot, add the crushed cardamom and bring to the boil, then simmer for 15 minutes until reduced by about a quarter.'),
    ('Sheer Khurma', 4, 'Stir in the stoned and sliced dates, the toasted vermicelli, sugar and saffron and cook on low heat for 8-10 minutes until the vermicelli is soft.'),
    ('Sheer Khurma', 5, 'Stir in the coconut and the nuts and raisins that were not set aside.'),
    ('Sheer Khurma', 6, 'Serve warm or chilled, topped with the reserved nuts.'),
    ('Mango Lassi', 1, 'Peel and chop ripe mangoes, or measure out canned mango pulp.'),
    ('Mango Lassi', 2, 'Add the mango, yogurt, milk, sugar, cardamom and ice to a blender.'),
    ('Mango Lassi', 3, 'Blend on high for 1 minute until completely smooth and frothy.'),
    ('Mango Lassi', 4, 'Taste and add more sugar if the mango is not sweet enough.'),
    ('Mango Lassi', 5, 'Pour into tall glasses and top with chopped pistachios. Serve straight away.'),
    ('Çılbır (Poached Eggs with Garlic Yogurt)', 1, 'Crush the garlic with a pinch of salt and stir it into the yogurt. Spread the yogurt on a shallow serving dish and leave it at room temperature.'),
    ('Çılbır (Poached Eggs with Garlic Yogurt)', 2, 'Bring a wide pan of water to a gentle simmer over medium heat and add the apple cider vinegar.'),
    ('Çılbır (Poached Eggs with Garlic Yogurt)', 3, 'Crack each egg into a small cup. Swirl the water gently and slide the eggs in a few at a time.'),
    ('Çılbır (Poached Eggs with Garlic Yogurt)', 4, 'Poach for 3 minutes until the whites are set and the yolks are still runny, then lift out with a slotted spoon and drain on kitchen paper.'),
    ('Çılbır (Poached Eggs with Garlic Yogurt)', 5, 'Melt the butter in a small pan over medium heat until it foams, then stir in the paprika and dried mint for 15 seconds.'),
    ('Çılbır (Poached Eggs with Garlic Yogurt)', 6, 'Place the eggs on the yogurt, drizzle with the hot paprika butter and serve straight away with warm bread.'),
    ('Sucuklu Yumurta (Beef Sucuk & Eggs)', 1, 'Slice the beef sucuk into thin rounds, about 3 mm thick.'),
    ('Sucuklu Yumurta (Beef Sucuk & Eggs)', 2, 'Heat the butter in a large non-stick frying pan over medium heat and fry the sucuk for 2 to 3 minutes, turning once, until it releases its red oil and edges crisp.'),
    ('Sucuklu Yumurta (Beef Sucuk & Eggs)', 3, 'Reduce the heat to medium-low and push the sucuk slices to the edges of the pan.'),
    ('Sucuklu Yumurta (Beef Sucuk & Eggs)', 4, 'Crack the eggs into the pan, spacing them out, and cook for 3 to 4 minutes until the whites are set but the yolks are still soft.'),
    ('Sucuklu Yumurta (Beef Sucuk & Eggs)', 5, 'Sprinkle with black pepper and chilli flakes and scatter over chopped parsley.'),
    ('Sucuklu Yumurta (Beef Sucuk & Eggs)', 6, 'Bring the pan to the table and serve with bread for mopping up the spiced oil.'),
    ('Lahmacun', 1, 'Mix the flour, yeast and 1 tsp salt in a bowl. Add the warm water and olive oil and knead for 8 minutes until smooth. Cover and rest for 40 minutes.'),
    ('Lahmacun', 2, 'Finely chop or pulse the onion, red pepper, tomatoes, garlic and half the parsley. Squeeze out excess liquid in a sieve.'),
    ('Lahmacun', 3, 'Mix the vegetables with the minced lamb, tomato paste, paprika, cumin, chilli flakes and 0.5 tsp salt into a loose paste.'),
    ('Lahmacun', 4, 'Heat the oven to its highest setting (about 250C) with two baking trays inside.'),
    ('Lahmacun', 5, 'Divide the dough into 8 balls and roll each into a very thin round about 20 cm across.'),
    ('Lahmacun', 6, 'Spread a thin even layer of the meat mixture over each round, right to the edge.'),
    ('Lahmacun', 7, 'Bake 2 or 3 at a time on the hot trays for 6 to 8 minutes until the edges are crisp and golden.'),
    ('Lahmacun', 8, 'Top with the remaining chopped parsley, squeeze over lemon and roll up to eat.'),
    ('İmam Bayıldı (Stuffed Aubergine)', 1, 'Peel the aubergines in lengthwise stripes and soak in salted water for 15 minutes, then pat dry.'),
    ('İmam Bayıldı (Stuffed Aubergine)', 2, 'Heat 3 tbsp olive oil in a frying pan over medium heat and fry the aubergines for 8 minutes, turning, until lightly golden. Transfer to a baking dish.'),
    ('İmam Bayıldı (Stuffed Aubergine)', 3, 'In the same pan, soften the sliced onions in 3 tbsp olive oil over medium heat for 10 minutes.'),
    ('İmam Bayıldı (Stuffed Aubergine)', 4, 'Add the garlic, diced pepper and chopped tomatoes with the sugar, salt and pepper and cook for 8 minutes until thick. Stir in the parsley.'),
    ('İmam Bayıldı (Stuffed Aubergine)', 5, 'Heat the oven to 180C. Slit each aubergine lengthwise and open it out like a pocket, then stuff with the filling.'),
    ('İmam Bayıldı (Stuffed Aubergine)', 6, 'Mix the water, lemon juice and remaining oil, pour around the aubergines and cover with foil.'),
    ('İmam Bayıldı (Stuffed Aubergine)', 7, 'Bake for 35 minutes, uncovered for the last 10, until very soft. Cool to room temperature before serving.'),
    ('Burek (Meat Pie)', 1, 'Grate the onions and mix with the minced beef, garlic, salt and pepper until well combined.'),
    ('Burek (Meat Pie)', 2, 'Heat the oven to 200C and oil a large round baking tin.'),
    ('Burek (Meat Pie)', 3, 'Mix the oil with the warm water. Lay a filo sheet on the counter, brush it lightly with the mixture and spread a thin line of filling along one long edge.'),
    ('Burek (Meat Pie)', 4, 'Roll the sheet into a thin sausage shape, then coil it into the tin. Repeat with the remaining sheets, joining the coils end to end into a spiral.'),
    ('Burek (Meat Pie)', 5, 'Brush the top with the remaining oil mixture and bake for 40 minutes until deep golden and crisp.'),
    ('Burek (Meat Pie)', 6, 'Cover with a clean tea towel for 10 minutes to soften slightly, then cut into wedges and serve with yogurt.'),
    ('Dushbara (Dumpling Soup)', 1, 'Put the lamb bones and 1.5 litres water in a pot, bring to the boil, skim, then simmer gently with 1 tsp salt for 40 minutes.'),
    ('Dushbara (Dumpling Soup)', 2, 'Meanwhile, knead the flour, egg, 100 ml water and a pinch of salt into a firm dough. Rest it, covered, for 30 minutes.'),
    ('Dushbara (Dumpling Soup)', 3, 'Grate the onion and mix with the minced lamb, pepper and 0.5 tsp salt for the filling.'),
    ('Dushbara (Dumpling Soup)', 4, 'Roll the dough very thin, cut into 3 cm squares and put a tiny piece of filling in the centre of each. Fold into a small triangle and pinch the corners together.'),
    ('Dushbara (Dumpling Soup)', 5, 'Strain the broth and return it to a gentle boil. Drop in the dumplings and cook for 8 to 10 minutes until they float and the filling is cooked.'),
    ('Dushbara (Dumpling Soup)', 6, 'Crush the garlic with the vinegar and stir it into the soup with the mint just before serving.'),
    ('Lanzhou-Style Beef Noodle Soup', 1, 'Cover the beef shin with cold water in a pot, bring to the boil for 5 minutes and drain, rinsing off the scum.'),
    ('Lanzhou-Style Beef Noodle Soup', 2, 'Return the beef to the pot with 2.5 litres fresh water, sliced ginger, star anise, cinnamon, black cardamom and peppercorns. Simmer very gently, partly covered, for 2 hours.'),
    ('Lanzhou-Style Beef Noodle Soup', 3, 'Add the soy sauce, salt and the radish cut into chunks and simmer for another 20 minutes.'),
    ('Lanzhou-Style Beef Noodle Soup', 4, 'Lift out the beef, let it rest 10 minutes and slice it thinly. Strain the broth and keep it hot.'),
    ('Lanzhou-Style Beef Noodle Soup', 5, 'Cook the noodles in a separate pot of boiling water according to packet time, usually 3 to 4 minutes, and drain.'),
    ('Lanzhou-Style Beef Noodle Soup', 6, 'Divide the noodles between bowls, add beef and radish and ladle over the hot broth.'),
    ('Lanzhou-Style Beef Noodle Soup', 7, 'Top with sliced spring onion, coriander and a spoonful of chilli oil.'),
    ('Circassian Chicken (Çerkez Tavuğu)', 1, 'Put the chicken, halved onion, bay leaves and 1 tsp salt in a pot with 1 litre of water. Bring to the boil, then simmer gently for 20 minutes until cooked through.'),
    ('Circassian Chicken (Çerkez Tavuğu)', 2, 'Lift out the chicken and let it cool, keeping the stock. Shred the meat into thin strips.'),
    ('Circassian Chicken (Çerkez Tavuğu)', 3, 'Soak the bread in about 150 ml warm stock for 2 minutes and squeeze it lightly.'),
    ('Circassian Chicken (Çerkez Tavuğu)', 4, 'Blitz the walnuts (saving a few for garnish), bread, garlic and pepper in a food processor, adding stock gradually, until a thick creamy sauce forms.'),
    ('Circassian Chicken (Çerkez Tavuğu)', 5, 'Stir half the sauce into the shredded chicken and spread it on a serving plate. Pour the remaining sauce over the top.'),
    ('Circassian Chicken (Çerkez Tavuğu)', 6, 'Heat the olive oil with paprika for 20 seconds and drizzle over, then scatter with the remaining chopped walnuts. Serve at room temperature.'),
    ('Iskender Kebab', 1, 'Mix the lamb mince with the grated onion, cumin, paprika, salt and pepper, then shape into 4 flat oval patties (kofte-style).'),
    ('Iskender Kebab', 2, 'Slice the beef sirloin very thinly against the grain and season with salt and pepper.'),
    ('Iskender Kebab', 3, 'Simmer the tomatoes and tomato paste with a pinch of salt in a small pan over medium heat for 12 minutes until thick.'),
    ('Iskender Kebab', 4, 'Heat the oil in a large frying pan over high heat. Sear the beef in batches for 2 minutes per side and the patties for 4 minutes per side.'),
    ('Iskender Kebab', 5, 'Cut the pide into small cubes and toast them in a dry pan for 2 minutes, then lay them in the base of 4 plates.'),
    ('Iskender Kebab', 6, 'Top the bread with beef, add the tomato sauce, then spoon a generous amount of yogurt alongside.'),
    ('Iskender Kebab', 7, 'Melt the butter until it foams and turns light brown, pour it sizzling over each plate and serve with grilled green chillies.'),
    ('Karnıyarık (Aubergine Stuffed with Beef)', 1, 'Peel the aubergines in stripes, soak in salted water for 15 minutes and pat dry.'),
    ('Karnıyarık (Aubergine Stuffed with Beef)', 2, 'Heat the oil in a large frying pan over medium-high heat and fry the aubergines for 8 minutes, turning, until golden and soft. Drain on kitchen paper and move to a baking dish.'),
    ('Karnıyarık (Aubergine Stuffed with Beef)', 3, 'Fry the chopped onions in 1 tbsp oil for 6 minutes, then add the beef and brown for 6 minutes, breaking it up.'),
    ('Karnıyarık (Aubergine Stuffed with Beef)', 4, 'Add the garlic, 2 chopped tomatoes, half the tomato paste, salt and pepper and cook for 8 minutes. Stir in the parsley.'),
    ('Karnıyarık (Aubergine Stuffed with Beef)', 5, 'Heat the oven to 190C. Cut a slit down each aubergine and press it open, then spoon in the filling.'),
    ('Karnıyarık (Aubergine Stuffed with Beef)', 6, 'Top each with a slice of the remaining tomato and a pepper. Stir the remaining paste into the hot water and pour into the dish.'),
    ('Karnıyarık (Aubergine Stuffed with Beef)', 7, 'Bake for 25 minutes until the aubergines are completely tender. Serve with rice.'),
    ('Kıymalı Pide (Minced Beef Pide)', 1, 'Mix the flour, yeast, 1.5 tsp salt, water and oil, knead for 8 minutes, cover and let rise for 45 minutes until doubled.'),
    ('Kıymalı Pide (Minced Beef Pide)', 2, 'Finely chop the onion, tomatoes, green pepper and parsley. Mix with the beef, tomato paste, paprika, pepper and 0.5 tsp salt.'),
    ('Kıymalı Pide (Minced Beef Pide)', 3, 'Heat the oven to 240C with a tray inside.'),
    ('Kıymalı Pide (Minced Beef Pide)', 4, 'Divide the dough into 4 and roll each into a long oval about 30 cm long. Spread the filling along the middle, leaving a 3 cm border.'),
    ('Kıymalı Pide (Minced Beef Pide)', 5, 'Fold the long edges in over the filling and pinch the ends into points to make a boat.'),
    ('Kıymalı Pide (Minced Beef Pide)', 6, 'Brush the dough with beaten egg and slide onto the hot tray.'),
    ('Kıymalı Pide (Minced Beef Pide)', 7, 'Bake for 12 to 15 minutes until golden, brush the edges with butter and rest for 3 minutes before cutting.'),
    ('Turkish Mantı', 1, 'Knead the flour, egg, water and 1 tsp salt into a stiff dough. Cover and rest for 30 minutes.'),
    ('Turkish Mantı', 2, 'Grate the onion and mix with the beef, parsley, pepper and 0.5 tsp salt.'),
    ('Turkish Mantı', 3, 'Roll the dough very thin and cut into 3 cm squares.'),
    ('Turkish Mantı', 4, 'Place a small pinch of filling on each square and pinch the four corners together to form little purses.'),
    ('Turkish Mantı', 5, 'Bring a large pot of salted water to a boil and cook the mantı for 8 to 10 minutes until they float and are tender.'),
    ('Turkish Mantı', 6, 'Mix the yogurt with crushed garlic and a pinch of salt.'),
    ('Turkish Mantı', 7, 'Melt the butter over medium heat, add the paprika, tomato paste and mint and sizzle for 30 seconds.'),
    ('Turkish Mantı', 8, 'Spoon the mantı into bowls, top with garlic yogurt and drizzle with the butter.'),
    ('Ćevapi with Lepinja', 1, 'Mix the beef, lamb, crushed garlic, salt, pepper, bicarbonate of soda and sparkling water. Knead by hand for 5 minutes until sticky and smooth.'),
    ('Ćevapi with Lepinja', 2, 'Cover and chill in the fridge for at least 1 hour, or overnight if you can.'),
    ('Ćevapi with Lepinja', 3, 'Wet your hands and shape the mixture into about 20 finger-sized sausages, roughly 6 cm long.'),
    ('Ćevapi with Lepinja', 4, 'Heat a grill pan or barbecue to medium-high and cook the ćevapi for 10 to 12 minutes, turning often, until browned and cooked through.'),
    ('Ćevapi with Lepinja', 5, 'Warm the lepinja on the grill for 1 minute each side.'),
    ('Ćevapi with Lepinja', 6, 'Serve the ćevapi inside or alongside the bread with chopped raw onion, sour cream and a sprinkle of paprika.'),
    ('Tavë Kosi (Baked Lamb & Yogurt)', 1, 'Heat the oven to 180C. Season the lamb with salt, pepper and oregano.'),
    ('Tavë Kosi (Baked Lamb & Yogurt)', 2, 'Melt the butter in a pan over medium-high heat and brown the lamb for 8 minutes, then add the sliced onion and cook for 4 minutes.'),
    ('Tavë Kosi (Baked Lamb & Yogurt)', 3, 'Transfer to a baking dish, add the rice and water, cover with foil and bake for 1 hour until the lamb is tender and the rice has soaked up the liquid.'),
    ('Tavë Kosi (Baked Lamb & Yogurt)', 4, 'Whisk the eggs, yogurt and flour with a pinch of salt until smooth.'),
    ('Tavë Kosi (Baked Lamb & Yogurt)', 5, 'Pour the yogurt mixture evenly over the lamb and rice.'),
    ('Tavë Kosi (Baked Lamb & Yogurt)', 6, 'Bake uncovered for 30 to 35 minutes until the topping is set and golden. Rest for 10 minutes before serving.'),
    ('Uzbek Plov', 1, 'Rinse the rice in several changes of water until clear, then soak in warm salted water for 30 minutes.'),
    ('Uzbek Plov', 2, 'Heat the oil in a heavy pot over high heat until hot. Brown the lamb for 8 minutes.'),
    ('Uzbek Plov', 3, 'Add the sliced onions and cook for 6 minutes until deep golden.'),
    ('Uzbek Plov', 4, 'Add the carrots cut into thick matchsticks and cook for 8 minutes, stirring, until softened.'),
    ('Uzbek Plov', 5, 'Add the cumin, pepper, salt and boiling water and simmer on low for 30 minutes to make the base (zirvak).'),
    ('Uzbek Plov', 6, 'Drain the rice and spread it evenly over the meat without stirring. Push the garlic bulb into the centre and scatter the barberries on top.'),
    ('Uzbek Plov', 7, 'Add hot water to cover the rice by 1 cm, cook on high until the water is absorbed, then poke a few holes, cover and cook on the lowest heat for 20 minutes.'),
    ('Uzbek Plov', 8, 'Gently mix the plov from the bottom, then serve on a large plate topped with the lamb and garlic.'),
    ('Lagman (Hand-Pulled Noodles)', 1, 'Mix 450 g flour with 200 ml water and 1 tsp salt, knead for 10 minutes, rub with oil, cover and rest for 1 hour.'),
    ('Lagman (Hand-Pulled Noodles)', 2, 'Heat 3 tbsp oil in a wok over high heat and sear the lamb for 4 minutes until browned.'),
    ('Lagman (Hand-Pulled Noodles)', 3, 'Add the sliced onion, carrot and garlic and cook for 4 minutes.'),
    ('Lagman (Hand-Pulled Noodles)', 4, 'Add the peppers and tomatoes, then tomato paste, cumin, pepper and 1 tsp salt, and cook for 5 minutes.'),
    ('Lagman (Hand-Pulled Noodles)', 5, 'Pour in 400 ml water, cover and simmer for 25 minutes until the sauce is thick and the lamb tender.'),
    ('Lagman (Hand-Pulled Noodles)', 6, 'Divide the dough into 8 pieces, roll into ropes, then stretch each rope and swing it to make long noodles about 1 m long.'),
    ('Lagman (Hand-Pulled Noodles)', 7, 'Boil the noodles in salted water for 3 to 4 minutes until chewy and drain.'),
    ('Lagman (Hand-Pulled Noodles)', 8, 'Serve the noodles in bowls topped generously with the sauce and chopped coriander.'),
    ('Beshbarmak', 1, 'Put the lamb in a large pot with 2.5 litres cold water, bring to the boil and skim off the foam.'),
    ('Beshbarmak', 2, 'Add 1 onion, bay leaves, peppercorns and 1 tsp salt and simmer gently for 2 to 2.5 hours until the meat falls from the bone.'),
    ('Beshbarmak', 3, 'Make the dough from the flour, eggs, warm water and 1 tsp salt, knead for 8 minutes and rest for 30 minutes.'),
    ('Beshbarmak', 4, 'Slice the remaining onions into rings and simmer them in a ladle of broth for 5 minutes.'),
    ('Beshbarmak', 5, 'Remove the lamb, strain the broth and cut the meat off the bone into pieces. Boil the peeled potatoes in some of the broth for 20 minutes.'),
    ('Beshbarmak', 6, 'Roll the dough thin, cut into 6 cm squares and boil in the strained broth for 6 to 8 minutes. Drain.'),
    ('Beshbarmak', 7, 'Serve the noodles topped with meat, potatoes and onions with dill, and drink the remaining broth from bowls on the side.'),
    ('Mercimek Köftesi (Lentil Patties)', 1, 'Rinse the lentils and simmer in 500 ml water for 12 to 15 minutes until mushy, stirring often.'),
    ('Mercimek Köftesi (Lentil Patties)', 2, 'Stir in the bulgur, switch off the heat, cover and leave for 15 minutes to absorb.'),
    ('Mercimek Köftesi (Lentil Patties)', 3, 'Soften the finely chopped onion in the olive oil over medium heat for 6 minutes, then stir in tomato paste, cumin and paprika for 1 minute.'),
    ('Mercimek Köftesi (Lentil Patties)', 4, 'Mix the onion mixture into the lentils with chopped spring onions, parsley, salt and the lemon juice.'),
    ('Mercimek Köftesi (Lentil Patties)', 5, 'Knead with damp hands for 3 minutes until smooth, then shape into small oval patties.'),
    ('Mercimek Köftesi (Lentil Patties)', 6, 'Serve cold on lettuce leaves with extra lemon wedges.'),
    ('Baklava', 1, 'Heat the oven to 170C and butter a 23 x 33 cm baking tin. Melt the remaining butter.'),
    ('Baklava', 2, 'Make the syrup by boiling the sugar, water and lemon juice for 10 minutes until slightly thickened, then cool completely.'),
    ('Baklava', 3, 'Chop the pistachios finely and mix with the cinnamon.'),
    ('Baklava', 4, 'Layer 10 filo sheets in the tin, brushing each with melted butter. Spread half the nuts over the top.'),
    ('Baklava', 5, 'Add 5 more buttered sheets, the rest of the nuts and finally another 10 buttered sheets, brushing the top well.'),
    ('Baklava', 6, 'Cut into diamonds or squares with a sharp knife, going all the way through.'),
    ('Baklava', 7, 'Bake for 45 to 50 minutes until deep golden, then pour the cool syrup evenly over the hot baklava.'),
    ('Baklava', 8, 'Leave to soak for at least 4 hours before serving.'),
    ('Sütlaç (Baked Rice Pudding)', 1, 'Simmer the rice in the water for 12 minutes until soft and nearly all absorbed.'),
    ('Sütlaç (Baked Rice Pudding)', 2, 'Add the milk and sugar and cook gently over medium-low heat for 15 minutes, stirring often.'),
    ('Sütlaç (Baked Rice Pudding)', 3, 'Whisk the rice flour into the cold milk and stir it into the pot. Cook for 5 minutes until thick, then add the vanilla powder.'),
    ('Sütlaç (Baked Rice Pudding)', 4, 'Pour into 6 ovenproof bowls and let them cool for 15 minutes.'),
    ('Sütlaç (Baked Rice Pudding)', 5, 'Heat the grill to high and place the bowls underneath for 3 to 4 minutes until the tops are spotted dark brown.'),
    ('Sütlaç (Baked Rice Pudding)', 6, 'Cool, then chill for at least 2 hours before serving.'),
    ('Samsa (Baked Lamb Pastries)', 1, 'Mix the flour, 1 tsp salt and water into a dough, knead for 5 minutes and rest for 20 minutes.'),
    ('Samsa (Baked Lamb Pastries)', 2, 'Roll the dough into a rectangle, spread with half the soft butter, fold into thirds, then repeat the butter and folding once more. Chill for 30 minutes.'),
    ('Samsa (Baked Lamb Pastries)', 3, 'Mix the lamb with finely chopped onions, fat, cumin, pepper and 0.5 tsp salt.'),
    ('Samsa (Baked Lamb Pastries)', 4, 'Heat the oven to 200C. Roll the dough out thin and cut into 10 cm squares.'),
    ('Samsa (Baked Lamb Pastries)', 5, 'Place a spoonful of filling on each square, fold into a triangle and pinch the edges tightly.'),
    ('Samsa (Baked Lamb Pastries)', 6, 'Brush with beaten egg, sprinkle with sesame seeds and bake for 30 to 35 minutes until golden and puffed.'),
    ('Chak-Chak (Honey Dough Bites)', 1, 'Whisk the eggs with 2 tbsp sugar and a pinch of salt, then add the flour and knead into a stiff, smooth dough. Rest it for 20 minutes.'),
    ('Chak-Chak (Honey Dough Bites)', 2, 'Roll the dough into thin sheets and cut into strips about 5 cm long and 5 mm wide.'),
    ('Chak-Chak (Honey Dough Bites)', 3, 'Heat the oil in a deep pan to medium-high (about 170C) and fry the strips in batches for 1 to 2 minutes until golden. Drain on kitchen paper.'),
    ('Chak-Chak (Honey Dough Bites)', 4, 'Heat the honey and 100 g sugar in a large pan over low heat for 5 minutes until bubbling and slightly thickened.'),
    ('Chak-Chak (Honey Dough Bites)', 5, 'Toss the fried strips in the syrup until coated.'),
    ('Chak-Chak (Honey Dough Bites)', 6, 'Tip onto a plate, shape into a mound with wet hands and let it set for 1 hour. Break into pieces to serve.'),
    ('Roti Canai with Dhal', 1, 'Mix the plain flour, salt, egg, condensed milk and warm water into a soft sticky dough, then knead for 5 minutes until smooth.'),
    ('Roti Canai with Dhal', 2, 'Divide the dough into 4 balls, coat each generously with ghee, put them in a dish, cover and rest for at least 1 hour (or overnight).'),
    ('Roti Canai with Dhal', 3, 'For the dhal, rinse the red lentils and simmer them in the water with turmeric for 20 minutes over medium-low heat until soft, stirring occasionally.'),
    ('Roti Canai with Dhal', 4, 'Heat the oil in a pan over medium heat, fry the chopped onion for 5 minutes, then add the garlic, ginger, curry leaves and curry powder and cook 1 minute.'),
    ('Roti Canai with Dhal', 5, 'Add the chopped tomato, cook 3 minutes until soft, then stir this mixture into the lentils and season with salt; keep warm.'),
    ('Roti Canai with Dhal', 6, 'On an oiled surface, stretch one dough ball as thin as paper with your hands, then fold it into a square or coil it into a spiral to trap the layers.'),
    ('Roti Canai with Dhal', 7, 'Cook each roti on a hot greased pan over medium-high heat for 2 to 3 minutes per side until golden and crisp.'),
    ('Roti Canai with Dhal', 8, 'Clap the hot roti between your hands to fluff up the layers and serve at once with the dhal.'),
    ('Nasi Goreng', 1, 'Blend or pound the shallots, garlic, chillies and shrimp paste into a rough paste.'),
    ('Nasi Goreng', 2, 'Slice the chicken thinly and season with a pinch of salt.'),
    ('Nasi Goreng', 3, 'Heat 2 tablespoons oil in a wok over high heat, add the paste and stir-fry 1 minute until fragrant.'),
    ('Nasi Goreng', 4, 'Add the chicken and stir-fry 4 to 5 minutes until cooked through.'),
    ('Nasi Goreng', 5, 'Add the cold rice, breaking up clumps, and stir-fry 4 minutes; pour in the kecap manis and soy sauce and toss until evenly brown.'),
    ('Nasi Goreng', 6, 'Stir in the sliced spring onions and taste for salt, then divide among plates.'),
    ('Nasi Goreng', 7, 'Fry the eggs in the remaining oil in a pan over medium-high heat for 2 to 3 minutes until the edges are crisp.'),
    ('Nasi Goreng', 8, 'Top each plate with an egg, cucumber and tomato slices and fried shallots.'),
    ('Bubur Ayam (Chicken Rice Porridge)', 1, 'Put the chicken, water, sliced ginger, crushed garlic, bruised lemongrass, bay leaves and turmeric in a large pot and bring to the boil.'),
    ('Bubur Ayam (Chicken Rice Porridge)', 2, 'Reduce to a gentle simmer and cook the chicken for 25 minutes, skimming any foam, until tender.'),
    ('Bubur Ayam (Chicken Rice Porridge)', 3, 'Lift out the chicken, let it cool a little, then shred the meat with two forks.'),
    ('Bubur Ayam (Chicken Rice Porridge)', 4, 'Rinse the rice, add it to the strained broth and simmer on low for 35 minutes, stirring often, until it breaks down into a thick porridge.'),
    ('Bubur Ayam (Chicken Rice Porridge)', 5, 'Season with salt and white pepper, adding hot water if it becomes too thick.'),
    ('Bubur Ayam (Chicken Rice Porridge)', 6, 'Boil the eggs for 7 minutes, cool in cold water, then peel and halve them.'),
    ('Bubur Ayam (Chicken Rice Porridge)', 7, 'Ladle the porridge into bowls and top with shredded chicken, egg, spring onions, celery leaves and fried shallots.'),
    ('Bubur Ayam (Chicken Rice Porridge)', 8, 'Drizzle with soy sauce and serve hot.'),
    ('Mee Goreng Mamak', 1, 'Rinse the noodles in hot water for 30 seconds to loosen them, then drain well.'),
    ('Mee Goreng Mamak', 2, 'Cut the chicken into thin slices, the tofu into cubes and the boiled potatoes into chunks.'),
    ('Mee Goreng Mamak', 3, 'Heat 2 tablespoons oil in a wok over high heat and fry the tofu until golden, about 3 minutes; set aside.'),
    ('Mee Goreng Mamak', 4, 'Add the remaining oil, fry the chopped garlic and shallots 1 minute, then the chilli paste for 1 minute.'),
    ('Mee Goreng Mamak', 5, 'Add the chicken and stir-fry 4 minutes until cooked through.'),
    ('Mee Goreng Mamak', 6, 'Push everything aside, crack in the eggs and scramble for 1 minute.'),
    ('Mee Goreng Mamak', 7, 'Add the noodles, potatoes, ketchup, soy sauce and kecap manis and toss over high heat for 3 minutes.'),
    ('Mee Goreng Mamak', 8, 'Add the choy sum and bean sprouts, toss 1 minute until just wilted, add the tofu back and serve with lime wedges.'),
    ('Curry Laksa', 1, 'Boil the eggs for 8 minutes, cool in cold water, peel and halve them.'),
    ('Curry Laksa', 2, 'Soak the vermicelli in hot water for 5 minutes, then drain.'),
    ('Curry Laksa', 3, 'Heat the oil in a large pot over medium heat and fry the laksa paste for 3 minutes until fragrant and the oil separates.'),
    ('Curry Laksa', 4, 'Pour in the stock and coconut milk, add the sugar and fish sauce, and simmer gently for 10 minutes.'),
    ('Curry Laksa', 5, 'Add the sliced chicken and cook 6 minutes, then add the prawns and tofu puffs and cook 3 minutes until the prawns turn pink.'),
    ('Curry Laksa', 6, 'Blanch the bean sprouts in boiling water for 20 seconds and place them with the noodles in four bowls.'),
    ('Curry Laksa', 7, 'Ladle the hot curry over the noodles and top with egg, coriander, mint and a squeeze of lime.'),
    ('Soto Ayam', 1, 'Blend the shallots, garlic, ginger, turmeric and candlenuts into a smooth paste with a splash of water.'),
    ('Soto Ayam', 2, 'Heat the oil in a large pot over medium heat and fry the paste for 4 minutes until fragrant.'),
    ('Soto Ayam', 3, 'Add the water, chicken, bruised lemongrass and lime leaves, bring to the boil and simmer 30 minutes until the chicken is tender.'),
    ('Soto Ayam', 4, 'Meanwhile boil the potatoes in a separate pot for 15 minutes, then cut into chunks; boil the eggs for 8 minutes and peel.'),
    ('Soto Ayam', 5, 'Remove the chicken, shred the meat and season the broth with salt and white pepper.'),
    ('Soto Ayam', 6, 'Soak the glass noodles in hot water for 5 minutes and drain.'),
    ('Soto Ayam', 7, 'Place noodles, bean sprouts, chicken, potato and egg in bowls and ladle the hot broth over.'),
    ('Soto Ayam', 8, 'Top with spring onions and fried shallots and serve with lime wedges.'),
    ('Gado-Gado', 1, 'Boil the potatoes in salted water for 15 minutes until tender, then slice; boil the eggs for 8 minutes, peel and halve.'),
    ('Gado-Gado', 2, 'Blanch the green beans, cabbage, spinach and bean sprouts one after another in boiling water for 1 to 2 minutes each, then refresh in cold water and drain.'),
    ('Gado-Gado', 3, 'Cut the tofu into cubes and fry in the oil over medium-high heat for 8 minutes until golden on all sides.'),
    ('Gado-Gado', 4, 'For the sauce, grind or blend the peanuts, garlic, chillies and palm sugar to a coarse paste.'),
    ('Gado-Gado', 5, 'Add the tamarind, kecap manis, coconut milk and warm water and blend, then simmer 3 minutes over low heat; add salt to taste.'),
    ('Gado-Gado', 6, 'Arrange the vegetables, potatoes, tofu, egg and cucumber slices on a platter.'),
    ('Gado-Gado', 7, 'Pour the warm peanut sauce over and top with prawn crackers.'),
    ('Pad Thai with Prawns', 1, 'Soak the noodles in warm water for 25 minutes until pliable but still firm, then drain.'),
    ('Pad Thai with Prawns', 2, 'Stir the tamarind, fish sauce and palm sugar in a small pan over low heat for 2 minutes until the sugar dissolves.'),
    ('Pad Thai with Prawns', 3, 'Heat 2 tablespoons oil in a wok over high heat, fry the diced tofu 3 minutes until golden, then add shallots and garlic for 30 seconds.'),
    ('Pad Thai with Prawns', 4, 'Add the prawns and cook 2 minutes until pink, then push to one side.'),
    ('Pad Thai with Prawns', 5, 'Add the remaining oil, crack in the eggs and scramble 30 seconds.'),
    ('Pad Thai with Prawns', 6, 'Add the noodles and sauce and toss 3 minutes until the noodles absorb the sauce and soften.'),
    ('Pad Thai with Prawns', 7, 'Add half the bean sprouts and the chives, toss 30 seconds, then plate and top with crushed peanuts, chilli flakes, remaining sprouts and lime wedges.'),
    ('Salmon Onigiri', 1, 'Rinse the rice in cold water until the water runs almost clear, then drain and soak it in the water for 20 minutes.'),
    ('Salmon Onigiri', 2, 'Bring to the boil in a lidded pot, then reduce to the lowest heat and cook 12 minutes; turn off the heat and rest covered for 10 minutes.'),
    ('Salmon Onigiri', 3, 'Meanwhile, season the salmon with 0.5 teaspoon salt and grill or pan-fry over medium heat for 4 minutes per side until cooked through.'),
    ('Salmon Onigiri', 4, 'Flake the salmon into small pieces, discarding the skin and bones, and mix with the soy sauce and vinegar.'),
    ('Salmon Onigiri', 5, 'Fluff the rice and let it cool until comfortable to touch.'),
    ('Salmon Onigiri', 6, 'Wet your hands and rub them with a little salt, take a quarter of the rice, press a hollow in the middle and add some salmon.'),
    ('Salmon Onigiri', 7, 'Cover with more rice and shape into a firm triangle with gentle pressure.'),
    ('Salmon Onigiri', 8, 'Sprinkle with sesame seeds and wrap the base of each onigiri with a strip of nori.'),
    ('Egg Fried Rice', 1, 'Beat the eggs with a pinch of salt and finely dice the carrot; slice the spring onions, keeping whites and greens separate.'),
    ('Egg Fried Rice', 2, 'Heat 1 tablespoon oil in a wok over high heat, pour in the eggs and scramble 1 minute until just set, then remove.'),
    ('Egg Fried Rice', 3, 'Add the remaining oil, fry the garlic and spring onion whites for 20 seconds, then the carrot and peas for 2 minutes.'),
    ('Egg Fried Rice', 4, 'Add the cold rice and stir-fry 3 to 4 minutes, pressing out lumps, until piping hot.'),
    ('Egg Fried Rice', 5, 'Return the egg and add the soy sauce, white pepper and sesame oil, tossing for 1 minute.'),
    ('Egg Fried Rice', 6, 'Stir in the spring onion greens and taste for salt before serving.'),
    ('Chicken Satay with Peanut Sauce', 1, 'Soak the skewers in water for 30 minutes so they do not burn.'),
    ('Chicken Satay with Peanut Sauce', 2, 'Blend the lemongrass, 3 shallots, garlic, ginger, turmeric, coriander, cumin, 1 tablespoon palm sugar, 1 tablespoon oil and salt into a paste.'),
    ('Chicken Satay with Peanut Sauce', 3, 'Cut the chicken into 2 cm strips, coat with the paste and marinate at least 1 hour.'),
    ('Chicken Satay with Peanut Sauce', 4, 'For the sauce, blend the remaining shallot, dried chillies (soaked in hot water 10 minutes) and peanuts into a paste.'),
    ('Chicken Satay with Peanut Sauce', 5, 'Fry the paste in 2 tablespoons oil over medium heat for 4 minutes, add the water, coconut milk, tamarind and remaining sugar, and simmer 8 minutes until thick.'),
    ('Chicken Satay with Peanut Sauce', 6, 'Thread the chicken onto skewers and grill over high heat or under a hot grill for 3 to 4 minutes per side, brushing with a little oil, until charred and cooked through.'),
    ('Chicken Satay with Peanut Sauce', 7, 'Serve the satay with the warm peanut sauce, cucumber chunks and raw red onion.'),
    ('Ayam Masak Merah', 1, 'Rub the chicken with turmeric and salt and rest for 15 minutes.'),
    ('Ayam Masak Merah', 2, 'Fry the chicken in hot oil over medium-high heat for 4 minutes per side until golden; remove and drain, leaving 3 tablespoons oil in the pan.'),
    ('Ayam Masak Merah', 3, 'Soak the dried chillies in hot water for 10 minutes, then blend with the shallots, garlic and ginger into a paste.'),
    ('Ayam Masak Merah', 4, 'Fry the cinnamon, star anise and cardamom in the pan oil for 30 seconds, then add the paste and cook 6 minutes over medium heat until the oil separates.'),
    ('Ayam Masak Merah', 5, 'Add the sliced onion, tomato puree, ketchup, tamarind, sugar and water and bring to a simmer.'),
    ('Ayam Masak Merah', 6, 'Return the chicken, cover and simmer on medium-low for 20 minutes until the chicken is cooked and the sauce is thick.'),
    ('Ayam Masak Merah', 7, 'Stir in the peas, cook 2 minutes and serve with steamed rice.'),
    ('Opor Ayam', 1, 'Blend the shallots, garlic, candlenuts, coriander, white pepper and turmeric to a smooth paste.'),
    ('Opor Ayam', 2, 'Heat the oil in a large pot over medium heat and fry the paste with the galangal, bruised lemongrass, bay and lime leaves for 5 minutes until fragrant.'),
    ('Opor Ayam', 3, 'Add the chicken and stir to coat, cooking 5 minutes.'),
    ('Opor Ayam', 4, 'Pour in the water and half the coconut milk, bring to a gentle boil, then simmer covered 25 minutes.'),
    ('Opor Ayam', 5, 'Stir in the remaining coconut milk, palm sugar and salt, and simmer uncovered 8 minutes without boiling hard.'),
    ('Opor Ayam', 6, 'Scatter with fried shallots and serve with steamed rice.'),
    ('Murtabak', 1, 'Knead the flour, water, 1 teaspoon salt and 1 tablespoon ghee into a soft dough for 5 minutes, divide into 4 balls, coat with ghee and rest 1 hour.'),
    ('Murtabak', 2, 'Fry one chopped onion, the garlic and ginger in 1 tablespoon oil over medium heat for 5 minutes, add the beef and curry powder and cook 8 minutes until dry and browned; season with salt.'),
    ('Murtabak', 3, 'Cool the beef, then mix with the sliced spring onions and the second onion, finely chopped, and the beaten eggs (one egg per murtabak, keep separate).'),
    ('Murtabak', 4, 'Stretch one dough ball paper thin on an oiled surface into a large square.'),
    ('Murtabak', 5, 'Spoon a quarter of the filling and one beaten egg on the centre, then fold the sides over to make a sealed square parcel.'),
    ('Murtabak', 6, 'Fry in a little oil over medium heat for 4 minutes per side until golden and crisp and the egg is set.'),
    ('Murtabak', 7, 'Make a quick pickle by mixing sliced cucumber with vinegar, sugar and a pinch of salt.'),
    ('Murtabak', 8, 'Cut the murtabak into squares and serve hot with the pickle.'),
    ('Beef Massaman Curry', 1, 'Cut the beef into 4 cm chunks and wedge the onions.'),
    ('Beef Massaman Curry', 2, 'Heat the oil in a heavy pot over medium heat, add the thick top half of the coconut milk and fry the curry paste 4 minutes until the oil separates.'),
    ('Beef Massaman Curry', 3, 'Add the beef and stir 5 minutes to coat and brown lightly.'),
    ('Beef Massaman Curry', 4, 'Pour in the rest of the coconut milk and the water, add the cinnamon, cardamom and bay leaves, bring to a simmer and cook covered on low heat for 1 hour 15 minutes.'),
    ('Beef Massaman Curry', 5, 'Add the potatoes and onions and cook 25 minutes until the beef and potatoes are tender.'),
    ('Beef Massaman Curry', 6, 'Stir in the fish sauce, palm sugar, tamarind and peanuts, simmer 5 minutes and taste to balance sweet, sour and salty.'),
    ('Beef Massaman Curry', 7, 'Serve with jasmine rice.'),
    ('Thai Green Chicken Curry', 1, 'Slice the chicken into bite-size pieces and cut the aubergines into wedges.'),
    ('Thai Green Chicken Curry', 2, 'Heat the oil in a wok or pot over medium heat, add the curry paste and 200 ml of the thick coconut milk, and fry 4 minutes until fragrant.'),
    ('Thai Green Chicken Curry', 3, 'Add the chicken and stir for 4 minutes until it changes colour.'),
    ('Thai Green Chicken Curry', 4, 'Pour in the rest of the coconut milk and the water, add lime leaves, and simmer gently for 8 minutes.'),
    ('Thai Green Chicken Curry', 5, 'Add the aubergines and beans and cook 6 minutes until tender.'),
    ('Thai Green Chicken Curry', 6, 'Stir in the fish sauce and palm sugar, taste and adjust, then add the basil and sliced chilli.'),
    ('Thai Green Chicken Curry', 7, 'Serve with steamed jasmine rice.'),
    ('Chicken Piaparan', 1, 'Toast the desiccated coconut in a dry pan over medium heat for 4 minutes until deep brown, then grind it into a rough paste.'),
    ('Chicken Piaparan', 2, 'Pound or blend half the spring onions, chillies, ginger and turmeric into a coarse palapa relish.'),
    ('Chicken Piaparan', 3, 'Heat the oil in a pot over medium heat and cook the chopped onion and garlic for 4 minutes.'),
    ('Chicken Piaparan', 4, 'Add the chicken and brown on all sides for 6 minutes, then stir in the palapa and cook 2 minutes.'),
    ('Chicken Piaparan', 5, 'Add the water, lemongrass and half the coconut milk, cover and simmer 25 minutes until the chicken is tender.'),
    ('Chicken Piaparan', 6, 'Stir in the toasted coconut, remaining coconut milk, salt and sugar and cook 5 minutes uncovered.'),
    ('Chicken Piaparan', 7, 'Top with the rest of the sliced spring onions and serve with steamed rice.'),
    ('Chicken Teriyaki', 1, 'Mix the soy sauce, honey, sugar, apple juice, rice vinegar, grated ginger, crushed garlic and cornflour in a bowl.'),
    ('Chicken Teriyaki', 2, 'Heat the oil in a large frying pan over medium-high heat and place the chicken skin-side down.'),
    ('Chicken Teriyaki', 3, 'Cook 6 minutes until the skin is golden, flip and cook 5 minutes more until almost cooked through.'),
    ('Chicken Teriyaki', 4, 'Steam or boil the broccoli for 4 minutes until bright green and tender.'),
    ('Chicken Teriyaki', 5, 'Pour the sauce into the pan, lower the heat to medium and simmer 3 to 4 minutes, turning the chicken, until the sauce is thick and glossy.'),
    ('Chicken Teriyaki', 6, 'Slice the chicken, spoon the sauce over and serve on rice with the broccoli.'),
    ('Chicken Teriyaki', 7, 'Sprinkle with sesame seeds and sliced spring onions.'),
    ('Beef Bulgogi', 1, 'Grate the pear and mix it with the soy sauce, sugar, honey, rice vinegar, sesame oil, crushed garlic, ginger and pepper.'),
    ('Beef Bulgogi', 2, 'Add the sliced beef, toss well and marinate in the fridge for at least 1 hour, up to overnight.'),
    ('Beef Bulgogi', 3, 'Slice the onion into half moons and the spring onions into 3 cm lengths.'),
    ('Beef Bulgogi', 4, 'Heat the vegetable oil in a large frying pan or cast iron skillet over high heat.'),
    ('Beef Bulgogi', 5, 'Cook the beef in two batches for 2 to 3 minutes each, with the onion, until browned and caramelised at the edges.'),
    ('Beef Bulgogi', 6, 'Stir in the spring onions and sesame seeds, cook 30 seconds.'),
    ('Beef Bulgogi', 7, 'Serve with rice and lettuce leaves for wrapping.'),
    ('Cumin Lamb Stir-Fry', 1, 'Toast the cumin seeds in a dry pan over medium heat for 1 to 2 minutes until fragrant, then crush them coarsely.'),
    ('Cumin Lamb Stir-Fry', 2, 'Toss the lamb with the soy sauce, cornflour and half the crushed cumin and marinate 15 minutes.'),
    ('Cumin Lamb Stir-Fry', 3, 'Slice the onion, green chillies, garlic and spring onions.'),
    ('Cumin Lamb Stir-Fry', 4, 'Heat 2 tablespoons oil in a wok over very high heat until smoking and sear the lamb for 2 minutes without moving, then stir-fry 1 more minute; remove.'),
    ('Cumin Lamb Stir-Fry', 5, 'Add the remaining oil and fry the onion, garlic and green chillies for 2 minutes.'),
    ('Cumin Lamb Stir-Fry', 6, 'Return the lamb and add the chilli flakes, Sichuan pepper, salt and remaining cumin, tossing for 1 minute.'),
    ('Cumin Lamb Stir-Fry', 7, 'Stir in the spring onions and coriander and serve at once with rice or flatbread.'),
    ('Pisang Goreng (Banana Fritters)', 1, 'Whisk the plain flour, rice flour, sugar, baking powder, salt and turmeric in a bowl.'),
    ('Pisang Goreng (Banana Fritters)', 2, 'Gradually whisk in the cold water to make a smooth batter the thickness of single cream.'),
    ('Pisang Goreng (Banana Fritters)', 3, 'Peel the bananas and cut each in half lengthways, or in thirds if small.'),
    ('Pisang Goreng (Banana Fritters)', 4, 'Heat the oil in a deep pan over medium heat to about 170 C (a drop of batter should sizzle and rise).'),
    ('Pisang Goreng (Banana Fritters)', 5, 'Dip each banana piece in the batter, let the excess drip off, and lower into the oil.'),
    ('Pisang Goreng (Banana Fritters)', 6, 'Fry in batches for 3 to 4 minutes, turning once, until deep golden and crisp.'),
    ('Pisang Goreng (Banana Fritters)', 7, 'Drain on paper towels and serve warm.'),
    ('Klepon (Palm Sugar Rice Balls)', 1, 'Mix the glutinous rice flour with the pandan juice and warm water, kneading to a soft dough that does not crack.'),
    ('Klepon (Palm Sugar Rice Balls)', 2, 'Chop or grate the palm sugar into small pieces.'),
    ('Klepon (Palm Sugar Rice Balls)', 3, 'Pinch off walnut-sized pieces of dough, flatten each, place a piece of palm sugar in the middle and seal into a smooth ball.'),
    ('Klepon (Palm Sugar Rice Balls)', 4, 'Bring the water to a boil in a large pot over high heat.'),
    ('Klepon (Palm Sugar Rice Balls)', 5, 'Drop in the balls in batches and cook 3 to 4 minutes until they float, then 1 more minute.'),
    ('Klepon (Palm Sugar Rice Balls)', 6, 'Meanwhile steam the grated coconut with the salt for 10 minutes.'),
    ('Klepon (Palm Sugar Rice Balls)', 7, 'Lift the balls out with a slotted spoon, drain well and roll them in the coconut.'),
    ('Klepon (Palm Sugar Rice Balls)', 8, 'Serve at room temperature.'),
    ('Canjeero (Laxoox Pancakes)', 1, 'In a large bowl, mix the plain flour, semolina, yeast, 2 tablespoons of the sugar, baking powder and salt.'),
    ('Canjeero (Laxoox Pancakes)', 2, 'Pour in the warm water gradually, whisking until you have a smooth, thin batter like single cream.'),
    ('Canjeero (Laxoox Pancakes)', 3, 'Cover the bowl with a clean towel and leave in a warm place for 1 hour until the batter is bubbly and has risen slightly.'),
    ('Canjeero (Laxoox Pancakes)', 4, 'Heat a non-stick frying pan over medium heat and wipe it with a little oil on kitchen paper.'),
    ('Canjeero (Laxoox Pancakes)', 5, 'Pour in a ladle of batter and tilt the pan to spread it into a thin circle. Cook for 2 to 3 minutes without flipping, until the top is dry and covered in small holes.'),
    ('Canjeero (Laxoox Pancakes)', 6, 'Slide the canjeero onto a plate and repeat with the remaining batter, re-oiling the pan lightly every few pancakes.'),
    ('Canjeero (Laxoox Pancakes)', 7, 'Serve warm, brushed with melted butter and sprinkled with the remaining 1 tablespoon sugar, with sweet tea on the side.'),
    ('Akara (Bean Fritters)', 1, 'Soak the black-eyed beans in plenty of cold water for 15 minutes, then rub them between your hands to loosen the skins. Rinse repeatedly, pouring off the floating skins, until most are gone.'),
    ('Akara (Bean Fritters)', 2, 'Roughly chop the onion, scotch bonnet and red pepper and place them in a blender with the peeled beans and 100 ml cold water.'),
    ('Akara (Bean Fritters)', 3, 'Blend until you have a thick, smooth paste, adding a splash more water only if the blender struggles.'),
    ('Akara (Bean Fritters)', 4, 'Transfer the paste to a bowl, add the salt and whisk vigorously with a wooden spoon for 3 to 5 minutes until the batter is light, fluffy and slightly paler.'),
    ('Akara (Bean Fritters)', 5, 'Heat the vegetable oil in a deep, heavy pan over medium-high heat until a drop of batter sizzles and rises straight away, about 180C.'),
    ('Akara (Bean Fritters)', 6, 'Scoop heaped tablespoons of batter into the hot oil, a few at a time, and fry for 3 to 4 minutes, turning once, until deep golden brown.'),
    ('Akara (Bean Fritters)', 7, 'Lift out with a slotted spoon, drain on kitchen paper and serve hot.'),
    ('Swahili Chapati', 1, 'Mix the plain flour, salt and sugar in a large bowl, then add 2 tablespoons of the oil and rub it in with your fingers.'),
    ('Swahili Chapati', 2, 'Add the warm water a little at a time and knead for 10 minutes into a soft, smooth, slightly sticky dough.'),
    ('Swahili Chapati', 3, 'Cover the dough with a damp cloth and rest it for 30 minutes.'),
    ('Swahili Chapati', 4, 'Divide the dough into 6 balls. Roll one out thinly into a large circle, brush with oil, then roll it up like a sausage and coil the rope into a snail shape. Repeat with the rest and let the coils rest for 15 minutes.'),
    ('Swahili Chapati', 5, 'Roll each coil out flat into a circle about 3 mm thick.'),
    ('Swahili Chapati', 6, 'Heat a dry frying pan over medium heat. Cook one chapati for 1 minute until small bubbles form, flip, and brush the cooked side with a teaspoon of oil.'),
    ('Swahili Chapati', 7, 'Flip again, oil the other side, and cook for 1 to 2 minutes more, pressing gently, until golden with brown spots. Keep the cooked chapatis wrapped in a towel while you cook the rest.'),
    ('Misir Wat (Spiced Red Lentils)', 1, 'Rinse the red lentils in a sieve under cold water until the water runs clear.'),
    ('Misir Wat (Spiced Red Lentils)', 2, 'Finely chop the onions. Place them in a large dry pot over medium heat and cook, stirring, for 8 minutes until softened and beginning to catch, without any fat yet.'),
    ('Misir Wat (Spiced Red Lentils)', 3, 'Add the spiced clarified butter, grated garlic and ginger, and stir for 2 minutes until fragrant.'),
    ('Misir Wat (Spiced Red Lentils)', 4, 'Stir in the berbere and tomato paste and cook for 3 minutes, adding a splash of water if it sticks.'),
    ('Misir Wat (Spiced Red Lentils)', 5, 'Add the lentils and 900 ml water, bring to the boil, then reduce to low heat.'),
    ('Misir Wat (Spiced Red Lentils)', 6, 'Simmer, partly covered, for 25 minutes, stirring often, until the lentils collapse into a thick stew. Add a little water if it gets too thick.'),
    ('Misir Wat (Spiced Red Lentils)', 7, 'Season with salt and serve warm with injera or flatbread.'),
    ('Shiro (Chickpea Stew)', 1, 'Finely chop the onions and cook them in a pot with no oil over medium heat for 6 minutes, stirring, until soft and golden.'),
    ('Shiro (Chickpea Stew)', 2, 'Add the vegetable oil, chopped garlic and chopped tomatoes and cook for 5 minutes until the tomatoes break down.'),
    ('Shiro (Chickpea Stew)', 3, 'Stir in the berbere and cook for 1 minute.'),
    ('Shiro (Chickpea Stew)', 4, 'Pour in the water and bring to a gentle simmer over medium heat.'),
    ('Shiro (Chickpea Stew)', 5, 'Sprinkle in the shiro powder slowly with one hand while whisking constantly with the other, so no lumps form.'),
    ('Shiro (Chickpea Stew)', 6, 'Reduce to low heat and cook for 10 to 12 minutes, stirring often, until thick, smooth and glossy. Add a splash of water if too thick.'),
    ('Shiro (Chickpea Stew)', 7, 'Season with salt and serve hot with injera or flatbread.'),
    ('Moi Moi (Steamed Bean Pudding)', 1, 'Soak the beans in cold water for 15 minutes, rub to remove the skins and rinse until mostly clean.'),
    ('Moi Moi (Steamed Bean Pudding)', 2, 'Hard-boil 3 of the eggs for 10 minutes, cool in cold water, peel and cut into quarters.'),
    ('Moi Moi (Steamed Bean Pudding)', 3, 'Blend the peeled beans with the peppers, onion and 300 ml warm water until completely smooth.'),
    ('Moi Moi (Steamed Bean Pudding)', 4, 'Pour into a bowl and stir in the oil, crumbled stock cube, ground crayfish and salt. Beat in the remaining raw egg.'),
    ('Moi Moi (Steamed Bean Pudding)', 5, 'Flake the drained mackerel into the batter and mix gently.'),
    ('Moi Moi (Steamed Bean Pudding)', 6, 'Pour the mixture into 6 oiled ramekins or heatproof cups, filling about three-quarters, and add a piece of boiled egg to each.'),
    ('Moi Moi (Steamed Bean Pudding)', 7, 'Cover each with foil. Place on a rack in a large pot with 3 cm of simmering water, cover the pot and steam over medium heat for 45 minutes until firm and a skewer comes out clean. Top up the water as needed.'),
    ('Waakye (Rice & Beans)', 1, 'Rinse the beans, place them in a large pot with the waakye leaves, baking soda and 1.5 litres water. Bring to the boil over high heat, then simmer on medium-low for 40 minutes until the beans are half cooked and the water is deep red-brown.'),
    ('Waakye (Rice & Beans)', 2, 'Rinse the rice in cold water until it runs clear.'),
    ('Waakye (Rice & Beans)', 3, 'Remove the leaves, add the rice and salt to the beans, stir and top up with water if needed so it sits about 2 cm above the rice.'),
    ('Waakye (Rice & Beans)', 4, 'Cover tightly and cook over low heat for 25 minutes until the rice is tender and has absorbed the liquid. Rest, covered, for 10 minutes.'),
    ('Waakye (Rice & Beans)', 5, 'Meanwhile, hard-boil the eggs for 10 minutes, cool and peel them.'),
    ('Waakye (Rice & Beans)', 6, 'Slice the plantains diagonally and fry in the oil over medium heat for 2 to 3 minutes per side until golden and caramelised.'),
    ('Waakye (Rice & Beans)', 7, 'Serve the waakye with the eggs, plantain, gari and a spoonful of shito.'),
    ('Sukuma Wiki with Ugali', 1, 'Strip the collard leaves from their thick stems, stack the leaves, roll them up and slice into thin ribbons. Wash well and drain.'),
    ('Sukuma Wiki with Ugali', 2, 'Heat the oil in a large pan over medium heat and fry the sliced onion for 5 minutes until soft and golden.'),
    ('Sukuma Wiki with Ugali', 3, 'Add the garlic and chopped tomatoes and cook for 5 minutes until they break down into a thick sauce. Stir in the ground coriander.'),
    ('Sukuma Wiki with Ugali', 4, 'Add the greens in handfuls, turning until they wilt, then cook over medium heat for 8 to 10 minutes until tender but still bright green. Season with salt.'),
    ('Sukuma Wiki with Ugali', 5, 'For the ugali, bring 600 ml of water to the boil in a heavy pot. Mix 100 g of the maize flour with 300 ml cold water and stir this into the boiling water to make a thin paste.'),
    ('Sukuma Wiki with Ugali', 6, 'Cook for 3 minutes, then add the remaining maize flour in batches, mixing hard with a wooden spoon over low heat until it forms a stiff dough that pulls from the sides, about 5 minutes.'),
    ('Sukuma Wiki with Ugali', 7, 'Cover and cook for 2 more minutes, then shape into a mound with the spoon. Serve slices of ugali with the greens.'),
    ('Bariis Iskukaris (Spiced Rice with Lamb)', 1, 'Place the lamb in a pot with 700 ml water, 1 teaspoon salt and half the onion. Bring to the boil, skim, then simmer covered over low heat for 50 minutes until tender. Drain, keeping the stock.'),
    ('Bariis Iskukaris (Spiced Rice with Lamb)', 2, 'Rinse the basmati rice until the water runs clear, then soak for 20 minutes and drain.'),
    ('Bariis Iskukaris (Spiced Rice with Lamb)', 3, 'Heat the oil in a large heavy pot over medium heat. Fry the remaining sliced onions with the cinnamon stick and whole cloves for 8 minutes until golden.'),
    ('Bariis Iskukaris (Spiced Rice with Lamb)', 4, 'Add the garlic and grated tomatoes and cook for 5 minutes. Stir in the cumin, coriander, cardamom and ground cinnamon and cook for 1 minute.'),
    ('Bariis Iskukaris (Spiced Rice with Lamb)', 5, 'Add the lamb and fry for 3 minutes, then add the drained rice and stir for 1 minute.'),
    ('Bariis Iskukaris (Spiced Rice with Lamb)', 6, 'Measure 650 ml of the lamb stock, adding water if needed, and pour it in with the grated carrot, raisins and remaining salt. Bring to the boil.'),
    ('Bariis Iskukaris (Spiced Rice with Lamb)', 7, 'Cover tightly, reduce to the lowest heat and cook for 20 minutes. Rest for 10 minutes off the heat, fluff with a fork and serve with a banana on the side, as Somalis do, and a squeeze of lime.'),
    ('Doro Wat (Chicken Stew)', 1, 'Skin the chicken, score the pieces with a knife and rub with the lemon juice and half the salt. Leave for 15 minutes.'),
    ('Doro Wat (Chicken Stew)', 2, 'Finely chop the onions and cook them in a large heavy pot over medium heat with no oil for 10 minutes, stirring, until they release their water and soften.'),
    ('Doro Wat (Chicken Stew)', 3, 'Add the spiced clarified butter, garlic and ginger and cook for 5 minutes until the onions turn golden and jammy.'),
    ('Doro Wat (Chicken Stew)', 4, 'Stir in the berbere and tomato paste, add a splash of water and cook for 10 minutes over low heat until the sauce deepens in colour.'),
    ('Doro Wat (Chicken Stew)', 5, 'Add the chicken and 500 ml water, then stir to coat. Cover and simmer over low heat for 40 minutes, turning the pieces occasionally.'),
    ('Doro Wat (Chicken Stew)', 6, 'Meanwhile, boil the eggs for 10 minutes, cool, peel and prick lightly with a fork. Add them to the stew for the last 10 minutes.'),
    ('Doro Wat (Chicken Stew)', 7, 'Season with the remaining salt and serve with injera.'),
    ('Zigni (Spiced Beef Stew)', 1, 'Finely chop the onions and cook them in a large heavy pot over medium heat for 10 minutes with no oil, stirring, until soft and reduced.'),
    ('Zigni (Spiced Beef Stew)', 2, 'Add the vegetable oil, garlic and ginger and cook for 3 minutes.'),
    ('Zigni (Spiced Beef Stew)', 3, 'Stir in the berbere and tomato paste and cook gently for 5 minutes, adding a splash of water if it sticks.'),
    ('Zigni (Spiced Beef Stew)', 4, 'Add the beef, salt and 600 ml water. Bring to a boil, cover and simmer over low heat for 1 hour 30 minutes, stirring now and then, until the beef is very tender.'),
    ('Zigni (Spiced Beef Stew)', 5, 'Boil the eggs for 10 minutes, peel them and add them to the pot for the last 10 minutes.'),
    ('Zigni (Spiced Beef Stew)', 6, 'Stir in the spiced clarified butter, cook uncovered for 5 minutes until the sauce is thick and oily, and serve with injera.'),
    ('Egusi Soup', 1, 'Place the beef in a pot with half the chopped onion, the stock cube, a little salt and 700 ml water. Cook over medium heat for 35 minutes until nearly tender, then keep the stock.'),
    ('Egusi Soup', 2, 'Blend the peppers and the remaining onion into a coarse puree.'),
    ('Egusi Soup', 3, 'Heat the palm oil in a wide pot over medium heat for 2 minutes, then add the pepper puree and fry for 10 minutes until the water has cooked off and the oil rises.'),
    ('Egusi Soup', 4, 'Mix the ground egusi with 4 tablespoons of water into a thick paste and drop spoonfuls into the oil. Do not stir; let them cook for 5 minutes until they form soft curds, then fold gently.'),
    ('Egusi Soup', 5, 'Add the beef with about 400 ml of its stock, the crayfish and the cleaned smoked fish. Simmer on low heat for 10 minutes.'),
    ('Egusi Soup', 6, 'Stir in the chopped spinach and cook for 3 to 4 minutes until just wilted. Taste, adjust the salt and serve hot with pounded yam, eba or rice.'),
    ('Suya (Spiced Beef Skewers)', 1, 'Grind the roasted peanuts in a food processor or blender to a coarse powder, being careful not to turn them into butter.'),
    ('Suya (Spiced Beef Skewers)', 2, 'Mix the ground peanuts with the ginger, garlic powder, onion powder, smoked paprika, cayenne, crumbled stock cube and salt. This is your yaji spice.'),
    ('Suya (Spiced Beef Skewers)', 3, 'Place the beef slices in a bowl, pour on the oil and rub in two-thirds of the yaji spice until every slice is coated. Marinate for at least 30 minutes.'),
    ('Suya (Spiced Beef Skewers)', 4, 'Thread the beef onto skewers, folding the slices over as you go. If using wooden skewers, soak them in water first.'),
    ('Suya (Spiced Beef Skewers)', 5, 'Heat a grill, griddle pan or barbecue to high and cook the skewers for 3 to 4 minutes per side until browned with charred edges.'),
    ('Suya (Spiced Beef Skewers)', 6, 'Sprinkle the skewers with the remaining yaji and serve with sliced raw onion and tomato.'),
    ('Thieboudienne (Fish & Rice)', 1, 'Make the stuffing by blitzing the parsley, 4 garlic cloves, half the scotch bonnet, half an onion, salt and black pepper into a coarse paste. Cut slits in the fish and press the paste in. Marinate for 30 minutes.'),
    ('Thieboudienne (Fish & Rice)', 2, 'Heat the oil in a large heavy pot over medium-high heat and fry the fish for 3 minutes per side until lightly golden. Remove and set aside.'),
    ('Thieboudienne (Fish & Rice)', 3, 'In the same oil, fry the remaining sliced onion for 5 minutes, then add the tomato paste and cook for 5 minutes, stirring.'),
    ('Thieboudienne (Fish & Rice)', 4, 'Add 1.5 litres water, crumbled stock cube, tamarind and the whole carrots, cassava and aubergine cut in large chunks. Simmer over medium heat for 20 minutes, then add the cabbage wedges and cook 10 minutes more until all vegetables are tender.'),
    ('Thieboudienne (Fish & Rice)', 5, 'Return the fish to the pot for the last 8 minutes of cooking, then carefully lift the fish and vegetables out onto a plate and keep warm.'),
    ('Thieboudienne (Fish & Rice)', 6, 'Rinse the rice, add it to the strained broth (about 700 ml, topping up with water if needed) and bring to the boil.'),
    ('Thieboudienne (Fish & Rice)', 7, 'Cover tightly and cook on the lowest heat for 20 minutes until the rice is tender and a little crusty at the bottom. Serve the rice on a platter topped with the fish and vegetables.'),
    ('Chicken Yassa', 1, 'Slice the onions into thin half-moons. Mix them in a large bowl with the lemon juice, mustard, crushed garlic, chopped chilli, black pepper, salt and 2 tablespoons of oil.'),
    ('Chicken Yassa', 2, 'Add the chicken and turn to coat. Cover and marinate in the fridge for at least 4 hours, or overnight.'),
    ('Chicken Yassa', 3, 'Lift the chicken out of the marinade, keeping the onions. Grill under a hot grill or on a barbecue for 6 to 8 minutes per side until browned and charred in places.'),
    ('Chicken Yassa', 4, 'Heat the remaining oil in a large pot over medium heat. Add the marinated onions and bay leaves and cook for 15 minutes, stirring, until soft and sweet.'),
    ('Chicken Yassa', 5, 'Add 150 ml water and the browned chicken. Cover and simmer over low heat for 30 minutes until the chicken is cooked through and the sauce is thick.'),
    ('Chicken Yassa', 6, 'Stir in the olives and cook for 3 minutes. Serve hot over white rice.'),
    ('Mafe (Peanut Stew)', 1, 'Heat the oil in a large heavy pot over medium-high heat and brown the beef in batches for 6 to 8 minutes, then set aside.'),
    ('Mafe (Peanut Stew)', 2, 'In the same pot, cook the sliced onions for 6 minutes until golden, then add the garlic and tomato paste and cook 3 minutes.'),
    ('Mafe (Peanut Stew)', 3, 'Return the beef, add the crumbled stock cube, whole scotch bonnet and 1 litre of water. Bring to the boil, cover and simmer over low heat for 45 minutes.'),
    ('Mafe (Peanut Stew)', 4, 'Whisk the peanut butter with a ladle of the hot broth until smooth, then stir it back into the pot.'),
    ('Mafe (Peanut Stew)', 5, 'Add the sweet potato, carrots and cabbage in big chunks. Simmer uncovered over medium-low heat for 25 minutes until the vegetables are tender and the oil from the peanut butter rises to the surface.'),
    ('Mafe (Peanut Stew)', 6, 'Remove the scotch bonnet, season with salt and serve over rice. Cook the rice according to its packet while the stew simmers.'),
    ('Swahili Pilau', 1, 'Boil the beef in 500 ml water with the salt, half the garlic and half the ginger over medium heat for 40 minutes, until nearly tender. Drain, saving the stock.'),
    ('Swahili Pilau', 2, 'Rinse the rice and soak in water for 15 minutes, then drain.'),
    ('Swahili Pilau', 3, 'Heat the oil in a heavy pot over medium heat, add the cumin seeds and cinnamon stick for 30 seconds, then add the sliced onions and cook for 15 minutes until deep golden brown.'),
    ('Swahili Pilau', 4, 'Add the remaining garlic and ginger, the chopped tomatoes and pilau masala, and cook for 5 minutes until the tomatoes collapse.'),
    ('Swahili Pilau', 5, 'Add the beef and quartered potatoes and stir for 3 minutes.'),
    ('Swahili Pilau', 6, 'Add the drained rice and about 650 ml of the beef stock (top up with water). Bring to the boil, then cover and cook on the lowest heat for 20 minutes.'),
    ('Swahili Pilau', 7, 'Rest for 10 minutes without lifting the lid, then fluff the rice with a fork and serve with kachumbari (tomato and onion salad).'),
    ('Samaki wa Kupaka (Coconut Fish Curry)', 1, 'Rub the fish with the lemon juice, half the turmeric, half the cumin, half the garlic and salt. Leave for 15 minutes.'),
    ('Samaki wa Kupaka (Coconut Fish Curry)', 2, 'Grill or pan-fry the fish in 2 tablespoons of oil over medium-high heat for 3 to 4 minutes per side until golden and just cooked. Set aside.'),
    ('Samaki wa Kupaka (Coconut Fish Curry)', 3, 'In a wide pan, heat the remaining oil over medium heat and cook the finely chopped onion for 5 minutes until soft.'),
    ('Samaki wa Kupaka (Coconut Fish Curry)', 4, 'Add the remaining garlic, grated ginger, turmeric, cumin and the sliced chilli, and cook for 1 minute.'),
    ('Samaki wa Kupaka (Coconut Fish Curry)', 5, 'Pour in the coconut milk and tamarind paste, stir and simmer gently for 8 minutes until slightly thickened.'),
    ('Samaki wa Kupaka (Coconut Fish Curry)', 6, 'Slide the fish into the sauce and spoon the sauce over for 3 minutes. Sprinkle with fresh coriander and serve with rice or chapati.'),
    ('Sambusa', 1, 'Cook the minced beef in a dry pan over medium-high heat for 8 minutes, breaking it up, until browned and any liquid has evaporated.'),
    ('Sambusa', 2, 'Add the finely chopped onion, garlic and chilli, then cook for 5 minutes. Stir in the cumin, coriander, turmeric and salt and cook for 2 minutes.'),
    ('Sambusa', 3, 'Remove from the heat, stir in the chopped fresh coriander and spring onions, and let the filling cool completely.'),
    ('Sambusa', 4, 'Mix the flour and water into a thin paste for sealing.'),
    ('Sambusa', 5, 'Cut each pastry sheet into strips about 8 cm wide. Put a spoonful of filling at one end of a strip and fold the corner over it to form a triangle, then keep folding the strip along its length like a flag. Seal the end with the flour paste.'),
    ('Sambusa', 6, 'Heat the oil in a deep pan over medium heat to about 170C. Fry the sambusas in batches for 2 to 3 minutes per side until golden brown and crisp.'),
    ('Sambusa', 7, 'Drain on kitchen paper and serve hot with lemon wedges or chilli sauce.'),
    ('Kelewele (Spiced Plantain)', 1, 'Peel the plantains and cut them into 2 cm cubes.'),
    ('Kelewele (Spiced Plantain)', 2, 'Grate the ginger and garlic, then mix them in a bowl with the cayenne, ground cloves, nutmeg and salt.'),
    ('Kelewele (Spiced Plantain)', 3, 'Add the plantain cubes and toss until every piece is coated. Rest for 10 minutes.'),
    ('Kelewele (Spiced Plantain)', 4, 'Heat the oil in a deep pan over medium heat to about 170C.'),
    ('Kelewele (Spiced Plantain)', 5, 'Fry the plantain in two batches for 4 to 5 minutes, turning, until the edges are dark golden and caramelised.'),
    ('Kelewele (Spiced Plantain)', 6, 'Drain on kitchen paper and serve warm with roasted peanuts.'),
    ('Mandazi', 1, 'In a large bowl, mix the flour, sugar, baking powder, cardamom, salt and desiccated coconut.'),
    ('Mandazi', 2, 'Rub in the cold butter with your fingertips until the mixture looks like breadcrumbs.'),
    ('Mandazi', 3, 'Beat the egg with the milk and add to the dry ingredients, mixing to form a soft dough. Knead for 3 minutes until smooth.'),
    ('Mandazi', 4, 'Cover and rest the dough for 20 minutes.'),
    ('Mandazi', 5, 'Roll out the dough to about 1 cm thick and cut into triangles or diamonds with a knife.'),
    ('Mandazi', 6, 'Heat the oil in a deep pan over medium heat to about 170C. Fry the mandazi in batches for 2 to 3 minutes per side, until puffed and golden brown.'),
    ('Mandazi', 7, 'Drain on kitchen paper and serve warm or at room temperature.'),
    ('Puff-Puff', 1, 'In a large bowl, mix the flour, sugar, yeast, nutmeg and salt.'),
    ('Puff-Puff', 2, 'Gradually pour in the warm water, whisking by hand for 2 to 3 minutes into a thick, smooth, stretchy batter.'),
    ('Puff-Puff', 3, 'Cover the bowl with a towel and leave in a warm place for 1 hour until doubled in size and full of bubbles.'),
    ('Puff-Puff', 4, 'Heat the oil in a deep, heavy pan over medium heat to about 170C. Stir the batter gently once.'),
    ('Puff-Puff', 5, 'Scoop a small handful of batter, squeeze it through your fist or use a spoon and drop balls the size of a golf ball into the oil. Fry in batches without crowding.'),
    ('Puff-Puff', 6, 'Cook for 4 to 5 minutes, turning often, until deep golden brown all over.'),
    ('Puff-Puff', 7, 'Remove with a slotted spoon, drain on kitchen paper and serve warm.'),
    ('Fluffy Pancakes with Berries', 1, 'Whisk the plain flour, baking powder, caster sugar and salt together in a large bowl.'),
    ('Fluffy Pancakes with Berries', 2, 'Melt the unsalted butter in a small pan or the microwave and let it cool for 2 minutes.'),
    ('Fluffy Pancakes with Berries', 3, 'In a jug, beat the egg with the whole milk, melted butter and vanilla powder.'),
    ('Fluffy Pancakes with Berries', 4, 'Pour the wet mixture into the dry ingredients and stir gently until just combined; a few small lumps are fine and keep the pancakes fluffy. Rest the batter for 5 minutes.'),
    ('Fluffy Pancakes with Berries', 5, 'Heat a non-stick frying pan over medium heat and lightly grease it. Pour in about 60 ml (a quarter cup) of batter per pancake.'),
    ('Fluffy Pancakes with Berries', 6, 'Cook for 2 to 3 minutes until bubbles appear on the surface, then flip and cook for 1 to 2 minutes until golden.'),
    ('Fluffy Pancakes with Berries', 7, 'Keep the cooked pancakes warm under a clean tea towel while you finish the batter, then stack them and top with sliced strawberries, blueberries and maple syrup.'),
    ('Spinach & Feta Omelette', 1, 'Wash the spinach and roughly chop it. Slice the spring onions and crumble the feta cheese.'),
    ('Spinach & Feta Omelette', 2, 'Heat half of the olive oil in a non-stick frying pan over medium heat. Cook the spring onions for 1 minute, add the spinach and stir for 1 to 2 minutes until wilted. Tip it into a bowl.'),
    ('Spinach & Feta Omelette', 3, 'Crack the eggs into a bowl, add the oregano, black pepper and a small pinch of salt (feta is already salty), and whisk well.'),
    ('Spinach & Feta Omelette', 4, 'Wipe the pan, add the remaining olive oil and heat over medium heat. Pour in half of the egg mixture.'),
    ('Spinach & Feta Omelette', 5, 'Cook for 2 minutes, gently pulling the set edges towards the centre, until the base is set but the top is still slightly creamy.'),
    ('Spinach & Feta Omelette', 6, 'Scatter half of the spinach and feta over one side, fold the omelette over, and cook for 1 more minute. Slide onto a plate and repeat with the remaining mixture.'),
    ('Greek Yogurt Parfait with Granola', 1, 'Wash the strawberries and blueberries, then hull and slice the strawberries.'),
    ('Greek Yogurt Parfait with Granola', 2, 'Stir the vanilla powder and 1 tablespoon of the honey into the Greek yogurt until smooth.'),
    ('Greek Yogurt Parfait with Granola', 3, 'Spoon a layer of yogurt into the bottom of four tall glasses, about one third of the total.'),
    ('Greek Yogurt Parfait with Granola', 4, 'Add a layer of granola and a layer of berries to each glass.'),
    ('Greek Yogurt Parfait with Granola', 5, 'Repeat the layers once more, finishing with a final layer of yogurt on top.'),
    ('Greek Yogurt Parfait with Granola', 6, 'Top with the remaining berries, flaked almonds and a drizzle of the remaining honey. Serve straight away so the granola stays crunchy.'),
    ('Beef & Egg Breakfast Burrito', 1, 'Finely dice the onion and red pepper, and grate the cheddar cheese.'),
    ('Beef & Egg Breakfast Burrito', 2, 'Heat the vegetable oil in a large frying pan over medium-high heat. Fry the onion and pepper for 4 minutes until soft.'),
    ('Beef & Egg Breakfast Burrito', 3, 'Add the minced beef and cook for 6 to 7 minutes, breaking it up with a spoon, until browned with no pink left. Stir in the cumin, smoked paprika, garlic powder, salt and pepper and cook for 1 minute.'),
    ('Beef & Egg Breakfast Burrito', 4, 'Push the beef to one side of the pan, pour in the beaten eggs on the other side, and scramble gently for 2 minutes until just set. Stir everything together.'),
    ('Beef & Egg Breakfast Burrito', 5, 'Warm the tortillas for 20 seconds each in a dry pan or the microwave so they are soft and will not crack.'),
    ('Beef & Egg Breakfast Burrito', 6, 'Spoon the beef and egg mixture down the centre of each tortilla, add cheese and salsa, fold in the sides and roll up tightly. Serve warm, cut in half.'),
    ('Spaghetti Bolognese', 1, 'Finely chop the onion, carrot and celery, and crush the garlic.'),
    ('Spaghetti Bolognese', 2, 'Heat the olive oil in a large heavy pan over medium heat. Cook the onion, carrot and celery for 8 minutes until soft, adding the garlic for the last minute.'),
    ('Spaghetti Bolognese', 3, 'Turn the heat to high, add the minced beef and cook for 6 to 8 minutes, breaking it up, until well browned.'),
    ('Spaghetti Bolognese', 4, 'Stir in the tomato puree and cook for 1 minute, then add the chopped tomatoes, beef stock, oregano, basil, bay leaf, salt and pepper.'),
    ('Spaghetti Bolognese', 5, 'Reduce the heat to low and simmer, partly covered, for 40 minutes, stirring now and then. Stir in the milk for the last 5 minutes and remove the bay leaf.'),
    ('Spaghetti Bolognese', 6, 'Meanwhile, cook the spaghetti in a large pan of salted boiling water for 9 to 11 minutes until al dente, then drain.'),
    ('Spaghetti Bolognese', 7, 'Serve the sauce spooned over the spaghetti with freshly grated parmesan cheese.'),
    ('Chicken Alfredo Pasta', 1, 'Slice the chicken breast in half horizontally to make thinner fillets, then season both sides with salt, pepper and the dried Italian herbs.'),
    ('Chicken Alfredo Pasta', 2, 'Heat the olive oil in a large frying pan over medium-high heat and cook the chicken for 5 to 6 minutes per side until golden and cooked through (no pink inside). Rest on a board for 5 minutes, then slice.'),
    ('Chicken Alfredo Pasta', 3, 'Cook the fettuccine in salted boiling water for 9 to 11 minutes until al dente. Save a mug of pasta water, then drain.'),
    ('Chicken Alfredo Pasta', 4, 'In the same frying pan, melt the unsalted butter over medium heat and cook the crushed garlic for 30 seconds.'),
    ('Chicken Alfredo Pasta', 5, 'Pour in the double cream and milk, simmer gently for 3 to 4 minutes, then stir in the grated parmesan cheese until the sauce is smooth and thick.'),
    ('Chicken Alfredo Pasta', 6, 'Add the pasta and toss to coat, loosening with a splash of the pasta water if needed. Top with the sliced chicken, chopped parsley and extra black pepper.'),
    ('Homemade Margherita Pizza', 1, 'Mix the flour, yeast, sugar and salt in a large bowl. Add the olive oil and warm water and stir to form a sticky dough.'),
    ('Homemade Margherita Pizza', 2, 'Knead on a floured surface for 8 to 10 minutes until smooth and elastic. Place in an oiled bowl, cover, and leave in a warm place for 1 hour until doubled in size.'),
    ('Homemade Margherita Pizza', 3, 'Meanwhile, make the sauce: crush the garlic and stir it into the chopped tomatoes with the oregano and a pinch of salt. No cooking is needed.'),
    ('Homemade Margherita Pizza', 4, 'Heat your oven to 240°C (465°F) with a baking tray or pizza stone inside. Divide the dough into 4 balls and roll each out to a 25 cm round.'),
    ('Homemade Margherita Pizza', 5, 'Place a dough round on a sheet of baking paper, spread over 3 to 4 tablespoons of sauce, leaving a 1 cm border, and top with torn mozzarella cheese.'),
    ('Homemade Margherita Pizza', 6, 'Slide the pizza with its paper onto the hot tray and bake for 8 to 10 minutes until the crust is golden and the cheese is bubbling. Repeat with the remaining pizzas.'),
    ('Homemade Margherita Pizza', 7, 'Top with fresh basil leaves, slice and serve hot.'),
    ('Beef Lasagne', 1, 'Finely chop the onion and carrot and crush the garlic. Heat the olive oil in a large pan and cook the onion and carrot for 6 minutes until soft, adding the garlic for the last minute.'),
    ('Beef Lasagne', 2, 'Add the minced beef and cook over high heat for 6 to 8 minutes until browned. Stir in the tomato puree, chopped tomatoes, stock, oregano, salt and pepper and simmer gently for 25 minutes until thick.'),
    ('Beef Lasagne', 3, 'Make the white sauce: melt the unsalted butter in a saucepan, stir in the flour and cook for 1 minute. Add the milk a little at a time, whisking, then simmer for 5 minutes until thick. Season with nutmeg, salt and pepper.'),
    ('Beef Lasagne', 4, 'Heat your oven to 180°C (350°F). Spread a thin layer of meat sauce in a 20 x 30 cm baking dish and cover with lasagne sheets.'),
    ('Beef Lasagne', 5, 'Add a layer of meat sauce, then a layer of white sauce, then more sheets. Repeat until everything is used, finishing with white sauce.'),
    ('Beef Lasagne', 6, 'Sprinkle over the grated mozzarella and parmesan cheeses and bake for 40 to 45 minutes until golden and bubbling.'),
    ('Beef Lasagne', 7, 'Rest for 10 minutes before cutting so the layers hold together.'),
    ('Chicken Souvlaki with Tzatziki', 1, 'Cut the chicken thighs into 3 cm cubes. Mix with the olive oil, juice of 1 lemon, 3 crushed garlic cloves, oregano, paprika, salt and pepper. Marinate for at least 30 minutes (up to 8 hours in the fridge).'),
    ('Chicken Souvlaki with Tzatziki', 2, 'Make the tzatziki: grate the cucumber and squeeze out as much water as you can. Mix with the Greek yogurt, 1 crushed garlic clove, dill, juice of half a lemon and a pinch of salt. Chill until needed.'),
    ('Chicken Souvlaki with Tzatziki', 3, 'If using wooden skewers, soak them in water for 20 minutes. Thread the chicken onto the skewers.'),
    ('Chicken Souvlaki with Tzatziki', 4, 'Heat a griddle pan or grill to medium-high. Cook the skewers for 12 to 15 minutes, turning every 3 to 4 minutes, until charred in places and cooked through with no pink inside.'),
    ('Chicken Souvlaki with Tzatziki', 5, 'Slice the tomatoes and red onion. Warm the pita in a dry pan for 30 seconds on each side.'),
    ('Chicken Souvlaki with Tzatziki', 6, 'Serve the chicken in or alongside the pita with sliced tomato, onion, tzatziki and the remaining lemon cut into wedges.'),
    ('Chicken & Prawn Paella', 1, 'Warm the chicken stock and soak the saffron threads in it for 10 minutes. Cut the chicken into bite-sized pieces and season with salt and half the smoked paprika.'),
    ('Chicken & Prawn Paella', 2, 'Heat the olive oil in a wide, shallow pan over medium-high heat. Brown the chicken for 6 to 8 minutes, then set aside.'),
    ('Chicken & Prawn Paella', 3, 'In the same pan cook the chopped onion and red pepper for 5 minutes. Add the crushed garlic, remaining smoked paprika and chopped tomatoes and cook for 3 minutes until thick.'),
    ('Chicken & Prawn Paella', 4, 'Stir in the rice for 1 minute, then pour in the hot saffron stock. Return the chicken, spread everything evenly and simmer without stirring for 15 minutes.'),
    ('Chicken & Prawn Paella', 5, 'Nestle the prawns and peas into the rice, cover with foil and cook for 8 to 10 minutes on low heat until the prawns turn pink and the rice is tender.'),
    ('Chicken & Prawn Paella', 6, 'Turn up the heat for the last 1 to 2 minutes to crisp the bottom layer of rice slightly. Rest for 5 minutes, then scatter with parsley and serve with lemon wedges.'),
    ('Minestrone Soup', 1, 'Dice the onion, carrot, celery, courgette and potato into small, even pieces of about 1 cm, and crush the garlic.'),
    ('Minestrone Soup', 2, 'Heat the olive oil in a large pot over medium heat and cook the onion, carrot and celery for 6 minutes until beginning to soften. Add the garlic and cook for 1 minute.'),
    ('Minestrone Soup', 3, 'Stir in the tomato puree, then add the potato, chopped tomatoes, vegetable stock, oregano, salt and pepper. Bring to the boil, then simmer for 15 minutes.'),
    ('Minestrone Soup', 4, 'Add the courgette, drained cannellini beans and pasta and simmer for 8 to 10 minutes until the pasta is tender.'),
    ('Minestrone Soup', 5, 'Stir in the spinach for 2 minutes until wilted, then taste and adjust the seasoning.'),
    ('Minestrone Soup', 6, 'Ladle into bowls and top with grated parmesan cheese and a drizzle of olive oil.'),
    ('Ratatouille', 1, 'Cut the aubergine, courgettes and peppers into 2 cm cubes. Slice the onion and crush the garlic.'),
    ('Ratatouille', 2, 'Heat 2 tablespoons of olive oil in a large, wide pan over medium-high heat. Fry the aubergine for 6 to 8 minutes until golden, then remove to a plate.'),
    ('Ratatouille', 3, 'Add another tablespoon of oil and fry the courgettes for 4 minutes until lightly browned, then remove to the plate.'),
    ('Ratatouille', 4, 'Add the remaining oil and cook the onion and peppers for 6 minutes until soft. Add the garlic and tomato puree and cook for 1 minute.'),
    ('Ratatouille', 5, 'Pour in the chopped tomatoes and add the thyme, bay leaf, salt and pepper. Return the aubergine and courgettes to the pan.'),
    ('Ratatouille', 6, 'Cover and simmer on low heat for 25 minutes, stirring occasionally, until the vegetables are tender and the sauce has thickened. Remove the bay leaf, stir in torn basil and serve warm or at room temperature.'),
    ('Tuna Niçoise Salad', 1, 'Boil the baby potatoes in salted water for 12 to 15 minutes until tender. Add the green beans for the last 3 minutes, then drain and cool under cold running water.'),
    ('Tuna Niçoise Salad', 2, 'Boil the eggs in a separate pan for 8 minutes, cool in cold water, then peel and quarter them.'),
    ('Tuna Niçoise Salad', 3, 'Make the dressing by whisking the olive oil, lemon juice, English mustard, honey, salt and pepper together in a small jar.'),
    ('Tuna Niçoise Salad', 4, 'Halve the potatoes, halve the cherry tomatoes and thinly slice the red onion. Separate the lettuce leaves.'),
    ('Tuna Niçoise Salad', 5, 'Arrange the lettuce on a large platter and top with the potatoes, green beans, tomatoes, onion and olives.'),
    ('Tuna Niçoise Salad', 6, 'Flake the drained tuna over the top, add the eggs, drizzle over the dressing and serve.'),
    ('Beef Tacos', 1, 'Finely chop the onion and crush the garlic. Shred the lettuce, dice the tomatoes and grate the cheddar cheese.'),
    ('Beef Tacos', 2, 'Heat the oil in a large frying pan over medium heat and cook the onion for 4 minutes until soft. Add the garlic and cook for 30 seconds.'),
    ('Beef Tacos', 3, 'Add the minced beef and cook over high heat for 6 to 8 minutes, breaking it up, until browned.'),
    ('Beef Tacos', 4, 'Stir in the cumin, smoked paprika, oregano, chilli powder, tomato puree and salt, then add the water. Simmer for 5 minutes until the sauce is thick and clings to the meat.'),
    ('Beef Tacos', 5, 'Warm the tortillas for 20 to 30 seconds per side in a dry pan.'),
    ('Beef Tacos', 6, 'Fill each tortilla with beef, lettuce, tomato, cheese and a spoonful of soured cream. Serve with lime wedges.'),
    ('Shepherd''s Pie with Lamb', 1, 'Peel and chop the potatoes into chunks and boil in salted water for 15 to 20 minutes until completely tender. Drain and mash with the unsalted butter, milk, salt and pepper until smooth.'),
    ('Shepherd''s Pie with Lamb', 2, 'Meanwhile, finely chop the onion and carrots and crush the garlic. Heat the olive oil in a large pan and cook the onion and carrots for 8 minutes.'),
    ('Shepherd''s Pie with Lamb', 3, 'Add the minced lamb and garlic and cook over high heat for 6 to 8 minutes until well browned. Stir in the tomato puree and flour and cook for 1 minute.'),
    ('Shepherd''s Pie with Lamb', 4, 'Pour in the lamb stock, add the thyme and bay leaf, and simmer for 15 to 20 minutes until thick. Stir in the peas and remove the bay leaf.'),
    ('Shepherd''s Pie with Lamb', 5, 'Heat your oven to 200°C (400°F). Spoon the lamb mixture into a 2 litre baking dish and spread the mash on top, then rough up the surface with a fork.'),
    ('Shepherd''s Pie with Lamb', 6, 'Bake for 25 to 30 minutes until the top is golden and the filling is bubbling at the edges. Rest for 5 minutes before serving.'),
    ('Oven-Baked Fish and Chips', 1, 'Heat your oven to 220°C (425°F). Cut the potatoes into thick chips, dry them well with a tea towel and toss with 2 tablespoons of oil, salt and pepper on a large baking tray.'),
    ('Oven-Baked Fish and Chips', 2, 'Roast the chips for 15 minutes, turn them over, then roast for another 20 to 25 minutes until golden and crisp.'),
    ('Oven-Baked Fish and Chips', 3, 'Set up three shallow dishes: flour seasoned with salt and pepper, beaten eggs, and panko breadcrumbs mixed with the paprika and the remaining oil.'),
    ('Oven-Baked Fish and Chips', 4, 'Pat the cod dry. Coat each fillet in flour, then egg, then breadcrumbs, pressing the crumbs on firmly.'),
    ('Oven-Baked Fish and Chips', 5, 'Place the fish on a lined tray and bake for 15 to 18 minutes, until the coating is golden and the fish flakes easily and is opaque all the way through.'),
    ('Oven-Baked Fish and Chips', 6, 'Boil the peas for 3 minutes, drain, then lightly crush with the butter, chopped mint, salt and pepper.'),
    ('Oven-Baked Fish and Chips', 7, 'Serve the fish with the chips, minty peas and lemon wedges.'),
    ('Homemade Beef Burgers', 1, 'Grate the onion finely. Mix it gently with the minced beef, garlic powder, black pepper and salt, handling the meat as little as possible.'),
    ('Homemade Beef Burgers', 2, 'Divide into 4 equal portions and shape each into a patty about 2 cm thick. Press a shallow dimple into the centre of each and chill for 15 minutes.'),
    ('Homemade Beef Burgers', 3, 'Heat the oil in a large frying pan or griddle over medium-high heat. Cook the burgers for 4 to 5 minutes per side until deep brown and cooked through with no pink inside.'),
    ('Homemade Beef Burgers', 4, 'Place a slice of cheddar on each burger for the last minute of cooking and cover the pan so the cheese melts.'),
    ('Homemade Beef Burgers', 5, 'Split the buns, spread with the unsalted butter and toast them cut-side down in a dry pan for 1 to 2 minutes until golden.'),
    ('Homemade Beef Burgers', 6, 'Build each burger with lettuce, the cheese-topped patty, sliced tomato, pickles, ketchup and mayonnaise and serve straight away.'),
    ('Chicken Fajitas', 1, 'Slice the chicken breast into thin strips. Mix with 1 tablespoon of oil, the cumin, smoked paprika, garlic powder, oregano, chilli powder, juice of 1 lime and a good pinch of salt. Leave to marinate for 15 minutes.'),
    ('Chicken Fajitas', 2, 'Slice the peppers and red onions into thin strips.'),
    ('Chicken Fajitas', 3, 'Make quick guacamole by mashing the avocados with the juice of half a lime, a pinch of salt and chopped coriander.'),
    ('Chicken Fajitas', 4, 'Heat the remaining oil in a large frying pan over high heat. Cook the chicken for 6 to 7 minutes until browned and cooked through with no pink inside, then remove to a plate.'),
    ('Chicken Fajitas', 5, 'Add the peppers and onions to the hot pan and cook for 5 minutes until softened with charred edges. Return the chicken to the pan and toss together.'),
    ('Chicken Fajitas', 6, 'Warm the tortillas for 20 seconds per side in a dry pan. Serve the fajita mix at the table with the tortillas, guacamole, soured cream and the remaining lime in wedges.'),
    ('Jerk Chicken with Rice and Peas', 1, 'Blend the spring onions, garlic, ginger, deseeded scotch bonnet, thyme, allspice, cinnamon, nutmeg, soy sauce, juice of 2 limes, brown sugar and 1 tablespoon of oil into a thick paste.'),
    ('Jerk Chicken with Rice and Peas', 2, 'Score the chicken skin and rub the paste all over. Cover and marinate in the fridge for at least 2 hours, or overnight for the best flavour.'),
    ('Jerk Chicken with Rice and Peas', 3, 'Heat your oven to 200°C (400°F). Place the chicken on a rack over a baking tray and roast for 45 to 50 minutes, turning once halfway, until charred and cooked through with clear juices.'),
    ('Jerk Chicken with Rice and Peas', 4, 'Meanwhile, rinse the rice until the water runs clear. Put it in a pot with the coconut milk, water, salt and the drained kidney beans.'),
    ('Jerk Chicken with Rice and Peas', 5, 'Bring to the boil, cover, reduce to the lowest heat and cook for 15 minutes without lifting the lid. Rest, covered, for 5 minutes and fluff with a fork.'),
    ('Jerk Chicken with Rice and Peas', 6, 'Rest the chicken for 5 minutes and serve with the rice and peas.'),
    ('Pão de Queijo (Cheese Bread)', 1, 'Heat your oven to 200°C (400°F) and line a baking tray with baking paper.'),
    ('Pão de Queijo (Cheese Bread)', 2, 'Put the milk, oil, water and salt in a saucepan and bring just to the boil.'),
    ('Pão de Queijo (Cheese Bread)', 3, 'Place the tapioca starch in a large bowl and pour the hot liquid over it. Stir with a spoon until combined, then leave to cool for 10 minutes.'),
    ('Pão de Queijo (Cheese Bread)', 4, 'Add the egg, grated mozzarella and grated parmesan cheeses and knead with oiled hands until you have a sticky, stretchy dough.'),
    ('Pão de Queijo (Cheese Bread)', 5, 'Roll the dough into 20 balls of about 3 cm and place them 4 cm apart on the tray.'),
    ('Pão de Queijo (Cheese Bread)', 6, 'Bake for 20 to 25 minutes until puffed and pale golden. Serve warm.'),
    ('Banana Bread', 1, 'Heat your oven to 175°C (350°F). Grease and line a 900 g (2 lb) loaf tin with baking paper.'),
    ('Banana Bread', 2, 'Melt the unsalted butter and let it cool slightly. Mash the bananas in a large bowl until almost smooth.'),
    ('Banana Bread', 3, 'Stir the melted butter, brown sugar, eggs and vanilla powder into the bananas until well mixed.'),
    ('Banana Bread', 4, 'Sift the flour, baking soda, salt and cinnamon over the banana mixture and fold gently until just combined. Fold in the chopped walnuts.'),
    ('Banana Bread', 5, 'Pour the batter into the tin and bake for 50 to 55 minutes, until a skewer pushed into the centre comes out clean. Cover with foil if the top browns too quickly.'),
    ('Banana Bread', 6, 'Cool in the tin for 10 minutes, then lift out onto a wire rack and cool completely before slicing.')
    ) AS v(recipe, num, txt)
  ) x
  WHERE x.recipe_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.recipe_steps s WHERE s.recipe_id = x.recipe_id AND s.step_number = x.num);

  INSERT INTO public.recipe_tips (recipe_id, tip, display_order)
  SELECT x.recipe_id, x.txt, x.ord FROM (
    SELECT (SELECT id FROM public.recipes WHERE lower(name) = lower(v.recipe) LIMIT 1) AS recipe_id, v.txt, v.ord
    FROM (VALUES
    ('Shakshuka', 'Add crumbled feta in the last two minutes for extra richness.', 1),
    ('Ful Medames', 'A boiled egg and some sliced cucumber make this a complete breakfast.', 1),
    ('Menemen', 'Take it off the heat while it still looks slightly wet — it keeps cooking.', 1),
    ('Za''atar Manakish', 'Serve with labneh, cucumber, tomato and fresh mint.', 1),
    ('Date & Tahini Overnight Oats', 'Slow-release oats and dates keep you full through a long fast.', 1),
    ('Lentil Soup (Shorbat Adas)', 'Freezes well for up to 3 months — make a double batch before Ramadan.', 1),
    ('Chicken Shawarma Wraps', 'Toast the rolled wraps in a dry pan for a crisp outside.', 1),
    ('Fattoush Salad', 'Add the pita at the last moment so it stays crunchy.', 1),
    ('Falafel with Tahini Sauce', 'If the mixture won’t hold, chill it for 30 minutes before shaping.', 1),
    ('Chicken Biryani', 'Seal the lid with foil for the dum step so the steam stays in.', 1),
    ('Moroccan Chicken Tagine with Olives and Lemon', 'No preserved lemon? Use the zest of one lemon plus a squeeze of juice at the end.', 1),
    ('Lamb Kofta with Yogurt Sauce', 'Wet your hands while shaping so the mixture doesn’t stick.', 1),
    ('Chicken Karahi', 'Peel the tomatoes for a smoother sauce.', 1),
    ('Daal Tadka', 'Serve with basmati rice or roti and a squeeze of lemon.', 1),
    ('Nasi Lemak', 'Fried chicken (ayam goreng) turns this into a feast.', 1),
    ('Beef Rendang', 'Rendang tastes even better the next day.', 1),
    ('Jollof Rice with Chicken', 'Letting the bottom catch slightly gives the prized smoky ‘party jollof’ flavour.', 1),
    ('Somali Chicken Suqaar', 'Xawaash is a blend of cumin, coriander, black pepper, cardamom, cinnamon and turmeric.', 1),
    ('Mujaddara', 'A simple tomato-cucumber salad is the classic side.', 1),
    ('Maqluba', 'Tap the bottom of the pot before lifting to help it release cleanly.', 1),
    ('Harira', 'Serve with dates and chebakia for a classic Moroccan iftar.', 1),
    ('Classic Hummus', 'Keeps for 4 days in the fridge.', 1),
    ('Date & Nut Energy Balls', 'Store in the fridge for up to a week.', 1),
    ('Basbousa', 'Hot cake + cool syrup is the secret to a moist basbousa.', 1),
    ('Kheer (Rice Pudding)', 'Stir the bottom of the pan regularly so the milk doesn’t catch.', 1),
    ('Lemon Herb Baked Salmon', 'Thicker fillets may need 2–3 more minutes.', 1),
    ('Chicken Kabsa', 'Serve with a simple tomato salsa (daqoos) on the side.', 1),
    ('Msemen with Honey', 'Plenty of oil on your hands and the work surface is the secret to stretching the dough thin without tearing.', 1),
    ('Baghrir (Thousand-Hole Pancakes)', 'If no holes appear, the batter is too thick; whisk in a splash of warm water.', 1),
    ('Bissara (Fava Bean Soup)', 'Bissara thickens as it cools, so loosen it with hot water when reheating.', 1),
    ('Lamb Tagine with Prunes and Almonds', 'Cooking on the lowest possible heat keeps the lamb tender; add a splash of water if the sauce dries out.', 1),
    ('Chicken Pastilla', 'Keep unused filo covered with a damp tea towel so it does not dry out and crack.', 1),
    ('Couscous with Seven Vegetables', 'Add the softer vegetables last so nothing turns to mush.', 1),
    ('Zaalouk (Aubergine Salad)', 'It tastes even better the next day, once the flavours have settled.', 1),
    ('Kefta Mkaouara (Meatball Tagine with Eggs)', 'Wet your hands when shaping the meatballs so the meat does not stick.', 1),
    ('Chorba Frik (Lamb & Freekeh Soup)', 'The soup thickens as it stands; add a little hot water to loosen it.', 1),
    ('Mhadjeb (Stuffed Semolina Flatbread)', 'Make sure the filling is dry, otherwise the dough will tear and turn soggy.', 1),
    ('Chtitha Djej (Spiced Chicken Stew)', 'Reduce the harissa to 1 tsp for a family-friendly mild version.', 1),
    ('Makrout (Date Semolina Cookies)', 'Fry in small batches so the oil temperature stays steady and the cookies do not turn greasy.', 1),
    ('Lablabi (Chickpea Soup)', 'Use bread that is a day or two old so it soaks up the broth without disintegrating.', 1),
    ('Brik à l''Oeuf (Egg Brik)', 'Work quickly once the egg is added, or it will soak through the pastry.', 1),
    ('Tunisian Fish Couscous', 'Use thick fillets such as cod, hake or monkfish so the fish holds together in the broth.', 1),
    ('Sharba Libiya (Lamb & Orzo Soup)', 'Orzo keeps absorbing broth, so add a little hot water when reheating leftovers.', 1),
    ('Koshari', 'Fry the onions until properly dark; they will crisp further as they cool.', 1),
    ('Molokhia with Chicken', 'Do not boil molokhia vigorously or cover it, as it can turn stringy and dull.', 1),
    ('Hawawshi (Spiced Beef Bread)', 'Spread the filling thinly and evenly so it cooks through before the bread burns.', 1),
    ('Om Ali (Bread Pudding)', 'Serve it straight from the oven; the pastry on top stays crunchy while the layers underneath turn creamy.', 1),
    ('Eggah (Herb Omelette)', 'Eggah keeps well in the fridge and is great cold in a sandwich.', 1),
    ('Mullah Bamia (Okra Stew)', 'Do not stir the okra too much; it will become slimy if broken up.', 1),
    ('Labneh with Za''atar and Olive Oil', 'Make the labneh a day or two ahead; it keeps well in the fridge for up to a week.', 1),
    ('Fatteh Hummus', 'Assemble just before serving so the pita keeps some crunch.', 1),
    ('Manaqish Jibneh (Cheese Flatbread)', 'No akkawi? Use all mozzarella with a pinch of salt.', 1),
    ('Mfarakeh (Potato & Egg Scramble)', 'Parboil the potatoes for 5 minutes first if you want them to cook faster.', 1),
    ('Tabbouleh', 'Dress it at the last minute so the parsley stays bright green.', 1),
    ('Warak Enab (Stuffed Vine Leaves)', 'Roll them thin and tight; loose rolls fall apart while cooking.', 1),
    ('Adas bi Hamod (Lentil & Chard Soup)', 'Mash a few lentils against the pot side to thicken the soup naturally.', 1),
    ('Arayes (Grilled Meat-Stuffed Pita)', 'Keep the meat layer thin so it cooks through before the bread burns.', 1),
    ('Sfeeha (Open Meat Pies)', 'Freeze unbaked pies on a tray, then bake straight from frozen for 18 minutes.', 1),
    ('Kibbeh bil Sanieh (Baked Kibbeh)', 'Keep your hands wet when pressing the paste so it does not stick.', 1),
    ('Shish Tawook', 'Thighs work well too and stay juicier if you are worried about dryness.', 1),
