  ) x
  WHERE x.recipe_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.recipe_tips t WHERE t.recipe_id = x.recipe_id AND t.display_order = x.ord);

  INSERT INTO public.recipe_allergens (recipe_id, allergen_id)
  SELECT DISTINCT x.recipe_id, x.allergen_id FROM (
    SELECT (SELECT id FROM public.recipes WHERE lower(name) = lower(v.recipe) LIMIT 1) AS recipe_id,
           (SELECT id FROM public.allergens a WHERE lower(a.name) = ANY(CASE v.allergen WHEN 'Gluten' THEN ARRAY['gluten', 'gluten', 'wheat', 'coeliac', 'celiac', 'barley', 'rye'] WHEN 'Dairy' THEN ARRAY['dairy', 'dairy', 'milk', 'lactose', 'cow milk'] WHEN 'Eggs' THEN ARRAY['eggs', 'egg', 'eggs'] WHEN 'Tree nuts' THEN ARRAY['tree nuts', 'tree nuts', 'tree nut', 'nuts', 'nut'] WHEN 'Peanuts' THEN ARRAY['peanuts', 'peanut', 'peanuts', 'groundnut', 'groundnuts'] WHEN 'Sesame' THEN ARRAY['sesame', 'sesame'] WHEN 'Fish' THEN ARRAY['fish', 'fish'] WHEN 'Shellfish' THEN ARRAY['shellfish', 'shellfish', 'crustaceans', 'molluscs', 'mollusks', 'seafood'] WHEN 'Soy' THEN ARRAY['soy', 'soy', 'soya', 'soybean', 'soybeans'] WHEN 'Mustard' THEN ARRAY['mustard', 'mustard'] WHEN 'Celery' THEN ARRAY['celery', 'celery', 'celeriac'] ELSE ARRAY[lower(v.allergen)] END) LIMIT 1) AS allergen_id
